import { t } from "../types";
import type { BookSet } from "../book-types";

/** Sabi Nila vs Sabi ni Lord: the book, one chapter per lesson. */
export const BOOK: BookSet = {
  "c-follow-vs-guard-heart": {
    epigraph: {
      text: t(
        "Keep your heart with all vigilance, for from it flow the springs of life.",
        "Ingatan mo ang iyong puso nang buong pagbabantay, sapagkat mula rito dumadaloy ang mga bukal ng buhay."
      ),
      ref: t("Proverbs 4:23", "Kawikaan 4:23"),
    },
    opening: [
      t(
        "It is past midnight in a bedspace in Riyadh. Six women share the room, and five of them are asleep. The sixth lies with her face lit by her phone. A message has just come in from a man who is not her husband: “Gising ka pa?” Her heart answers before her mind does. It is beating fast, and it is saying something that sounds very much like her own voice. You deserve to be happy. Nobody back home listens to you like this. Just this once.",
        "Lampas hatinggabi na sa isang bedspace sa Riyadh. Anim na babae ang magkakasama sa kuwarto, at tulog na ang lima. Ang ikaanim ay nakahiga, naiilawan ng cellphone ang mukha. May dumating na mensahe mula sa isang lalaking hindi niya asawa: “Gising ka pa?” Nauna pang sumagot ang puso niya kaysa sa isip niya. Mabilis ang tibok nito, at may sinasabi itong kaboses na kaboses niya. Deserve mo namang sumaya. Walang nakikinig sa iyo nang ganito sa Pilipinas. Ngayon lang naman."
      ),
      t(
        "If you have watched enough movies, you already know what the script says next. The music swells, and somebody tells her to follow her heart. Our songs say it, our teleseryes say it, and the posts on our feeds say it in pretty letters over a sunset. Follow your heart. It sounds like freedom. It sounds like being true to yourself.",
        "Kung marami ka nang napanood na pelikula, alam mo na ang kasunod sa script. Lalakas ang tugtog, at may magsasabi sa kanya na sundin ang puso niya. Sinasabi ito ng mga kanta natin, ng mga teleserye natin, at ng mga post sa feed natin na nakasulat nang maganda sa ibabaw ng paglubog ng araw. Sundin mo ang puso mo. Parang kalayaan pakinggan. Parang pagiging totoo sa sarili."
      ),
      t(
        "But let me ask you a question that may hurt a little, and I ask it as a pastor who has sat with many people after the music stopped. Who told you that your heart was a compass? Where did you learn that the loudest feeling in the room must be the truest one? The Word of God, which has never flattered anyone, says something very different.",
        "Pero hayaan mong magtanong ako ng isang bagay na baka medyo masakit, at itinatanong ko ito bilang pastor na maraming beses nang naupo sa tabi ng mga tao matapos tumigil ang tugtog. Sino ang nagsabi sa iyo na kompas ang puso mo? Saan mo natutunan na ang pinakamalakas na damdamin sa loob mo ang siya ring pinakatotoo? Ang Salita ng Diyos, na kailanman ay hindi nambola ng sinuman, ay may ibang sinasabi."
      ),
    ],
    sections: [
      {
        heading: t("The voice that sounds like your own", "Ang tinig na kaboses mo"),
        body: [
          t(
            "Jeremiah wrote the most uncomfortable sentence about the human heart in all of Scripture: “The heart is deceitful above all things, and desperately sick; who can understand it?” (Jeremiah 17:9). He did not write it in a book of philosophy. He wrote it to a nation about to lose everything. Judah had altars on the hills and idols under every green tree, and the people were sure they were fine. The chapter opens with God saying their sin was written “with a pen of iron” on the tablet of their heart (17:1). It was not a stain on the surface. It was engraved.",
            "Si Jeremias ang sumulat ng pinakamahirap tanggaping pangungusap tungkol sa puso ng tao sa buong Kasulatan: “Ang puso ay mapanlinlang higit sa lahat ng bagay, at lubhang may sakit; sino ang makauunawa nito?” (Jeremias 17:9). Hindi niya ito isinulat sa isang aklat ng pilosopiya. Isinulat niya ito sa isang bansang malapit nang mawalan ng lahat. May mga altar ang Juda sa mga burol at mga diyus-diyosan sa ilalim ng bawat luntiang punongkahoy, at sigurado ang mga tao na ayos lang sila. Nagsisimula ang kabanata sa pagsasabi ng Diyos na ang kasalanan nila ay nakasulat “sa panulat na bakal” sa tapyas ng kanilang puso (t. 1). Hindi ito mantsa sa ibabaw. Nakaukit ito."
          ),
          t(
            "Read the verses just before verse 9 and you will see what the passage is really about. “Cursed is the man who trusts in man and makes flesh his strength, whose heart turns away from the Lord. He is like a shrub in the desert” (17:5-6). Then: “Blessed is the man who trusts in the Lord... He is like a tree planted by water, that sends out its roots by the stream” (17:7-8). The question of the chapter is not whether you have feelings. It is where your roots go. A heart rooted in itself becomes a dry shrub in salt land, however green it looks for a season.",
            "Basahin mo ang mga talatang nauna sa talata 9 at makikita mo kung tungkol saan talaga ang bahaging ito. “Sumpain ang taong nagtitiwala sa tao at ginagawang lakas ang laman, na ang puso ay lumalayo sa Panginoon. Siya'y gaya ng mababang palumpong sa ilang” (t. 5-6). Pagkatapos: “Mapalad ang taong nagtitiwala sa Panginoon... Siya'y gaya ng punong itinanim sa tabi ng tubig, na nag-uugat sa tabi ng batis” (t. 7-8). Ang tanong ng kabanata ay hindi kung may damdamin ka. Ang tanong ay kung saan nakaugat ang buhay mo. Ang pusong nakaugat sa sarili ay nagiging tuyong palumpong sa maalat na lupa, gaano man ito kaberde sa loob ng isang panahon."
          ),
          t(
            "Here is why the heart is such a dangerous guide. It deceives us in our own voice. When Eve was tempted, at least there was a serpent to look at. But when the heart tempts, it does not sound like an enemy. It sounds like you. It uses your wounds, your loneliness, your sense of what is fair. It whispers, “This is who you really are.” That is how so many people have walked into ruin with complete sincerity. They were not lying to anyone. They were being lied to, from the inside.",
            "Ito ang dahilan kung bakit mapanganib na gabay ang puso. Nanlilinlang ito gamit ang sarili mong boses. Nang tuksuhin si Eva, may ahas man lang na nakikita. Pero kapag ang puso ang nanunukso, hindi ito tunog kaaway. Tunog ikaw. Ginagamit nito ang mga sugat mo, ang kalungkutan mo, ang pakiramdam mo kung ano ang patas. Bumubulong ito, “Ito ang tunay na ikaw.” Ganyan pumasok ang napakaraming tao sa pagkawasak nang buong katapatan. Hindi sila nagsisinungaling kaninuman. Sila ang pinagsisinungalingan, mula sa loob."
          ),
          t(
            "And yet the very next verse carries a mercy: “I the Lord search the heart and test the mind” (17:10). There is Someone who can read what you cannot. You do not have to understand your own heart before you come to God. You only have to bring it to the One who does.",
            "Pero ang kasunod na talata ay may dalang awa: “Ako, ang Panginoon, ang sumisiyasat sa puso at sumusubok sa isip” (t. 10). May Isang nakababasa ng hindi mo mabasa. Hindi mo kailangang maunawaan muna ang sarili mong puso bago ka lumapit sa Diyos. Kailangan mo lang itong dalhin sa Kanya na nakauunawa rito."
          ),
        ],
      },
      {
        heading: t("The man who followed his eyes", "Ang lalaking sumunod sa kanyang mga mata"),
        body: [
          t(
            "If you want to see what “follow your heart” looks like when it grows up, read the life of Samson. He was set apart before he was born, a Nazirite, with a strength that came from the Spirit of the Lord. Yet his story is the story of a man who let his eyes lead him. When he saw a Philistine woman in Timnah, his parents begged him to think again. His answer could be the slogan of our generation: “Get her for me, for she is right in my eyes” (Judges 14:3).",
            "Kung gusto mong makita kung ano ang hitsura ng “sundin mo ang puso mo” kapag lumaki na ito, basahin mo ang buhay ni Samson. Ibinukod na siya bago pa ipanganak, isang Nazareo, na may lakas na mula sa Espiritu ng Panginoon. Pero ang kuwento niya ay kuwento ng isang lalaking hinayaang mga mata niya ang manguna. Nang makakita siya ng isang babaeng Filisteo sa Timnah, nakiusap ang mga magulang niya na pag-isipan niya ito. Ang sagot niya ay puwedeng maging slogan ng henerasyon natin: “Kunin ninyo siya para sa akin, sapagkat siya ang tama sa aking paningin” (Hukom 14:3)."
          ),
          t(
            "Right in my eyes. Remember that phrase, because the book of Judges ends with it: “In those days there was no king in Israel. Everyone did what was right in his own eyes” (Judges 21:25). Samson was not an exception to his generation. He was its portrait. He went down to Gaza. He went to the valley of Sorek and to Delilah, who asked him three times for the secret of his strength and showed him three times that she meant to destroy him. His heart told him he could handle it. The heart always does.",
            "Tama sa aking paningin. Tandaan mo ang pariralang iyan, dahil doon nagtatapos ang aklat ng Hukom: “Nang mga araw na iyon ay walang hari sa Israel. Ginagawa ng bawat isa ang tama sa sarili niyang paningin” (Hukom 21:25). Hindi naiiba si Samson sa henerasyon niya. Siya ang larawan nito. Bumaba siya sa Gaza. Pumunta siya sa libis ng Sorek at kay Delila, na tatlong beses nagtanong sa sikreto ng lakas niya at tatlong beses ding nagpakita na gusto siyang ipahamak. Sinabi ng puso niya na kaya niya iyon. Laging ganyan ang sinasabi ng puso."
          ),
          t(
            "Then came the terrible irony. The man who followed his eyes lost his eyes. The Philistines gouged them out, bound him with bronze shackles, and set him grinding grain in the prison like an ox (Judges 16:21). Picture him there, walking in circles in the dark, the strongest man in Israel pushing a millstone. Sin always promises a view and pays you in blindness.",
            "At dumating ang nakapanghihilakbot na kabalintunaan. Ang lalaking sumunod sa kanyang mga mata ay nawalan ng mga mata. Dinukit ito ng mga Filisteo, iginapos siya ng tansong kadena, at pinagiling siya ng butil sa bilangguan na parang baka (Hukom 16:21). Isipin mo siya roon, paikot-ikot sa dilim, ang pinakamalakas na lalaki sa Israel na nagtutulak ng gilingang bato. Laging nangangako ng magandang tanawin ang kasalanan, pero pagkabulag ang ibinabayad nito."
          ),
          t(
            "But do not close the book too quickly, because Scripture adds a quiet line: “But the hair of his head began to grow again after it had been shaved” (16:22). Even there, God was not finished. At the very end Samson prayed, “O Lord God, please remember me” (16:28). My friend, if you have already followed your heart into the prison house, hear me: the God who remembered Samson remembers you. But how much better to learn this before the shackles than after them.",
            "Pero huwag mo munang isara ang aklat, dahil may idinagdag na tahimik na linya ang Kasulatan: “Ngunit nagsimulang tumubo muli ang buhok sa kanyang ulo matapos itong ahitin” (16:22). Kahit doon, hindi pa tapos ang Diyos. Sa pinakadulo, nanalangin si Samson, “O Panginoong Diyos, alalahanin Mo ako” (16:28). Kapatid, kung nasundan mo na ang puso mo hanggang sa bilangguan, pakinggan mo ako: ang Diyos na umalala kay Samson ay umaalala rin sa iyo. Pero mas mabuting matutunan ito bago ang kadena kaysa pagkatapos."
          ),
        ],
      },
      {
        heading: t("A watchman at the gates", "Isang bantay sa mga tarangkahan"),
        body: [
          t(
            "Solomon does not tell his son to follow his heart. He tells him to guard it, and he says it with urgency: “Keep your heart with all vigilance,” or as other translations put it, “Above all else, guard your heart” (Proverbs 4:23). Above all else. Above your career, your savings, your reputation. Why? “For from it flow the springs of life.” Everything you will ever say, choose and become flows out of that one place. Poison the spring and the whole river is sick.",
            "Hindi sinabi ni Solomon sa anak niya na sundin ang puso niya. Sinabi niyang bantayan ito, at sinabi niya ito nang may pagmamadali: “Higit sa lahat ng iyong iniingatan, ingatan mo ang iyong puso” (Kawikaan 4:23). Higit sa lahat. Higit sa karera mo, sa ipon mo, sa pangalan mo. Bakit? “Sapagkat mula rito dumadaloy ang mga bukal ng buhay.” Lahat ng sasabihin mo, pipiliin mo at magiging ikaw ay dumadaloy mula sa iisang lugar na iyon. Lasunin mo ang bukal at magkakasakit ang buong ilog."
          ),
          t(
            "In the old cities a watchman stood on the wall and at the gate. He did not stop the city from living. Merchants came in, families came in, food came in. But he watched. He knew which caravans came from the enemy. He shut the gates at night. That is what it means to guard the heart. It is not to stop feeling. It is to know what you let in, and when.",
            "Sa mga sinaunang lungsod, may bantay na nakatayo sa pader at sa pintuang-bayan. Hindi niya pinipigilang mabuhay ang lungsod. Pumapasok ang mga mangangalakal, ang mga pamilya, ang pagkain. Pero nagbabantay siya. Alam niya kung aling karabana ang galing sa kaaway. Isinasara niya ang pintuan sa gabi. Iyan ang ibig sabihin ng pag-iingat sa puso. Hindi ito pagtigil sa pakiramdam. Ito ay pagkaalam kung ano ang pinapapasok mo, at kailan."
          ),
          t(
            "Look how practical Solomon becomes in the next verses: “Put away from you crooked speech... Let your eyes look directly forward... Ponder the path of your feet” (Proverbs 4:24-26). The mouth, the eyes, the feet. The gates of the heart are not mysterious. They are what you say when you are angry, what you look at when you are alone, where you walk when you are bored. For many of us there is now a fourth gate, and it fits in the palm of the hand.",
            "Tingnan mo kung gaano kapraktikal si Solomon sa mga kasunod na talata: “Ilayo mo sa iyo ang baluktot na pananalita... Ang iyong mga mata ay tumingin nang tuwid sa unahan... Pag-isipan mo ang landas ng iyong mga paa” (Kawikaan 4:24-26). Ang bibig, ang mata, ang paa. Hindi misteryoso ang mga tarangkahan ng puso. Ito ang sinasabi mo kapag galit ka, ang tinitingnan mo kapag mag-isa ka, ang pinupuntahan mo kapag nabuburyo ka. At para sa marami sa atin, may ikaapat nang tarangkahan, at kasya ito sa palad."
          ),
          t(
            "King David did not fall on a busy day. He fell on an idle evening. “In the spring of the year, the time when kings go out to battle,” David stayed in Jerusalem, rose from his couch, and walked on the roof (2 Samuel 11:1-2). Idle, restless, alone, awake too late. Many OFWs know those hours: the rest day with nothing planned, the long night after a hard shift, the payday when the loneliness is loud. A wise watchman knows when the enemy likes to come. Post your guard there.",
            "Hindi bumagsak si Haring David sa isang abalang araw. Bumagsak siya sa isang tamad na gabi. “Sa pagpasok ng taon, sa panahong lumalabas ang mga hari sa digmaan,” nanatili si David sa Jerusalem, bumangon mula sa higaan, at naglakad sa bubungan (2 Samuel 11:1-2). Walang ginagawa, hindi mapakali, mag-isa, gising pa kahit malalim na ang gabi. Kilala ng maraming OFW ang mga oras na iyan: ang day off na walang plano, ang mahabang gabi pagkatapos ng mabigat na shift, ang sweldo-day na ang lakas ng lungkot. Alam ng matalinong bantay kung kailan gustong dumating ng kaaway. Doon ka maglagay ng bantay."
          ),
        ],
      },
      {
        heading: t("Not a colder heart, but a new one", "Hindi mas malamig na puso, kundi bago"),
        body: [
          t(
            "Some of you have heard all this and decided the answer is to become hard. You were hurt by following your heart, so now you trust nothing you feel. You love no one too much. You stopped crying years ago. Beloved, that is not a guarded heart. That is a fortified grave. God never asked you to kill your heart. He promised to replace it.",
            "May ilan sa inyo na nakarinig na nito at nagpasyang ang sagot ay tumigas. Nasaktan ka sa pagsunod sa puso mo, kaya ngayon wala ka nang pinagkakatiwalaang nararamdaman. Wala ka nang minamahal nang sobra. Matagal ka nang hindi umiiyak. Minamahal, hindi iyan pusong nag-iingat. Libingan iyan na may pader. Hindi kailanman hiniling ng Diyos na patayin mo ang puso mo. Nangako Siyang papalitan ito."
          ),
          t(
            "Listen to Ezekiel, speaking to exiles by the rivers of Babylon, people who had followed their hearts all the way into captivity: “I will give you a new heart, and a new spirit I will put within you. And I will remove the heart of stone from your flesh and give you a heart of flesh. And I will put My Spirit within you, and cause you to walk in My statutes” (Ezekiel 36:26-27). Notice who does the work. I will give. I will remove. I will put. This is not a self-improvement program. It is a transplant, and the surgeon is God.",
            "Pakinggan mo si Ezekiel, nagsasalita sa mga bihag sa tabi ng mga ilog ng Babilonia, mga taong sinundan ang puso nila hanggang sa pagkabihag: “Bibigyan Ko kayo ng bagong puso, at isang bagong espiritu ang ilalagay Ko sa inyo. Aalisin Ko ang pusong bato sa inyong laman at bibigyan Ko kayo ng pusong laman. Ilalagay Ko ang Aking Espiritu sa inyo, at palalakarin Ko kayo sa Aking mga tuntunin” (Ezekiel 36:26-27). Pansinin mo kung sino ang gumagawa. Ako ang magbibigay. Ako ang mag-aalis. Ako ang maglalagay. Hindi ito programa ng pagpapabuti sa sarili. Heart transplant ito, at ang Diyos ang siruhano."
          ),
          t(
            "That is why Psalm 37:4 is not the blank check people make it out to be. “Delight yourself in the Lord, and He will give you the desires of your heart.” The order matters. First the delight, then the desires. When you make God your joy, He does something better than granting your wishes. He rewrites them. Slowly you find yourself wanting what He wants: purity where you once wanted thrills, peace where you once wanted revenge, His presence where you once wanted applause.",
            "Kaya hindi blangkong tseke ang Awit 37:4 gaya ng akala ng iba. “Magpakaligaya ka sa Panginoon, at ibibigay Niya sa iyo ang mga hangarin ng iyong puso.” Mahalaga ang pagkakasunod. Una ang kaligayahan sa Kanya, saka ang mga hangarin. Kapag ginawa mong kagalakan ang Diyos, may ginagawa Siyang mas maganda pa kaysa pagbibigay sa mga gusto mo. Isinusulat Niya itong muli. Dahan-dahan, mapapansin mong gusto mo na ang gusto Niya: kalinisan kung saan dati ay kilig ang hanap mo, kapayapaan kung saan dati ay paghihiganti, ang presensya Niya kung saan dati ay palakpak ng tao."
          ),
          t(
            "Even our Lord in Gethsemane did not pretend to have no feelings. He said, “My soul is very sorrowful, even to death” (Matthew 26:38). He fell on His face. He asked whether the cup could pass. And then He said the words every guarded heart must learn: “Nevertheless, not as I will, but as You will” (26:39). Real feelings, honestly told, fully surrendered. That is not a cold heart. It is the warmest heart that ever beat.",
            "Kahit ang Panginoon natin sa Getsemani ay hindi nagkunwaring walang nararamdaman. Sinabi Niya, “Labis na nalulungkot ang Aking kaluluwa, hanggang sa kamatayan” (Mateo 26:38). Nagpatirapa Siya. Itinanong Niya kung puwedeng lumampas ang saro. At saka Niya sinabi ang mga salitang dapat matutunan ng bawat pusong nag-iingat: “Gayunman, huwag ang ayon sa kalooban Ko, kundi ang ayon sa Iyo” (t. 39). Totoong damdamin, tapat na sinabi, lubos na isinuko. Hindi iyan malamig na puso. Iyan ang pinakamainit na pusong tumibok kailanman."
          ),
        ],
      },
      {
        heading: t("How a guarded heart decides", "Paano nagpapasya ang pusong nag-iingat"),
        body: [
          t(
            "So what do you do with a strong feeling about a decision: a relationship, a job offer abroad, a business your cousin keeps pushing, a church you want to leave? Proverbs 3:5-6 gives the posture: “Trust in the Lord with all your heart, and do not lean on your own understanding. In all your ways acknowledge Him, and He will make straight your paths.” Your heart is not thrown away. It is given a job. Its job is to trust.",
            "Kaya ano ang gagawin mo sa isang malakas na damdamin tungkol sa isang desisyon: isang relasyon, isang alok na trabaho sa abroad, isang negosyong ipinipilit ng pinsan mo, isang simbahang gusto mo nang iwan? Ibinibigay ng Kawikaan 3:5-6 ang tamang tindig: “Magtiwala ka sa Panginoon nang buong puso, at huwag kang manalig sa sarili mong pang-unawa. Sa lahat ng iyong mga lakad ay kilalanin mo Siya, at Kanyang itutuwid ang iyong mga landas.” Hindi itinatapon ang puso mo. Binibigyan ito ng trabaho. Ang trabaho nito ay magtiwala."
          ),
          t(
            "Bring the feeling into the light. Tell God plainly what you feel, the way Jesus did. Then open His Word and ask honestly, “What does God say about this?” and not, “Which verse can I find to support what I already want?” Then bring it to people who love God and love you enough to disagree with you. A feeling that cannot survive Scripture and godly counsel never came from the Spirit.",
            "Dalhin mo sa liwanag ang damdamin. Sabihin mo nang diretso sa Diyos ang nararamdaman mo, gaya ng ginawa ni Hesus. Saka mo buksan ang Salita Niya at tapat na itanong, “Ano ang sinasabi ng Diyos tungkol dito?” at hindi, “Anong talata ang mahahanap ko para suportahan ang gusto ko na?” Pagkatapos, dalhin mo ito sa mga taong nagmamahal sa Diyos at nagmamahal sa iyo nang sapat para hindi sumang-ayon sa iyo. Ang damdaming hindi makatatagal sa Kasulatan at sa maka-Diyos na payo ay hindi kailanman nanggaling sa Espiritu."
          ),
          t(
            "And learn the difference between peace and preference. Paul wrote, “Let the peace of Christ rule in your hearts” (Colossians 3:15), and the word for rule is the word for an umpire. Peace is meant to call the game, but it must be Christ's peace, not the relief we feel when we finally decide to do what we wanted all along. Real peace often comes after an obedience that cost you something. Preference comes before it and feels like excitement.",
            "At matutunan mo ang pagkakaiba ng kapayapaan at ng gusto lang. Isinulat ni Pablo, “Hayaang maghari sa inyong mga puso ang kapayapaan ni Cristo” (Colosas 3:15), at ang salitang ginamit para sa maghari ay salita para sa isang referee. Ang kapayapaan ang dapat magpasya, pero dapat kapayapaan ni Cristo, hindi ang ginhawang nararamdaman natin kapag sa wakas ay ginawa na natin ang matagal na nating gusto. Ang tunay na kapayapaan ay madalas dumarating pagkatapos ng pagsunod na may kapalit. Ang gusto lang ay dumarating bago iyon at parang excitement ang pakiramdam."
          ),
          t(
            "If you are the woman in the bedspace in Riyadh, it may look like this. You put the phone face down. You do not reply. Tomorrow you tell a sister in your fellowship the truth, and you call your husband even though the conversation will be awkward. Your heart will protest for a while. Let it. Feelings that are not fed eventually lose their voice. And a heart guarded today will thank you for the rest of your life.",
            "Kung ikaw ang babae sa bedspace sa Riyadh, puwedeng ganito ang hitsura nito. Itataob mo ang cellphone. Hindi ka sasagot. Bukas, sasabihin mo ang totoo sa isang kapatid sa fellowship mo, at tatawagan mo ang asawa mo kahit alam mong magiging ilang ang usapan. Magrereklamo ang puso mo nang ilang panahon. Hayaan mo. Ang damdaming hindi pinapakain ay nawawalan din ng boses. At ang pusong iningatan ngayon ay magpapasalamat sa iyo habang buhay."
          ),
        ],
      },
    ],
    pullQuote: t(
      "The heart deceives us in our own voice; that is why God's voice must become the louder one.",
      "Nanlilinlang ang puso gamit ang sarili nating boses; kaya dapat maging mas malakas ang tinig ng Diyos."
    ),
    pastoralWord: [
      t(
        "Beloved, I do not know what your heart is telling you tonight. Maybe it is pulling you toward someone you should not be with. Maybe it is telling you to quit, to run, to finally say everything you have been holding in. Maybe it has gone quiet and cold because you are tired of being hurt. Whatever it is, do not obey it yet. Bring it first to the One who searches hearts, and pray Psalm 139 with me: “Search me, O God, and know my heart! Try me and know my thoughts! And see if there be any grievous way in me, and lead me in the way everlasting.”",
        "Minamahal, hindi ko alam kung ano ang sinasabi ng puso mo ngayong gabi. Baka hinihila ka nito papunta sa taong hindi mo dapat kasama. Baka sinasabi nitong sumuko ka na, tumakbo ka na, sabihin mo na ang lahat ng matagal mong kinikimkim. Baka tumahimik at lumamig na ito dahil pagod ka nang masaktan. Anuman iyon, huwag mo muna itong sundin. Dalhin mo muna ito sa Kanya na sumisiyasat sa mga puso, at ipanalangin mo kasama ko ang Awit 139: “Siyasatin Mo ako, O Diyos, at kilalanin ang aking puso! Subukin Mo ako at kilalanin ang aking mga isipin! Tingnan Mo kung may anumang masamang lakad sa akin, at akayin Mo ako sa daang walang hanggan.”"
      ),
      t(
        "Then do one thing this week. Find the gate that is least guarded in your life and shut it. Delete the conversation. Unfollow the account. Tell someone the truth. And every morning, before your feelings start talking, give your heart back to God and ask Him to fill it. You were not made to be ruled by your heart. You were made to have a heart ruled by Him, and that is a far freer way to live.",
        "Pagkatapos, gumawa ka ng isang bagay ngayong linggo. Hanapin mo ang tarangkahan sa buhay mo na pinakamahina ang bantay at isara mo ito. Burahin mo ang usapan. I-unfollow mo ang account. Sabihin mo ang totoo sa isang tao. At tuwing umaga, bago magsimulang magsalita ang damdamin mo, ibalik mo ang puso mo sa Diyos at hilingin mong punuin Niya ito. Hindi ka ginawa para pagharian ng puso mo. Ginawa ka para magkaroon ng pusong pinaghaharian Niya, at iyan ang mas malayang paraan ng pamumuhay."
      ),
    ],
    benediction: t(
      "May the Lord who searches the heart guard yours with His peace. May He take away every heart of stone in you and give you a heart that beats for Him. And may every spring that flows from your life run clean and living, for His glory. Amen.",
      "Ingatan nawa ng Panginoong sumisiyasat sa puso ang puso mo sa pamamagitan ng Kanyang kapayapaan. Alisin nawa Niya ang bawat pusong bato sa iyo at bigyan ka ng pusong tumitibok para sa Kanya. At ang bawat bukal na dumadaloy mula sa buhay mo ay maging malinis at buhay, para sa Kanyang kaluwalhatian. Amen."
    ),
  },

  "c-money-vs-provider": {
    epigraph: {
      text: t(
        "The name of the Lord is a strong tower; the righteous man runs into it and is safe.",
        "Ang pangalan ng Panginoon ay matibay na tore; tumatakbo rito ang matuwid at siya'y ligtas."
      ),
      ref: t("Proverbs 18:10", "Kawikaan 18:10"),
    },
    opening: [
      t(
        "Friday afternoon, and the line at the remittance center stretches out the door. Men still in their work uniforms, women holding the hands of their friends, everyone with a slip of paper and a number in their head. Picture one of them, a father from Pangasinan who has worked in the Gulf for eleven years. He watches the exchange rate on the screen the way a farmer watches the sky. He has told himself the same thing every year: “Kapag nakaipon na ako, saka ako magpapahinga. Saka ako uuwi.”",
        "Biyernes ng hapon, at lampas na sa pinto ang pila sa remittance center. Mga lalaking naka-uniporme pa ng trabaho, mga babaeng magkakahawak-kamay, bawat isa may hawak na papel at may numerong nasa isip. Isipin mo ang isa sa kanila, isang tatay na taga-Pangasinan na labing-isang taon nang nagtatrabaho sa Gulf. Binabantayan niya ang palitan sa screen gaya ng pagbabantay ng magsasaka sa langit. Taon-taon, iisa ang sinasabi niya sa sarili: “Kapag nakaipon na ako, saka ako magpapahinga. Saka ako uuwi.”"
      ),
      t(
        "I honor that man. There is nothing small about a father who sweats in the desert so his children can study. But I want to ask him, and I want to ask you, a question that money itself can never answer. How much is enough? At what number will you finally feel safe?",
        "Iginagalang ko ang lalaking iyan. Walang maliit sa isang amang pinapawisan sa disyerto para makapag-aral ang mga anak niya. Pero gusto kong itanong sa kanya, at sa iyo rin, ang isang tanong na hindi kailanman masasagot ng pera. Magkano ang sapat? Sa anong halaga ka sa wakas makararamdam na ligtas ka na?"
      ),
      t(
        "Our culture has a ready answer. “Basta may pera, ligtas ka.” “Pera ang nagpapaikot sa mundo.” But God has another answer, and He gave it in two short verses that stand side by side like two buildings on the same street.",
        "May handang sagot ang kultura natin. “Basta may pera, ligtas ka.” “Pera ang nagpapaikot sa mundo.” Pero may ibang sagot ang Diyos, at ibinigay Niya ito sa dalawang maikling talatang magkatabi na parang dalawang gusali sa iisang kalye."
      ),
    ],
    sections: [
      {
        heading: t("A wall that exists in the imagination", "Pader na nasa guni-guni lamang"),
        body: [
          t(
            "“The name of the Lord is a strong tower; the righteous man runs into it and is safe. A rich man's wealth is his strong city, and like a high wall in his imagination” (Proverbs 18:10-11). Solomon was the richest king Israel ever had. He knew exactly what money could do. And he placed these two refuges next to each other so we would compare them. One is a tower you run into. The other is a wall you imagine.",
            "“Ang pangalan ng Panginoon ay matibay na tore; tumatakbo rito ang matuwid at siya'y ligtas. Ang kayamanan ng mayaman ay kanyang matibay na lungsod, at parang mataas na pader sa kanyang guni-guni” (Kawikaan 18:10-11). Si Solomon ang pinakamayamang haring nagkaroon ang Israel. Alam na alam niya ang kayang gawin ng pera. At pinagtabi niya ang dalawang kanlungang ito para paghambingin natin. Ang isa ay toreng tinatakbuhan mo. Ang isa ay pader na iniisip mo lang."
          ),
          t(
            "Money does build real things. It pays tuition and hospital bills and puts a roof over the family. Scripture never despises honest wealth. But money also builds an illusion, and the illusion is this: that if the wall is high enough, nothing can climb over it. Then the typhoon comes, and the floodwater rises the same in the subdivision as in the squatter area. The diagnosis comes, and the doctor speaks in the same low voice to the rich man as to the poor. The phone rings at three in the morning, and no bank balance can make the news untrue.",
            "May totoong naitatayo ang pera. Nagbabayad ito ng tuition at ng hospital bill at naglalagay ng bubong sa ulo ng pamilya. Hindi kailanman minamaliit ng Kasulatan ang tapat na kayamanan. Pero nagtatayo rin ang pera ng ilusyon, at ito ang ilusyon: na kapag sapat ang taas ng pader, wala nang makaaakyat dito. Saka darating ang bagyo, at pareho ang taas ng baha sa subdivision at sa iskwater. Darating ang diagnosis, at parehong mahina ang boses ng doktor sa mayaman at sa mahirap. Tutunog ang telepono nang alas-tres ng madaling-araw, at walang bank balance na makapagpapabago sa balita."
          ),
          t(
            "Notice the verbs in verse 10. The righteous man runs into the tower. That is what you do when danger comes. You run somewhere. And here is the question that tells you where your security truly lives: when the bad news comes, where do your feet go first? To your savings, your connections, your plan B? Or to the name of the Lord?",
            "Pansinin mo ang mga pandiwa sa talata 10. Tumatakbo ang matuwid papasok sa tore. Iyan ang ginagawa mo kapag dumating ang panganib. Tumatakbo ka sa isang lugar. At ito ang tanong na magsasabi kung saan talaga nakatira ang seguridad mo: kapag dumating ang masamang balita, saan unang pumupunta ang mga paa mo? Sa ipon mo, sa koneksyon mo, sa plan B mo? O sa pangalan ng Panginoon?"
          ),
        ],
      },
      {
        heading: t("Manna does not keep", "Hindi naitatabi ang mana"),
        body: [
          t(
            "When God led Israel out of Egypt, He fed a whole nation in a wilderness with bread from heaven. And He gave them a strange rule: gather enough for today, no more. Some did not listen. They kept extra overnight, just in case, and in the morning “it bred worms and stank” (Exodus 16:20). Only before the Sabbath could they gather double, and that day the bread stayed fresh.",
            "Nang ilabas ng Diyos ang Israel mula sa Egipto, pinakain Niya ang isang buong bansa sa ilang ng tinapay mula sa langit. At binigyan Niya sila ng kakaibang patakaran: mamulot ng sapat para sa araw na iyon, hindi hihigit. May hindi nakinig. Nagtabi sila ng sobra magdamag, baka sakali lang, at kinaumagahan, “inuod ito at bumaho” (Exodo 16:20). Bago lang ng Sabbath sila puwedeng mamulot ng doble, at sa araw na iyon, nanatiling sariwa ang tinapay."
          ),
          t(
            "Why would God do that? Moses later explained it: God “humbled you and let you hunger and fed you with manna... that He might make you know that man does not live by bread alone” (Deuteronomy 8:3). For forty years, every single morning, Israel woke up with an empty pantry and a full promise. God was not being stingy. He was teaching a nation of former slaves to trust a Father.",
            "Bakit iyon gagawin ng Diyos? Ipinaliwanag ito ni Moises kalaunan: “Pinakumbaba ka Niya, hinayaan kang magutom, at pinakain ka ng mana... upang ipakilala sa iyo na hindi lamang sa tinapay nabubuhay ang tao” (Deuteronomio 8:3). Sa loob ng apatnapung taon, tuwing umaga, nagigising ang Israel na walang laman ang taguan pero puno ang pangako. Hindi nagdadamot ang Diyos. Tinuturuan Niya ang isang bansang dating alipin na magtiwala sa isang Ama."
          ),
          t(
            "I am not telling you to stop saving. The same Bible praises the ant that stores food in summer (Proverbs 6:6-8), and Joseph saved Egypt by filling storehouses. Saving is wisdom. But there is a kind of saving that is really hoarding, driven not by wisdom but by fear, and it stinks in the end like Israel's manna. It steals your Sundays, your sleep and your generosity. Jesus taught us to pray, “Give us this day our daily bread” (Matthew 6:11), not, “Give us enough so that we never need to pray again.”",
            "Hindi ko sinasabing tumigil ka sa pag-iipon. Ang Bibliya ring iyan ang pumupuri sa langgam na nag-iimbak ng pagkain sa tag-araw (Kawikaan 6:6-8), at iniligtas ni Jose ang Egipto sa pagpuno ng mga kamalig. Karunungan ang pag-iipon. Pero may uri ng pag-iipon na ang totoo ay pagkamkam, itinutulak hindi ng karunungan kundi ng takot, at bumabaho rin ito sa huli gaya ng mana ng Israel. Ninanakaw nito ang mga Linggo mo, ang tulog mo at ang pagiging mapagbigay mo. Tinuruan tayo ni Hesus na manalangin, “Bigyan Mo kami ngayon ng aming kakanin sa araw-araw” (Mateo 6:11), hindi, “Bigyan Mo kami ng sapat para hindi na namin kailangang manalangin ulit.”"
          ),
        ],
      },
      {
        heading: t("The man who talked to his own soul", "Ang lalaking kinausap ang sarili niyang kaluluwa"),
        body: [
          t(
            "Jesus told a story about a farmer whose land produced a huge harvest (Luke 12:16-21). Read it slowly and you will notice something sad. The man has a problem, and he has a meeting about it, but the only one at the meeting is himself. “What shall I do?... I will do this... I will tear down my barns and build larger ones... And I will say to my soul, ‘Soul, you have ample goods laid up for many years; relax, eat, drink, be merry.’” I, I, my, my. He never thanked God. He never thought of his neighbor.",
            "Nagkuwento si Hesus tungkol sa isang magsasakang umani nang napakarami (Lucas 12:16-21). Basahin mo nang dahan-dahan at may mapapansin kang nakalulungkot. May problema ang lalaki, at nagpulong siya tungkol dito, pero siya lang ang nasa pulong. “Ano ang gagawin ko?... Ito ang gagawin ko... Gigibain ko ang aking mga kamalig at magtatayo ng mas malalaki... At sasabihin ko sa aking kaluluwa, ‘Kaluluwa, marami ka nang naimbak para sa maraming taon; magpahinga ka, kumain, uminom, at magsaya.’” Ako, ako, akin, akin. Hindi siya nagpasalamat sa Diyos. Hindi niya inisip ang kapwa niya."
          ),
          t(
            "Then God spoke, and it was the only time in the story anyone else talks: “Fool! This night your soul is required of you, and the things you have prepared, whose will they be?” He had planned for many years. He had not planned for one night. He had made his barns secure and left his soul exposed.",
            "Saka nagsalita ang Diyos, at iyon lang ang pagkakataon sa kuwento na may ibang nagsalita: “Hangal! Ngayong gabi ay hihingin sa iyo ang iyong kaluluwa, at ang mga inihanda mo, kanino mapupunta ang mga iyon?” Nagplano siya para sa maraming taon. Hindi siya nagplano para sa isang gabi. Siniguro niya ang mga kamalig niya at iniwang bukas ang kaluluwa niya."
          ),
          t(
            "Jesus ends with one line: “So is the one who lays up treasure for himself and is not rich toward God.” There are two kinds of rich in that sentence. You can be rich in barns and bankrupt toward God. And by His grace you can be poor in barns and very rich toward Him. Many Filipino grandmothers who never owned a bank account are among the wealthiest people I can imagine, because their treasure was stored where no flood and no scam could ever reach it.",
            "Nagtapos si Hesus sa isang linya: “Ganyan ang taong nag-iimbak ng kayamanan para sa sarili ngunit hindi mayaman sa Diyos.” Dalawang klase ng mayaman ang nasa pangungusap na iyan. Puwede kang mayaman sa kamalig pero bangkarote sa harap ng Diyos. At sa biyaya Niya, puwede kang mahirap sa kamalig pero napakayaman sa Kanya. Maraming lolang Pilipino na hindi kailanman nagkaroon ng bank account ang kabilang sa pinakamayayamang taong maiisip ko, dahil nakaimbak ang kayamanan nila sa lugar na hindi maaabot ng baha o ng scam."
          ),
        ],
      },
      {
        heading: t("The God who sees ahead", "Ang Diyos na nakakikita nang maaga"),
        body: [
          t(
            "On a mountain in Moriah, an old man climbed with a knife, fire and wood, and his son asked him a question that broke his heart: “Where is the lamb?” Abraham answered, “God will provide for Himself the lamb” (Genesis 22:8). When the moment came, a ram was caught by its horns in a thicket. Abraham named the place “The Lord will provide,” Yahweh Yireh (22:14). The Hebrew word carries the idea of seeing. The God who provides is the God who sees ahead, who had that ram on the mountain before Abraham ever started climbing.",
            "Sa isang bundok sa Moria, umakyat ang isang matandang lalaki na may dalang kutsilyo, apoy at kahoy, at may itinanong ang anak niya na dumurog sa puso niya: “Nasaan ang tupa?” Sumagot si Abraham, “Ang Diyos ang maglalaan ng tupa para sa Kanyang sarili” (Genesis 22:8). Nang dumating ang sandali, may lalaking tupang nasabit ang sungay sa kasukalan. Pinangalanan ni Abraham ang lugar na “Ang Panginoon ang maglalaan,” Yahweh Yireh (t. 14). Ang salitang Hebreo ay may diwa ng pagtingin. Ang Diyos na naglalaan ay ang Diyos na nakakikita nang maaga, na naroon na ang tupang iyon sa bundok bago pa nagsimulang umakyat si Abraham."
          ),
          t(
            "Notice where the provision was found. On the mountain of obedience, not at the bottom of it. Abraham did not receive the ram while he sat at home negotiating with God. Many of us want God to show us the ram first, then we will obey. He usually works the other way.",
            "Pansinin mo kung saan natagpuan ang paglalaan. Sa bundok ng pagsunod, hindi sa paanan nito. Hindi natanggap ni Abraham ang tupa habang nakaupo siya sa bahay at nakikipagtawaran sa Diyos. Marami sa atin ang gustong ipakita muna ng Diyos ang tupa, saka tayo susunod. Kadalasan, kabaligtaran ang paraan Niya."
          ),
          t(
            "David wrote, “Some trust in chariots and some in horses, but we trust in the name of the Lord our God” (Psalm 20:7). Chariots were the armored trucks of the ancient world, the most impressive thing a king could own. David had his share of them. But he refused to let them become his trust. That is the line we must learn to walk: use the chariot, drive the chariot, maintain the chariot, but never kneel to the chariot.",
            "Isinulat ni David, “Ang ilan ay nagtitiwala sa mga karwahe at ang ilan sa mga kabayo, ngunit kami ay nagtitiwala sa pangalan ng Panginoon naming Diyos” (Awit 20:7). Ang mga karwahe ang armored truck ng sinaunang mundo, ang pinakakahanga-hangang maaaring ariin ng isang hari. May mga karwahe rin si David. Pero tumanggi siyang gawin itong tiwala niya. Iyan ang linyang dapat nating matutunang lakaran: gamitin mo ang karwahe, imaneho mo, alagaan mo, pero huwag na huwag kang luluhod dito."
          ),
        ],
      },
      {
        heading: t("Open hands", "Bukas na mga palad"),
        body: [
          t(
            "How do you know whether money has become your master? Jesus said plainly, “You cannot serve God and money” (Matthew 6:24). One sign is this: a master decides your schedule. If money tells you when you may go to church, when you may rest, when you may see your children, then money is no longer your servant. Another sign is anxiety. A servant does not keep you awake. A master does.",
            "Paano mo malalaman kung naging panginoon mo na ang pera? Diretsong sinabi ni Hesus, “Hindi kayo maaaring maglingkod sa Diyos at sa pera” (Mateo 6:24). Ito ang isang palatandaan: ang panginoon ang nagpapasya ng iskedyul mo. Kung pera ang nagsasabi kung kailan ka puwedeng magsimba, kailan puwedeng magpahinga, kailan puwedeng makita ang mga anak mo, hindi na lingkod mo ang pera. Isa pang palatandaan ang pagkabalisa. Hindi ka pinupuyat ng lingkod. Ang panginoon, oo."
          ),
          t(
            "The way out is not to hate money but to open your hand. In the 1800s, a German-born pastor named George Müller cared for thousands of orphans in Bristol, England, and he made it his principle never to ask any person for money, only God. He kept careful records of every gift and every answered prayer. His life was not a formula for getting rich. It was a public testimony that the Father who feeds the birds can be trusted with children, and that a man can work hard, keep good books and still sleep in peace.",
            "Ang daan palabas ay hindi pagkamuhi sa pera kundi pagbukas ng palad. Noong 1800s, isang pastor na isinilang sa Alemanya na si George Müller ang nag-alaga ng libu-libong ulila sa Bristol, Inglatera, at ginawa niyang prinsipyo na huwag humingi ng pera sa kahit sinong tao, sa Diyos lamang. Maingat niyang itinala ang bawat kaloob at bawat sagot sa panalangin. Ang buhay niya ay hindi pormula sa pagyaman. Isa itong hayag na patotoo na ang Amang nagpapakain sa mga ibon ay mapagkakatiwalaan sa mga bata, at na puwedeng magsipag ang isang tao, maging maayos sa pagtatala, at makatulog pa rin nang payapa."
          ),
          t(
            "Paul gave Timothy instructions for the rich, and they fit anyone with a monthly salary: do not be haughty, do not “set their hopes on the uncertainty of riches, but on God, who richly provides us with everything to enjoy. They are to do good, to be rich in good works, to be generous and ready to share” (1 Timothy 6:17-18). Enjoy what God gives. Share what God gives. Hope only in the God who gives.",
            "Nagbigay si Pablo kay Timoteo ng bilin para sa mayayaman, at bagay ito sa kahit sinong may buwanang sweldo: huwag maging palalo, huwag “ilagak ang kanilang pag-asa sa kayamanang hindi tiyak, kundi sa Diyos na saganang nagbibigay sa atin ng lahat ng bagay upang ating tamasahin. Gumawa sila ng mabuti, maging mayaman sa mabubuting gawa, maging mapagbigay at handang magbahagi” (1 Timoteo 6:17-18). Tamasahin ang ibinibigay ng Diyos. Ibahagi ang ibinibigay ng Diyos. Sa Diyos lang na nagbibigay umasa."
          ),
          t(
            "For an OFW, open hands may look like a budget that puts giving first, saving second and spending third. It may look like saying a loving no to the cousin's fourth business proposal, and a joyful yes to a kababayan who truly has nothing. It may look like going home sooner than the plan said, because your children need a father more than another year of padala. Money can build a house. Only God can make it a home.",
            "Para sa isang OFW, ang bukas na palad ay puwedeng maging budget na inuuna ang pagbibigay, ikalawa ang pag-iipon, at ikatlo ang paggastos. Puwedeng maging mapagmahal na hindi sa ikaapat na business proposal ng pinsan, at masayang oo sa kababayang wala talagang-wala. Puwedeng maging pag-uwi nang mas maaga kaysa sa plano, dahil mas kailangan ng mga anak mo ang isang ama kaysa sa isa pang taon ng padala. Kayang magtayo ng bahay ng pera. Ang Diyos lang ang makagagawa nitong tahanan."
          ),
        ],
      },
    ],
    pullQuote: t(
      "Money is a faithful servant and a cruel master, and it never announces the day it switches roles.",
      "Tapat na lingkod ang pera at malupit na amo, at hindi nito kailanman ipinaaalam kung kailan ito nagpalit ng papel."
    ),
    pastoralWord: [
      t(
        "My friend, I know the weight you carry. The tuition, the hospital bill of your mother, the utang that never seems to shrink, the relatives who think abroad means rich. I will not tell you that money does not matter. It does. But I will tell you that it was never meant to hold you up. Only the everlasting arms can do that. Tonight, before you check your balance again, open your hands before the Lord and say, “Father, everything I have is Yours. Be my tower.”",
        "Kapatid, alam ko ang bigat na pasan mo. Ang tuition, ang hospital bill ng nanay mo, ang utang na parang hindi lumiliit, ang mga kamag-anak na akala ay mayaman na kapag nasa abroad. Hindi ko sasabihing hindi mahalaga ang pera. Mahalaga ito. Pero sasabihin kong hindi ito kailanman ginawa para buhatin ka. Ang walang hanggang mga bisig lang ang may kakayahan niyon. Ngayong gabi, bago mo tingnan ulit ang balance mo, ibukas mo ang mga palad mo sa harap ng Panginoon at sabihin, “Ama, Iyo ang lahat ng mayroon ako. Ikaw ang maging tore ko.”"
      ),
      t(
        "Then let your trust become visible. Write down three times God provided when you had no way out, and thank Him for each one aloud. Sit with your family, in person or on a video call, and talk honestly about money and priorities. And give something this week that stretches you a little, quietly, as an act of worship. You will discover what every generous believer has discovered: the hand that opens to give is the same hand God fills.",
        "Pagkatapos, hayaan mong makita ang tiwala mo. Isulat mo ang tatlong pagkakataong naglaan ang Diyos noong wala ka nang madaanan, at pasalamatan mo Siya nang malakas sa bawat isa. Umupo kayo bilang pamilya, harapan man o sa video call, at mag-usap nang tapat tungkol sa pera at sa mga priyoridad. At magbigay ka ng isang bagay ngayong linggo na medyo mag-uunat sa iyo, nang tahimik, bilang pagsamba. Matutuklasan mo ang natuklasan ng bawat mapagbigay na mananampalataya: ang kamay na bumubukas para magbigay ang siya ring kamay na pinupuno ng Diyos."
      ),
    ],
    benediction: t(
      "May the Lord who saw the ram before Abraham climbed see every need of your house before it comes. May His name be your strong tower in every storm. And may you work with diligence, give with joy and rest with peace, because your security has a Name. Amen.",
      "Ang Panginoong nakakita sa tupa bago pa umakyat si Abraham ay makita nawa ang bawat pangangailangan ng tahanan mo bago pa ito dumating. Ang pangalan Niya nawa ang maging matibay mong tore sa bawat bagyo. At nawa'y magtrabaho ka nang masipag, magbigay nang may kagalakan, at magpahinga nang may kapayapaan, dahil may Pangalan ang seguridad mo. Amen."
    ),
  },

  "c-yourself-vs-die-to-self": {
    epigraph: {
      text: t(
        "Unless a grain of wheat falls into the earth and dies, it remains alone; but if it dies, it bears much fruit.",
        "Malibang mahulog sa lupa at mamatay ang isang butil ng trigo, mananatili itong nag-iisa; ngunit kung mamatay ito, magbubunga ito nang marami."
      ),
      ref: t("John 12:24", "Juan 12:24"),
    },
    opening: [
      t(
        "Go to any province before planting season and you will find the binhi, the seed grain, kept in sacks in a dry corner of the house. Those sacks are precious. A family may go hungry before they eat the seed, because they know that seed is next year's harvest. But here is the strange thing every farmer understands. As long as the grain stays safe in the sack, it will never become anything more than a grain. It has to leave the sack. It has to go into the wet, dark mud. It has to disappear.",
        "Pumunta ka sa alinmang probinsya bago ang taniman at makikita mo ang binhi, nakasako at nakatabi sa tuyong sulok ng bahay. Mahalaga ang mga sakong iyon. Kaya ng isang pamilya na magtiis ng gutom bago kainin ang binhi, dahil alam nilang iyon ang ani sa susunod na taon. Pero ito ang kakaibang bagay na alam ng bawat magsasaka. Hangga't ligtas ang butil sa loob ng sako, hindi ito magiging higit pa sa isang butil. Kailangan nitong lumabas sa sako. Kailangan nitong pumasok sa basa at madilim na putik. Kailangan nitong maglaho."
      ),
      t(
        "Our generation has a different philosophy. “Self-love muna.” “Put yourself first.” “Deserve mo 'yan.” “Protect your peace.” Some of that contains a grain of truth, and we will honor that truth in this chapter. But taken as a whole, it is the philosophy of the seed that refuses to leave the sack. It promises a full life and delivers a small one.",
        "Iba ang pilosopiya ng henerasyon natin. “Self-love muna.” “Unahin mo ang sarili mo.” “Deserve mo 'yan.” “Protect your peace.” May butil ng katotohanan ang ilan diyan, at igagalang natin ang katotohanang iyon sa kabanatang ito. Pero kung pagsasamahin, ito ang pilosopiya ng binhing ayaw lumabas ng sako. Nangangako ito ng buong buhay at maliit na buhay ang ibinibigay."
      ),
      t(
        "Jesus offered the opposite. And He did not just preach it. He became the grain of wheat.",
        "Kabaligtaran ang inialok ni Hesus. At hindi lang Niya ito ipinangaral. Siya mismo ang naging butil ng trigo."
      ),
    ],
    sections: [
      {
        heading: t("The throne in the middle of the room", "Ang trono sa gitna ng silid"),
        body: [
          t(
            "Every human heart has a throne in it, and somebody always sits there. In the garden, the serpent's offer was not really about fruit. It was about the throne: “You will be like God” (Genesis 3:5). Ever since, the deepest instinct of fallen people has been to climb up and sit in God's place, to be the one who decides what is good, what I deserve and who must serve me.",
            "May trono ang bawat puso ng tao, at laging may nakaupo roon. Sa hardin, hindi talaga tungkol sa prutas ang alok ng ahas. Tungkol ito sa trono: “Magiging gaya kayo ng Diyos” (Genesis 3:5). Mula noon, ang pinakamalalim na hilig ng taong nagkasala ay umakyat at maupo sa puwesto ng Diyos, maging siya ang magpapasya kung ano ang mabuti, ano ang nararapat sa akin, at sino ang dapat maglingkod sa akin."
          ),
          t(
            "Now look at when Jesus said, “If anyone would come after Me, let him deny himself and take up his cross daily and follow Me” (Luke 9:23). It came right after Peter's great confession, “You are the Christ of God,” and right after Jesus told them for the first time that He would suffer, be rejected and be killed (9:20-22). Mark tells us Peter pulled Jesus aside and rebuked Him (Mark 8:32). Peter wanted a Messiah without a cross, and therefore a discipleship without one. Jesus turned and rebuked him in front of everyone.",
            "Tingnan mo ngayon kung kailan sinabi ni Hesus, “Kung ang sinuman ay nais sumunod sa Akin, tanggihan niya ang kanyang sarili at pasanin ang kanyang krus araw-araw at sumunod sa Akin” (Lucas 9:23). Sinabi Niya ito agad pagkatapos ng dakilang pahayag ni Pedro, “Ikaw ang Cristo ng Diyos,” at agad pagkatapos sabihin ni Hesus sa unang pagkakataon na Siya ay magdurusa, itatakwil at papatayin (t. 20-22). Sinabi ni Marcos na hinila ni Pedro si Hesus sa isang tabi at sinaway Siya (Marcos 8:32). Gusto ni Pedro ng Mesiyas na walang krus, kaya pagiging alagad din na walang krus. Lumingon si Hesus at sinaway siya sa harap ng lahat."
          ),
          t(
            "To deny yourself does not mean to deny that you exist, or to deny yourself every good thing. It means to say no to the self as master. It is the moment you get up from the throne and say to Jesus, “This seat is Yours.” That decision begins at conversion, but as Luke reminds us with one small word, it must be made again daily. The self is a very persistent king. It tries to reclaim the throne every morning.",
            "Ang pagtanggi sa sarili ay hindi pagtanggi na umiiral ka, o pagtanggi sa sarili ng bawat mabuting bagay. Ito ay pagsasabi ng hindi sa sarili bilang panginoon. Ito ang sandaling tumayo ka mula sa trono at sabihin kay Hesus, “Iyo ang upuang ito.” Nagsisimula ang pasyang iyan sa pagbabalik-loob, pero gaya ng paalala ni Lucas sa isang maliit na salita, kailangan itong gawin ulit araw-araw. Napakakulit na hari ang sarili. Sinusubukan nitong agawin muli ang trono tuwing umaga."
          ),
        ],
      },
      {
        heading: t("A cross is not a bad day", "Hindi masamang araw ang krus"),
        body: [
          t(
            "We Filipinos use the word cross very loosely. “Ang krus ko ang biyenan ko.” “Ang krus ko ang traffic sa EDSA.” We laugh, and there is no harm in a joke. But when Jesus said “take up your cross,” nobody in the crowd laughed. They had seen crosses. Rome lined the roads with them. A man carrying a crossbeam through the streets was not having a difficult day. He was a man walking to his death, and everyone knew he was not coming back.",
            "Maluwag gamitin nating mga Pilipino ang salitang krus. “Ang krus ko ang biyenan ko.” “Ang krus ko ang traffic sa EDSA.” Tumatawa tayo, at walang masama sa biro. Pero nang sabihin ni Hesus na “pasanin mo ang iyong krus,” walang tumawa sa mga tao. Nakakita na sila ng krus. Pinupuno ng Roma ang mga daan nito. Ang taong nagpapasan ng kahoy na pahalang sa lansangan ay hindi lang nagkakaroon ng mahirap na araw. Naglalakad siya papunta sa kamatayan, at alam ng lahat na hindi na siya babalik."
          ),
          t(
            "So the cross is not your difficult boss or your sickness, though God can use both. The cross is the place where your will dies so that God's will can live. It is the moment you want to win the argument and you choose to listen instead. It is the moment you could take the credit and you let a co-worker have it. It is the night you want to scroll and you open your Bible. It is the payday you want to treat yourself and you quietly pay your tithe and help a neighbor first.",
            "Kaya ang krus ay hindi ang mahirap mong amo o ang sakit mo, bagaman kaya ng Diyos gamitin ang dalawang iyan. Ang krus ay ang lugar kung saan namamatay ang kalooban mo para mabuhay ang kalooban ng Diyos. Ito ang sandaling gusto mong manalo sa pagtatalo pero pinili mong makinig. Ito ang sandaling puwede mong angkinin ang credit pero ipinaubaya mo sa katrabaho. Ito ang gabing gusto mong mag-scroll pero binuksan mo ang Bibliya mo. Ito ang sweldo-day na gusto mong i-treat ang sarili pero tahimik mo munang ibinigay ang ikapu at tinulungan ang kapitbahay."
          ),
          t(
            "Remember Simon of Cyrene. He came to Jerusalem for the feast, minding his own business, and the soldiers forced him to carry the cross of Jesus (Mark 15:21). He did not choose it. But Mark names his sons, Alexander and Rufus, as if the first readers knew them well, and many believe the family came to faith. The cross Simon never wanted became the road by which his household met the Savior. Your cross may be like that too.",
            "Alalahanin mo si Simon na taga-Cirene. Dumating siya sa Jerusalem para sa pista, walang pakialam sa iba, at pinilit siya ng mga sundalo na pasanin ang krus ni Hesus (Marcos 15:21). Hindi niya ito pinili. Pero binanggit ni Marcos ang pangalan ng mga anak niya, sina Alejandro at Rufo, na para bang kilala sila ng mga unang mambabasa, at marami ang naniniwala na sumampalataya ang pamilyang iyon. Ang krus na hindi kailanman ginusto ni Simon ang naging daan para makilala ng sambahayan niya ang Tagapagligtas. Baka ganyan din ang krus mo."
          ),
        ],
      },
      {
        heading: t("The Lord who went down the stairs", "Ang Panginoong bumaba sa hagdan"),
        body: [
          t(
            "If you want to see what dying to self looks like, do not look at a monk on a mountain. Look at Jesus in Philippians 2. Paul describes Him like a man walking down a staircase. He was in the form of God, yet He did not count equality with God a thing to be grasped. He emptied Himself. He took the form of a servant. He was born in the likeness of men. He humbled Himself. He became obedient to the point of death. And not just any death: “even death on a cross” (Philippians 2:6-8). Every step goes down.",
            "Kung gusto mong makita kung ano ang hitsura ng pagkamatay sa sarili, huwag kang tumingin sa isang monghe sa bundok. Tumingin ka kay Hesus sa Filipos 2. Inilalarawan Siya ni Pablo na parang isang taong bumababa sa hagdan. Siya ay nasa anyo ng Diyos, pero hindi Niya itinuring na dapat panghawakan ang pagiging kapantay ng Diyos. Hinubad Niya ang Kanyang sarili. Kinuha Niya ang anyo ng alipin. Ipinanganak Siya sa wangis ng tao. Nagpakumbaba Siya. Naging masunurin Siya hanggang kamatayan. At hindi basta kamatayan: “maging kamatayan sa krus” (Filipos 2:6-8). Pababa ang bawat hakbang."
          ),
          t(
            "And Paul introduces that hymn with an instruction: “Have this mind among yourselves” (2:5). This is not only theology to admire. It is a pattern to follow. On the night before the cross, John tells us, Jesus knew “that the Father had given all things into His hands,” and so He got up, took a towel and washed His disciples' feet (John 13:3-5). Knowing He had everything, He knelt. Only a person secure in the Father's love can go that low without feeling small.",
            "At sinimulan ni Pablo ang awit na iyan sa isang bilin: “Taglayin ninyo ang pag-iisip na ito” (t. 5). Hindi lang ito teolohiyang hahangaan. Huwaran itong susundin. Noong gabi bago ang krus, sinabi ni Juan na alam ni Hesus “na ibinigay ng Ama ang lahat ng bagay sa Kanyang mga kamay,” kaya tumayo Siya, kumuha ng tuwalya at hinugasan ang paa ng mga alagad (Juan 13:3-5). Alam Niyang nasa Kanya ang lahat, kaya lumuhod Siya. Ang taong panatag lang sa pag-ibig ng Ama ang kayang bumaba nang ganoon nang hindi nakararamdam na maliit siya."
          ),
          t(
            "Think of a barangay fiesta. Everyone is there for the lechon and the program. But somewhere in the back there are people nobody photographs: the ones scrubbing the giant kawa, carrying the plastic chairs, sweeping after midnight. That is where you will often find the mind of Christ. It does not mean you can never stand in front. It means you are just as glad to be in the back, because you are not doing it for the crowd.",
            "Isipin mo ang isang pista sa barangay. Nandoon ang lahat para sa lechon at sa programa. Pero sa likod, may mga taong walang kumukuha ng litrato: ang mga nagkukuskos ng malaking kawa, nagbubuhat ng mga plastik na upuan, nagwawalis pagkalampas ng hatinggabi. Doon mo madalas makikita ang pag-iisip ni Cristo. Hindi ibig sabihing hindi ka na puwedeng tumayo sa harap. Ibig sabihin, kasing-saya mo rin kapag nasa likod ka, dahil hindi ka gumagawa para sa madla."
          ),
        ],
      },
      {
        heading: t("What dying to self does not mean", "Ang hindi ibig sabihin ng pagkamatay sa sarili"),
        body: [
          t(
            "I must speak carefully here, because some of you have been hurt by a twisted version of this teaching. Dying to self does not mean hating yourself. It does not mean you have no worth. You are made in the image of God, and Christ thought you worth dying for. A person who constantly says “wala akong kwenta” is not dead to self. That is still self at the center, only wearing sad clothes.",
            "Kailangan kong mag-ingat dito, dahil may ilan sa inyo na nasaktan ng baluktot na bersyon ng turong ito. Ang pagkamatay sa sarili ay hindi pagkamuhi sa sarili. Hindi ito nangangahulugang wala kang halaga. Nilikha ka sa larawan ng Diyos, at itinuring ka ni Cristo na karapat-dapat pagkamatayan. Ang taong laging nagsasabing “wala akong kwenta” ay hindi patay sa sarili. Sarili pa rin iyan sa gitna, nakasuot lang ng malungkot na damit."
          ),
          t(
            "Nor does it mean you must neglect your body or tolerate abuse. When Elijah collapsed under the broom tree and asked to die, God did not scold him for self-care. He sent an angel with bread and water and said, “Arise and eat, for the journey is too great for you” (1 Kings 19:5-7). Jesus Himself withdrew to rest and pray. Paul assumes that people nourish and cherish their own bodies (Ephesians 5:29). A wife enduring violence, a worker whose passport is being held, a child being harmed: they are not being called to “die to self” by staying in danger. They are being called to safety, and the church should help them get there.",
            "Hindi rin ito nangangahulugang pababayaan mo ang katawan mo o titiisin ang pang-aabuso. Nang bumagsak si Elias sa ilalim ng puno ng enebro at hilingin niyang mamatay na siya, hindi siya pinagalitan ng Diyos dahil sa pag-aalaga sa sarili. Nagpadala Siya ng anghel na may tinapay at tubig at nagsabing, “Bumangon ka at kumain, sapagkat napakalayo ng paglalakbay para sa iyo” (1 Hari 19:5-7). Si Hesus mismo ay lumalayo para magpahinga at manalangin. Ipinapalagay ni Pablo na pinakakain at inaalagaan ng tao ang sarili niyang katawan (Efeso 5:29). Ang asawang dumaranas ng karahasan, ang manggagawang hawak ng amo ang pasaporte, ang batang sinasaktan: hindi sila tinatawag na “mamatay sa sarili” sa pananatili sa panganib. Tinatawag sila sa kaligtasan, at dapat silang tulungan ng simbahan na makarating doon."
          ),
          t(
            "What dies is pride, the demand to be first, the need to be noticed, the will that refuses God. What rises is the real you. Paul did not say, “I no longer exist.” He said, “It is no longer I who live, but Christ who lives in me. And the life I now live in the flesh I live by faith in the Son of God, who loved me and gave Himself for me” (Galatians 2:20). He still had a life. It was simply no longer run by him. And notice the last words: “who loved me.” Self-denial is not the price of His love. It is the response to it.",
            "Ang namamatay ay ang kayabangan, ang paghingi na mauna, ang pangangailangang mapansin, ang kaloobang tumatanggi sa Diyos. Ang bumabangon ay ang tunay na ikaw. Hindi sinabi ni Pablo, “Wala na ako.” Sinabi niya, “Hindi na ako ang nabubuhay, kundi si Cristo ang nabubuhay sa akin. At ang buhay na ipinamumuhay ko ngayon sa laman ay ipinamumuhay ko sa pananampalataya sa Anak ng Diyos, na umibig sa akin at ibinigay ang Kanyang sarili para sa akin” (Galacia 2:20). May buhay pa rin siya. Hindi na lang siya ang nagpapatakbo nito. At pansinin mo ang huling mga salita: “na umibig sa akin.” Ang pagtanggi sa sarili ay hindi bayad para sa pag-ibig Niya. Ito ang tugon dito."
          ),
        ],
      },
      {
        heading: t("The seed that fell in Ecuador", "Ang binhing nahulog sa Ecuador"),
        body: [
          t(
            "Jesus spoke the words of our epigraph in the last week of His life, when some Greeks came asking to see Him (John 12:20-24). His answer sounds strange at first, until you realize He was explaining how the nations would come: not by His fame, but by His death. The grain had to fall. The harvest from that one death is still being gathered from every tribe and tongue.",
            "Sinabi ni Hesus ang mga salita sa simula ng kabanatang ito sa huling linggo ng Kanyang buhay, nang may ilang Griyegong dumating at nagtanong kung puwede nila Siyang makita (Juan 12:20-24). Kakaiba ang dating ng sagot Niya sa una, hanggang maunawaan mong ipinapaliwanag Niya kung paano darating ang mga bansa: hindi sa Kanyang kasikatan, kundi sa Kanyang kamatayan. Kailangang mahulog ang butil. Hanggang ngayon, inaani pa ang bunga ng iisang kamatayang iyon mula sa bawat lipi at wika."
          ),
          t(
            "In 1949 a young American named Jim Elliot wrote in his journal, “He is no fool who gives what he cannot keep to gain that which he cannot lose.” In January 1956, he and four other missionaries were speared to death on a river beach in Ecuador by the Waorani people they had hoped to reach. The newspapers called it a waste. Five young men, with wives and small children, gone.",
            "Noong 1949, isinulat ng isang batang Amerikano na si Jim Elliot sa kanyang journal, “Hindi hangal ang taong nagbibigay ng hindi niya kayang panatilihin para makamit ang hindi niya kailanman mawawala.” Noong Enero 1956, siya at ang apat pang misyonero ay sinibat hanggang mamatay sa tabing-ilog sa Ecuador ng mga Waorani, ang mga taong nais sana nilang maabot. Tinawag itong sayang ng mga pahayagan. Limang binata, may mga asawa at maliliit na anak, wala na."
          ),
          t(
            "But the seed had fallen into the ground. Within a few years, Elliot's widow Elisabeth and Rachel Saint, the sister of another of the slain men, went to live among the Waorani. Some of the very men who had thrown the spears came to faith in Christ, and the story of those five deaths stirred a generation of young believers around the world to give their lives to missions. The world saw a sack of grain thrown away. Heaven saw a field being planted.",
            "Pero nahulog na ang binhi sa lupa. Makalipas ang ilang taon, ang balo ni Elliot na si Elisabeth at si Rachel Saint, kapatid ng isa pang napatay, ay tumira kasama ng mga Waorani. Ilan mismo sa mga lalaking naghagis ng sibat ang sumampalataya kay Cristo, at ang kuwento ng limang kamatayang iyon ang gumising sa isang henerasyon ng kabataang mananampalataya sa buong mundo na ibigay ang kanilang buhay sa misyon. Isang sako ng butil na itinapon ang nakita ng mundo. Isang bukid na tinatamnan ang nakita ng langit."
          ),
          t(
            "Most of us will not die on a riverbank. Our dying will be quieter: a career ambition laid down to stay near aging parents, a grudge buried instead of nursed, years of hidden service in a small church in a city where nobody knows your name. Do not despise those small burials. Jesus promised, “If anyone serves Me, the Father will honor him” (John 12:26). No seed sown for Him is ever wasted.",
            "Karamihan sa atin ay hindi mamamatay sa tabing-ilog. Mas tahimik ang magiging pagkamatay natin: isang ambisyon sa karera na isinuko para manatiling malapit sa tumatandang magulang, isang samaan ng loob na ibinaon sa halip na alagaan, mga taon ng nakatagong paglilingkod sa isang maliit na simbahan sa lungsod na walang nakakikilala sa pangalan mo. Huwag mong maliitin ang maliliit na paglilibing na iyan. Nangako si Hesus, “Kung ang sinuman ay naglilingkod sa Akin, pararangalan siya ng Ama” (Juan 12:26). Walang binhing inihasik para sa Kanya ang nasasayang."
          ),
        ],
      },
    ],
    pullQuote: t(
      "A seed that refuses to be buried stays safe, small and alone; it never sees anything but the inside of the sack.",
      "Ang binhing ayaw magpalibing ay nananatiling ligtas, maliit at nag-iisa; wala itong nakikita kundi ang loob ng sako."
    ),
    pastoralWord: [
      t(
        "Beloved, I want you to ask yourself honestly who is sitting on the throne of your heart today. Not in your theology. In your schedule, your spending, your reactions when someone crosses you. If you find yourself there, do not despair. Every one of us has found ourselves there. Simply get up. Tell Him, “Lord Jesus, this throne is Yours. I step down again today.” He who washed Peter's feet is not ashamed to receive you.",
        "Minamahal, gusto kong tapat mong itanong sa sarili kung sino ang nakaupo sa trono ng puso mo ngayon. Hindi sa teolohiya mo. Sa iskedyul mo, sa paggastos mo, sa reaksyon mo kapag may sumalungat sa iyo. Kung makita mong ikaw ang nakaupo roon, huwag kang mawalan ng pag-asa. Bawat isa sa atin ay nakaupo na rin doon. Tumayo ka lang. Sabihin mo sa Kanya, “Panginoong Hesus, Iyo ang tronong ito. Bababa ulit ako ngayong araw.” Ang naghugas ng paa ni Pedro ay hindi mahihiyang tanggapin ka."
      ),
      t(
        "Then begin each day this week with one small question: “Lord, what is my cross today, and whom can I serve?” Write down the answer at night. Some days it will be a small thing, a word of patience, a dish washed, an apology spoken first. Do it anyway. You are not losing your life. You are planting it, and the One who rose from the grave knows how to bring a harvest out of every buried seed.",
        "Pagkatapos, simulan mo ang bawat araw ngayong linggo sa isang maliit na tanong: “Panginoon, ano ang krus ko ngayong araw, at sino ang mapaglilingkuran ko?” Isulat mo ang sagot sa gabi. May mga araw na maliit na bagay lang ito, isang salita ng pagtitiis, isang pinggang hinugasan, isang paumanhing ikaw ang unang nagsabi. Gawin mo pa rin. Hindi mo nawawala ang buhay mo. Itinatanim mo ito, at alam ng Isang bumangon mula sa libingan kung paano maglabas ng ani mula sa bawat binhing ibinaon."
      ),
    ],
    benediction: t(
      "May the Lord Jesus, who emptied Himself for you, give you the grace to step down from every throne that is His. May your hidden sacrifices become a harvest you will one day see with joy. And may Christ live in you so fully that people meet Him when they meet you. Amen.",
      "Ang Panginoong Hesus, na naghubad ng Kanyang sarili para sa iyo, ay bigyan ka nawa ng biyayang bumaba sa bawat tronong sa Kanya. Ang mga nakatago mong sakripisyo nawa'y maging aning makikita mo balang araw nang may kagalakan. At mabuhay nawa si Cristo sa iyo nang lubos, anupa't Siya ang makikilala ng mga tao kapag nakilala ka nila. Amen."
    ),
  },

  "c-relative-vs-word-truth": {
    epigraph: {
      text: t(
        "If you abide in My word, you are truly My disciples, and you will know the truth, and the truth will set you free.",
        "Kung mananatili kayo sa Aking salita, tunay ngang mga alagad Ko kayo, at makikilala ninyo ang katotohanan, at palalayain kayo ng katotohanan."
      ),
      ref: t("John 8:31-32", "Juan 8:31-32"),
    },
    opening: [
      t(
        "Every Filipino mother who has done her marketing knows the trick. You ask for one kilo of galunggong, the vendor drops the fish on the timbangan, the needle jumps to one kilo, and you pay. But at home the fish looks a little few. Your suki down the street weighs it on her own scale, and it is only eight hundred grams. The first scale had been adjusted. It told the vendor's truth, not the truth.",
        "Alam ng bawat nanay na namamalengke ang daya. Hihingi ka ng isang kilong galunggong, ihuhulog ng tindera ang isda sa timbangan, tatalon ang karayom sa isang kilo, at magbabayad ka. Pero pag-uwi mo, parang kaunti ang isda. Tinimbang ito ng suki mo sa kabilang kalye sa sarili niyang timbangan, at walong daang gramo lang pala. Dinaya ang unang timbangan. Ang katotohanan ng tindera ang sinabi nito, hindi ang katotohanan."
      ),
      t(
        "Nobody at the palengke says, “Well, that's her truth, and this is my truth.” We get angry. We know that a scale is supposed to measure something outside of anyone's feelings. And God agrees with us: “A false balance is an abomination to the Lord, but a just weight is His delight” (Proverbs 11:1).",
        "Walang namamalengke na nagsasabing, “E, truth niya 'yon, at ito ang truth ko.” Nagagalit tayo. Alam nating dapat sukatin ng timbangan ang isang bagay na nasa labas ng damdamin ninuman. At sang-ayon ang Diyos sa atin: “Ang madayang timbangan ay kasuklam-suklam sa Panginoon, ngunit ang tapat na panimbang ay Kanyang kaluguran” (Kawikaan 11:1)."
      ),
      t(
        "Yet when it comes to the biggest questions of life, who God is, what is right, what marriage is, what will happen when we die, many people suddenly want a scale that can be adjusted. “Truth mo 'yan, truth ko 'to.” This chapter is about why that does not work, and about the Person who is the true measure of all things.",
        "Pero pagdating sa pinakamalalaking tanong ng buhay, kung sino ang Diyos, ano ang tama, ano ang kasal, ano ang mangyayari kapag namatay tayo, maraming tao ang biglang naghahanap ng timbangang puwedeng iayos. “Truth mo 'yan, truth ko 'to.” Ang kabanatang ito ay tungkol sa kung bakit hindi iyan uubra, at tungkol sa Persona na siyang tunay na panukat ng lahat ng bagay."
      ),
    ],
    sections: [
      {
        heading: t("A governor's shrug", "Ang kibit-balikat ng isang gobernador"),
        body: [
          t(
            "It was early morning in Jerusalem. The religious leaders would not even enter Pilate's headquarters because they did not want to be defiled before the Passover, though they had no problem demanding an innocent man's death (John 18:28). Inside, the Roman governor faced a beaten Galilean who spoke with strange authority: “For this purpose I was born and for this purpose I have come into the world, to bear witness to the truth. Everyone who is of the truth listens to My voice” (18:37).",
            "Maaga pa noon sa Jerusalem. Ayaw man lang pumasok ng mga lider ng relihiyon sa punong-himpilan ni Pilato dahil ayaw nilang madungisan bago ang Paskuwa, pero wala silang problema sa paghingi ng kamatayan ng isang walang-salang tao (Juan 18:28). Sa loob, kaharap ng Romanong gobernador ang isang binugbog na taga-Galilea na nagsasalita nang may kakaibang awtoridad: “Para sa layuning ito ay ipinanganak Ako at para rito ay naparito Ako sa sanlibutan, upang magpatotoo sa katotohanan. Ang bawat isa na mula sa katotohanan ay nakikinig sa Aking tinig” (18:37)."
          ),
          t(
            "Pilate answered, “What is truth?” and then, John tells us, “he went back outside” (18:38). He did not wait for an answer. That is the posture of much of our world. Not an honest question, but a shrug on the way out the door. Pilate was a politician. Truth was inconvenient. The crowd was loud. It was easier to treat truth as a matter of opinion and let the majority decide.",
            "Sumagot si Pilato, “Ano ang katotohanan?” at pagkatapos, sabi ni Juan, “lumabas siyang muli” (18:38). Hindi siya naghintay ng sagot. Iyan ang tindig ng malaking bahagi ng mundo natin. Hindi tapat na tanong, kundi kibit-balikat habang palabas ng pinto. Politiko si Pilato. Abala ang katotohanan. Maingay ang madla. Mas madaling ituring ang katotohanan na usapin ng opinyon at hayaang ang nakararami ang magpasya."
          ),
          t(
            "He washed his hands before the crowd and declared himself innocent (Matthew 27:24). But history did not let him off. For centuries Christians around the world have confessed in the Apostles' Creed that Jesus “suffered under Pontius Pilate.” The man who would not wait for the truth is remembered forever because of the Truth he condemned. You cannot shrug off Jesus. Sooner or later every person must give Him an answer.",
            "Naghugas siya ng kamay sa harap ng madla at idineklarang wala siyang sala (Mateo 27:24). Pero hindi siya pinalampas ng kasaysayan. Sa loob ng maraming siglo, ipinahahayag ng mga Kristiyano sa buong mundo sa Apostles' Creed na si Hesus ay “nagdusa sa ilalim ni Poncio Pilato.” Ang lalaking ayaw maghintay sa katotohanan ay maaalala magpakailanman dahil sa Katotohanang hinatulan niya. Hindi mo puwedeng kibitan ng balikat si Hesus. Maaga o huli, kailangang bigyan Siya ng sagot ng bawat tao."
          ),
        ],
      },
      {
        heading: t("The plumb line", "Ang hulog"),
        body: [
          t(
            "Ask any karpintero how he knows a wall is straight. He will not tell you, “I feel that it's straight.” He hangs a plumb line, a string with a weight at the end, and lets gravity tell the truth. The prophet Amos saw a vision of the Lord standing beside a wall with a plumb line in His hand, and God said, “Behold, I am setting a plumb line in the midst of My people Israel” (Amos 7:7-8). Israel's leaders thought their society was upright. God's line showed it was leaning, ready to fall.",
            "Tanungin mo ang kahit sinong karpintero kung paano niya nalalamang tuwid ang pader. Hindi niya sasabihing, “Pakiramdam ko tuwid.” Magsasabit siya ng hulog, isang tali na may pabigat sa dulo, at hahayaan ang grabidad na magsabi ng totoo. Nakita ng propetang si Amos sa isang pangitain ang Panginoon na nakatayo sa tabi ng pader na may hawak na hulog, at sinabi ng Diyos, “Narito, maglalagay Ako ng hulog sa gitna ng Aking bayang Israel” (Amos 7:7-8). Akala ng mga lider ng Israel na tuwid ang lipunan nila. Ipinakita ng hulog ng Diyos na nakahilig ito, handa nang bumagsak."
          ),
          t(
            "That is what the Word of God is. Not a mirror that reflects back what we already think, but a plumb line that hangs from heaven. Jesus prayed, “Sanctify them in the truth; Your word is truth” (John 17:17). He did not say, “Your word contains some helpful truths,” or “Your word is true for those who like it.” He said it is truth, the standard by which every wall, every culture and every heart is measured.",
            "Iyan ang Salita ng Diyos. Hindi salaming nagpapakita lang ng iniisip na natin, kundi hulog na nakabitin mula sa langit. Nanalangin si Hesus, “Pabanalin Mo sila sa katotohanan; ang Iyong salita ay katotohanan” (Juan 17:17). Hindi Niya sinabing, “May ilang kapaki-pakinabang na katotohanan ang Iyong salita,” o “Totoo ang Iyong salita para sa mga may gusto nito.” Sinabi Niyang ito ang katotohanan, ang pamantayang sumusukat sa bawat pader, bawat kultura at bawat puso."
          ),
          t(
            "When a people throws away the plumb line, the wall does not become free. It becomes crooked. The last verse of Judges describes it: “Everyone did what was right in his own eyes” (Judges 21:25), and the chapters before it are some of the darkest in the Bible. A society where every person is his own measure does not become a paradise of freedom. It becomes a place where the strong do as they please and the weak suffer.",
            "Kapag itinapon ng isang bayan ang hulog, hindi lumalaya ang pader. Bumabaluktot ito. Inilalarawan ito ng huling talata ng Hukom: “Ginagawa ng bawat isa ang tama sa sarili niyang paningin” (Hukom 21:25), at ang mga kabanatang nauna rito ay ilan sa pinakamadilim sa Bibliya. Ang lipunang ang bawat tao ang sariling panukat ay hindi nagiging paraiso ng kalayaan. Nagiging lugar ito kung saan ginagawa ng malakas ang gusto niya at ang mahina ang nagdurusa."
          ),
          t(
            "And notice the irony in the slogan itself. “There is no absolute truth” is a sentence that claims to be absolutely true. The person who says it does not live by it either. He is outraged when his employer cheats him of his salary, when a politician steals relief goods, when someone lies to his daughter. In those moments he knows perfectly well that some things are really wrong. Relativism usually disappears the moment we are the ones being wronged.",
            "At pansinin mo ang kabalintunaan sa mismong slogan. Ang “walang ganap na katotohanan” ay pangungusap na nagsasabing ganap na totoo ito. Hindi rin ito isinasabuhay ng nagsasabi nito. Galit na galit siya kapag dinaya siya ng amo sa sweldo, kapag nagnakaw ng relief goods ang isang politiko, kapag may nagsinungaling sa anak niyang babae. Sa mga sandaling iyon, alam na alam niyang may mga bagay na talagang mali. Kadalasang nawawala ang relativismo sa sandaling tayo na ang naaagrabyado."
          ),
        ],
      },
      {
        heading: t("Itching ears", "Makakating tainga"),
        body: [
          t(
            "From a Roman prison, near the end of his life, Paul warned his son in the faith: “The time is coming when people will not endure sound teaching, but having itching ears they will accumulate for themselves teachers to suit their own passions, and will turn away from listening to the truth and wander off into myths” (2 Timothy 4:3-4). Notice what drives it. Not a lack of information. Passions. People decide what they want first, and then go shopping for a teacher who will approve it.",
            "Mula sa isang bilangguan sa Roma, malapit na sa katapusan ng buhay niya, nagbabala si Pablo sa kanyang anak sa pananampalataya: “Darating ang panahon na hindi titiisin ng mga tao ang tamang aral, kundi dahil makati ang kanilang tainga ay magtitipon sila ng mga gurong angkop sa kanilang sariling pagnanasa, at tatalikod sa pakikinig sa katotohanan at babaling sa mga alamat” (2 Timoteo 4:3-4). Pansinin mo kung ano ang nagtutulak dito. Hindi kakulangan ng impormasyon. Pagnanasa. Nagpapasya muna ang tao kung ano ang gusto niya, saka siya namimili ng gurong sasang-ayon dito."
          ),
          t(
            "We have never had more teachers to choose from. A believer can scroll past a hundred preachers in an evening and stop only on the ones who make him feel good. Our phones learn what we like and feed us more of it. Without noticing, we can build a private religion out of verses we enjoy, skipping every passage that confronts us about money, sex, forgiveness or pride.",
            "Ngayon lang nagkaroon ng ganito karaming guro na mapagpipilian. Kayang lampasan ng isang mananampalataya ang isandaang mangangaral sa isang gabi ng pag-scroll at tumigil lang sa mga nagpapagaan ng loob niya. Natututunan ng cellphone natin ang gusto natin at mas marami pa niyon ang ipinapakain sa atin. Nang hindi namamalayan, puwede tayong makabuo ng pribadong relihiyon mula sa mga talatang gusto natin, nilalaktawan ang bawat bahaging sumasaway sa atin tungkol sa pera, sekswalidad, pagpapatawad o kayabangan."
          ),
          t(
            "Isaiah saw where this road ends: “Woe to those who call evil good and good evil, who put darkness for light and light for darkness, who put bitter for sweet and sweet for bitter!” (Isaiah 5:20). The labels get switched. What God calls sin is renamed freedom, and what God calls faithfulness is renamed narrow-mindedness. Here is a simple test for your own heart. When did the Bible last change your mind about something? If it never does, you may be reading it as a mirror, not a plumb line.",
            "Nakita ni Isaias kung saan nagtatapos ang daang ito: “Sa aba ng mga tumatawag sa masama na mabuti at sa mabuti na masama, na ginagawang liwanag ang kadiliman at kadiliman ang liwanag, na ginagawang matamis ang mapait at mapait ang matamis!” (Isaias 5:20). Pinagpapalit ang mga etiketa. Ang tinatawag ng Diyos na kasalanan ay pinangangalanang kalayaan, at ang tinatawag ng Diyos na katapatan ay pinangangalanang makitid na pag-iisip. Narito ang isang simpleng pagsubok para sa sarili mong puso. Kailan ka huling binago ng Bibliya ng isip tungkol sa isang bagay? Kung hindi kailanman, baka binabasa mo ito bilang salamin, hindi bilang hulog."
          ),
        ],
      },
      {
        heading: t("Truth with a face", "Katotohanang may mukha"),
        body: [
          t(
            "Here is what makes the Christian faith different from a rulebook. Jesus did not only say, “I teach the truth.” He said, “I am the way, and the truth, and the life” (John 14:6). Truth is not finally a list of propositions, though it includes them. Truth is a Person. That means when you are wrestling with what is true, you are not merely arguing with a book. You are standing before Someone who looks at you.",
            "Ito ang nagpapaiba sa pananampalatayang Kristiyano sa isang listahan ng patakaran. Hindi lang sinabi ni Hesus, “Itinuturo Ko ang katotohanan.” Sinabi Niya, “Ako ang daan, at ang katotohanan, at ang buhay” (Juan 14:6). Ang katotohanan, sa huli, ay hindi lang listahan ng mga pahayag, bagaman kasama ang mga iyon. Ang katotohanan ay isang Persona. Ibig sabihin, kapag nakikipagbuno ka sa kung ano ang totoo, hindi ka lang nakikipagtalo sa isang aklat. Nakatayo ka sa harap ng Isang nakatingin sa iyo."
          ),
          t(
            "And look at how He looks at people. In John 8, the scribes dragged a woman caught in adultery into the temple courts and threw her down in front of everyone. They had the law on their side, and they had stones in their hands. Jesus bent down and wrote on the ground. Then He said, “Let him who is without sin among you be the first to throw a stone at her.” One by one, from the oldest to the youngest, they walked away (John 8:7-9).",
            "At tingnan mo kung paano Siya tumingin sa mga tao. Sa Juan 8, kinaladkad ng mga eskriba ang isang babaeng nahuli sa pangangalunya papasok sa templo at inihagis siya sa harap ng lahat. Nasa panig nila ang kautusan, at may hawak silang mga bato. Yumuko si Hesus at sumulat sa lupa. Saka Niya sinabi, “Ang walang kasalanan sa inyo ang maunang bumato sa kanya.” Isa-isa, mula sa pinakamatanda hanggang sa pinakabata, umalis sila (Juan 8:7-9)."
          ),
          t(
            "Then Jesus said two things to the woman, and we must never separate them. “Neither do I condemn you.” And, “Go, and from now on sin no more” (8:11). The first sentence without the second would be a lie, as if adultery did not matter. The second without the first would crush her. Jesus gave her both, because He is “full of grace and truth” (John 1:14). That is the only kind of truth that sets anyone free.",
            "Pagkatapos, dalawang bagay ang sinabi ni Hesus sa babae, at hindi natin dapat paghiwalayin ang mga ito kailanman. “Hindi rin kita hinahatulan.” At, “Humayo ka, at mula ngayon ay huwag ka nang magkasala” (8:11). Ang unang pangungusap na walang ikalawa ay magiging kasinungalingan, na parang walang halaga ang pangangalunya. Ang ikalawa na walang una ay dudurog sa kanya. Ibinigay ni Hesus ang dalawa, dahil Siya ay “puspos ng biyaya at katotohanan” (Juan 1:14). Iyan lang ang uri ng katotohanang nakapagpapalaya ng sinuman."
          ),
        ],
      },
      {
        heading: t("Speaking truth so it can be heard", "Pagsasalita ng katotohanan para marinig ito"),
        body: [
          t(
            "Paul wrote that we grow up into Christ by “speaking the truth in love” (Ephesians 4:15). Some of us are good at the truth part and have left a trail of bruised people behind us. Others are good at the love part and have never once told a friend what he needed to hear. Both have failed the friend.",
            "Isinulat ni Pablo na lumalago tayo patungo kay Cristo sa “pagsasalita ng katotohanan sa pag-ibig” (Efeso 4:15). May ilan sa atin na magaling sa bahaging katotohanan at nag-iwan ng maraming nasaktang tao sa likod. May iba namang magaling sa bahaging pag-ibig at ni minsan ay hindi nagsabi sa kaibigan ng kailangan niyang marinig. Pareho nilang binigo ang kaibigan."
          ),
          t(
            "Remember how the prophet Nathan confronted King David after Bathsheba. He did not storm into the palace shouting. He told a story about a rich man who stole a poor man's only little lamb, a lamb that “used to eat of his morsel and drink from his cup and lie in his arms” (2 Samuel 12:3). David burned with anger at the injustice. Then Nathan said four words: “You are the man” (12:7). The truth went in because love had prepared the way. And David wept, and wrote Psalm 51.",
            "Alalahanin mo kung paano hinarap ni propeta Natan si Haring David pagkatapos ng nangyari kay Batsheba. Hindi siya sumugod sa palasyo nang pasigaw. Nagkuwento siya tungkol sa isang mayamang nagnakaw ng nag-iisang maliit na tupa ng isang mahirap, tupang “kumakain mula sa kanyang pagkain at umiinom sa kanyang tasa at humihiga sa kanyang kandungan” (2 Samuel 12:3). Nag-alab ang galit ni David sa kawalang-katarungan. Saka sinabi ni Natan, “Ikaw ang taong iyon” (12:7). Pumasok ang katotohanan dahil inihanda ng pag-ibig ang daan. At umiyak si David, at isinulat ang Awit 51."
          ),
          t(
            "When a co-worker in your dorm says, “Basta masaya ka, okay lang 'yan,” you do not need to win a debate before lights-out. Ask a gentle question: “Is that true for everyone, even the person who hurts someone else to be happy?” Listen to the story behind the slogan, because there usually is one. Live honestly in the small things, the timesheet, the receipt, the excuse you could have invented. And when the door opens, tell them about the Truth who did not condemn you but also did not leave you as you were.",
            "Kapag sinabi ng katrabaho mo sa dorm, “Basta masaya ka, okay lang 'yan,” hindi mo kailangang manalo sa debate bago patayin ang ilaw. Magtanong ka nang mahinahon: “Totoo ba iyan para sa lahat, pati sa taong nananakit ng iba para lang sumaya?” Pakinggan mo ang kuwento sa likod ng slogan, dahil kadalasan ay mayroon. Mamuhay ka nang tapat sa maliliit na bagay, sa timesheet, sa resibo, sa palusot na puwede mo sanang inimbento. At kapag bumukas ang pinto, ikuwento mo sa kanila ang Katotohanang hindi humatol sa iyo pero hindi rin hinayaang manatili ka sa dati mong kalagayan."
          ),
        ],
      },
    ],
    pullQuote: t(
      "If the truth bends to fit you, it will never be strong enough to lift you.",
      "Kung bumabaluktot ang katotohanan para umayon sa iyo, hindi ito kailanman magiging sapat ang lakas para iahon ka."
    ),
    pastoralWord: [
      t(
        "Beloved, there may be a part of God's Word you have been quietly avoiding. You know which one. It is the passage you skip, the sermon you mute, the conviction you have explained away. I am not asking you to fake an agreement you do not feel. I am asking you to stop walking out of the room like Pilate. Stay. Wait for the answer. Open that passage this week and pray, “Lord, I want Your truth more than my comfort. Change my mind where I am wrong.”",
        "Minamahal, baka may bahagi ng Salita ng Diyos na tahimik mong iniiwasan. Alam mo kung alin. Iyon ang talatang nilalaktawan mo, ang sermong ini-mute mo, ang paninindigang pinalusutan mo na. Hindi kita hinihiling na magkunwaring sumasang-ayon kahit hindi mo nararamdaman. Hinihiling ko lang na huwag ka nang lumabas ng silid gaya ni Pilato. Manatili ka. Hintayin mo ang sagot. Buksan mo ang talatang iyon ngayong linggo at manalangin, “Panginoon, mas gusto ko ang Iyong katotohanan kaysa sa aking ginhawa. Baguhin Mo ang isip ko kung saan ako mali.”"
      ),
      t(
        "And then, because truth is a Person, go to Him with it. Abide in His word, as our epigraph says, not for a day but as a way of life. Read the Gospel of John slowly. Let the One who said “I am the truth” sit with you the way He sat with the woman who had been thrown at His feet. You will find that His truth does not crush you. It sets you free.",
        "At pagkatapos, dahil Persona ang katotohanan, lumapit ka sa Kanya dala ito. Manatili ka sa Kanyang salita, gaya ng sinasabi ng talata sa simula ng kabanatang ito, hindi lang sa isang araw kundi bilang paraan ng pamumuhay. Basahin mo nang dahan-dahan ang Ebanghelyo ni Juan. Hayaan mong samahan ka ng nagsabing “Ako ang katotohanan” gaya ng pagsama Niya sa babaeng inihagis sa Kanyang paanan. Matutuklasan mong hindi ka dinudurog ng katotohanan Niya. Pinalalaya ka nito."
      ),
    ],
    benediction: t(
      "May the Lord Jesus, who is the Truth, anchor you when every voice around you shifts. May His Word be the plumb line of your heart and the lamp of your feet. And may you speak His truth with His tenderness, until many find freedom in Him. Amen.",
      "Ang Panginoong Hesus, na siyang Katotohanan, ang mag-angkla nawa sa iyo kapag nagbabago-bago ang bawat tinig sa paligid mo. Ang Kanyang Salita nawa ang maging hulog ng puso mo at ilaw ng mga paa mo. At nawa'y maipahayag mo ang Kanyang katotohanan nang may Kanyang lambing, hanggang marami ang makatagpo ng kalayaan sa Kanya. Amen."
    ),
  },

  "c-success-vs-faithfulness": {
    epigraph: {
      text: t(
        "Moreover, it is required of stewards that they be found faithful.",
        "Bukod dito, hinihingi sa mga katiwala na sila'y matagpuang tapat."
      ),
      ref: t("1 Corinthians 4:2", "1 Corinto 4:2"),
    },
    opening: [
      t(
        "Drive through any town in April and May and you will see them: the tarpaulins. “Congratulations, Engr. So-and-so, Board Passer!” “Our pride and joy, Magna Cum Laude!” They hang from gates and fences with big smiling photos, and the whole barangay knows whose child made it. Then December comes, and the reunions begin. Around the long table with the pancit and the lumpia, the question goes around like a serving spoon: “O, ano na'ng trabaho mo? Saan ka na? Ilan na anak mo? May sasakyan ka na?”",
        "Dumaan ka sa kahit anong bayan tuwing Abril at Mayo at makikita mo sila: ang mga tarpaulin. “Congratulations, Engr. Ganito, Board Passer!” “Ang aming karangalan, Magna Cum Laude!” Nakasabit sila sa mga gate at bakod na may malalaking nakangiting litrato, at alam ng buong barangay kung kaninong anak ang nakaabot. Tapos darating ang Disyembre, at magsisimula ang mga reunion. Sa mahabang mesa na may pancit at lumpia, umiikot ang tanong na parang sandok: “O, ano na'ng trabaho mo? Saan ka na? Ilan na anak mo? May sasakyan ka na?”"
      ),
      t(
        "Some people love that table. Many dread it. There is a nephew who failed the board twice and now sits quietly at the end. There is a woman who has worked as a household helper in Hong Kong for fifteen years, sending three siblings through college, and nobody made a tarpaulin for her. There is a pastor of a small church who has never had a car. They all feel the weight of the question underneath the questions: “Ano na'ng naipagmamalaki mo?”",
        "May mga taong gustong-gusto ang mesang iyon. Marami ang kinakabahan dito. May pamangking dalawang beses bumagsak sa board at tahimik na nakaupo sa dulo. May babaeng labinlimang taon nang household helper sa Hong Kong, nakapagpatapos ng tatlong kapatid sa kolehiyo, at walang gumawa ng tarpaulin para sa kanya. May pastor ng isang maliit na simbahan na hindi kailanman nagkaroon ng kotse. Lahat sila ay ramdam ang bigat ng tanong sa ilalim ng mga tanong: “Ano na'ng naipagmamalaki mo?”"
      ),
      t(
        "I want to tell you that heaven asks a different question. And I want to tell you that by heaven's measure, some of the people at the end of that table are the most successful people in the room.",
        "Gusto kong sabihin sa iyo na iba ang tanong ng langit. At gusto kong sabihin sa iyo na sa sukatan ng langit, ang ilan sa mga nakaupo sa dulo ng mesang iyon ang pinakamatagumpay na tao sa buong silid."
      ),
    ],
    sections: [
      {
        heading: t("The question under every question", "Ang tanong sa ilalim ng bawat tanong"),
        body: [
          t(
            "Jesus once asked a question that cuts through every reunion: “What does it profit a man to gain the whole world and forfeit his soul?” (Mark 8:36). Notice He assumes it is possible to gain the whole world. Not just a good job, not just a house, the whole thing. And He says a person could have all of it and still end up with a loss on the final balance sheet.",
            "Minsan nagtanong si Hesus ng tanong na tumatagos sa bawat reunion: “Ano ang mapapakinabangan ng tao kung makamit niya ang buong mundo ngunit maiwala ang kanyang kaluluwa?” (Marcos 8:36). Pansinin mong ipinapalagay Niyang posibleng makamit ang buong mundo. Hindi lang magandang trabaho, hindi lang bahay, ang lahat. At sinasabi Niyang puwedeng makuha ng tao ang lahat ng iyon pero lugi pa rin sa huling kuwenta."
          ),
          t(
            "Our culture adds another layer the Bible knows well: shame. We chase success not only to have things but to avoid being looked down on. “Nakakahiya kung hindi ka umasenso.” Many young Filipinos carry this pressure until it crushes them. They study, work and migrate not out of calling but out of fear of the reunion table. And when they fail an exam or lose a job, they do not just feel disappointed. They feel worthless.",
            "May isa pang patong na idinadagdag ang kultura natin na kilalang-kilala ng Bibliya: hiya. Hinahabol natin ang tagumpay hindi lang para magkaroon ng mga bagay kundi para hindi tayo maliitin. “Nakakahiya kung hindi ka umasenso.” Maraming kabataang Pilipino ang nagpapasan ng presyong ito hanggang madurog sila. Nag-aaral sila, nagtatrabaho at nangingibang-bansa hindi dahil sa tawag kundi dahil sa takot sa mesa ng reunion. At kapag bumagsak sila sa exam o nawalan ng trabaho, hindi lang sila nadidismaya. Pakiramdam nila wala silang halaga."
          ),
          t(
            "Jesus said something even sharper to the Pharisees, who loved money and loved being admired: “You are those who justify yourselves before men, but God knows your hearts. For what is exalted among men is an abomination in the sight of God” (Luke 16:15). That is a frightening sentence. It means some of the things our culture puts on tarpaulins, God looks at and turns His face away, because of the pride and the means behind them. And some things nobody ever photographs, He treasures.",
            "May mas matalim pang sinabi si Hesus sa mga Pariseo, na mahilig sa pera at mahilig hangaan: “Kayo ang mga nagpapakatuwid sa harap ng tao, ngunit kilala ng Diyos ang inyong mga puso. Sapagkat ang itinataas ng mga tao ay kasuklam-suklam sa paningin ng Diyos” (Lucas 16:15). Nakakatakot na pangungusap iyan. Ibig sabihin, may ilang bagay na inilalagay ng kultura natin sa tarpaulin na tinitingnan ng Diyos at tinatalikuran, dahil sa kayabangan at sa paraang ginamit sa likod nito. At may mga bagay na walang kumukuha ng litrato pero pinakaiingatan Niya."
          ),
        ],
      },
      {
        heading: t("Two talents and the same words", "Dalawang talento at parehong salita"),
        body: [
          t(
            "In the parable of the talents (Matthew 25:14-30), a master goes on a journey and entrusts his property to three servants, “to each according to his ability.” One receives five talents, one two, one a single talent. A talent was a huge sum, many years of a laborer's wages. So even the least of them was trusted with a great deal.",
            "Sa talinghaga ng mga talento (Mateo 25:14-30), may isang panginoong naglakbay at ipinagkatiwala ang kanyang ari-arian sa tatlong alipin, “sa bawat isa ayon sa kanyang kakayahan.” Limang talento ang tinanggap ng isa, dalawa ang isa, at iisa ang huli. Napakalaking halaga ng isang talento, sahod ng manggagawa sa maraming taon. Kaya kahit ang pinakamaliit sa kanila ay pinagkatiwalaan ng napakalaki."
          ),
          t(
            "When the master returns, the five-talent servant reports five more. The master says, “Well done, good and faithful servant. You have been faithful over a little; I will set you over much. Enter into the joy of your master” (25:21). Then the two-talent servant comes. He has only four talents to show, less than the first man started with. And the master says, word for word, the exact same thing (25:23). Read the two verses side by side. Not one word is different.",
            "Pagbalik ng panginoon, nag-ulat ang may limang talento ng lima pang dagdag. Sinabi ng panginoon, “Magaling, mabuti at tapat na alipin. Naging tapat ka sa kaunti; pamamahalain kita sa marami. Pumasok ka sa kagalakan ng iyong panginoon” (25:21). Saka dumating ang may dalawang talento. Apat na talento lang ang maipapakita niya, mas kaunti pa sa sinimulan ng una. At sinabi ng panginoon, salita por salita, ang eksaktong pareho (25:23). Basahin mo nang magkatabi ang dalawang talata. Walang kahit isang salitang naiiba."
          ),
          t(
            "That is heaven's arithmetic. God does not grade on the size of the result but on the faithfulness of the steward. The two-talent servant was not a lesser success. He was a complete success, because he did everything he could with everything he was given.",
            "Iyan ang aritmetika ng langit. Hindi nagmamarka ang Diyos ayon sa laki ng resulta kundi ayon sa katapatan ng katiwala. Hindi mas mababang tagumpay ang may dalawang talento. Buong tagumpay siya, dahil ginawa niya ang lahat ng kaya niya sa lahat ng ibinigay sa kanya."
          ),
          t(
            "And look closely at the servant who failed. His problem was not that he had only one talent. It was what he said: “I was afraid, and I went and hid your talent in the ground” (25:25). Fear of failure made him bury what he had. Many people raised in a culture of shame do exactly this. They are so afraid of not being impressive that they do nothing at all. Hear me: God would rather have your small, imperfect, faithful offering than your perfect excuse.",
            "At tingnan mong mabuti ang aliping nabigo. Hindi ang pagkakaroon ng iisang talento ang problema niya. Ang problema ay ang sinabi niya: “Natakot ako, kaya umalis ako at ibinaon sa lupa ang iyong talento” (25:25). Pinagbaon siya ng takot sa kabiguan ng mayroon siya. Ganito mismo ang ginagawa ng maraming lumaki sa kultura ng hiya. Takot na takot silang hindi maging kahanga-hanga kaya wala na silang ginagawa. Pakinggan mo ako: mas gusto ng Diyos ang maliit, hindi perpekto, pero tapat mong handog kaysa sa perpekto mong palusot."
          ),
        ],
      },
      {
        heading: t("The prophet who never had a revival", "Ang propetang hindi nakakita ng muling pagkabuhay"),
        body: [
          t(
            "If success means visible results, then Jeremiah was one of the great failures of the Bible. He preached for about forty years to a nation that would not listen. His own townsmen plotted to kill him (Jeremiah 11:21). The king cut up his scroll piece by piece and threw it into the fire (36:23). He was beaten, put in stocks, and lowered into a muddy cistern where he sank in the mire (38:6). He watched Jerusalem burn exactly as he had warned.",
            "Kung ang tagumpay ay nakikitang resulta, isa si Jeremias sa pinakamalaking kabiguan sa Bibliya. Nangaral siya nang mga apatnapung taon sa isang bansang ayaw makinig. Nagbalak ang mga kababayan niya na patayin siya (Jeremias 11:21). Hiniwa-hiwa ng hari ang kanyang balumbon at isa-isang inihagis sa apoy (36:23). Binugbog siya, inilagay sa pangawan, at ibinaba sa maputik na balon kung saan lumubog siya sa putik (38:6). Napanood niyang nasunog ang Jerusalem eksakto gaya ng babala niya."
          ),
          t(
            "No crowds. No church growth. No tarpaulin. Yet when God called him, He had said, “Before I formed you in the womb I knew you” (1:5). Jeremiah's success was never measured by how many listened. It was measured by whether he spoke what God said. Centuries later, when people wondered who Jesus was, some said, “Jeremiah” (Matthew 16:14). The forgotten failure had become the measure of a true prophet.",
            "Walang madla. Walang paglago ng simbahan. Walang tarpaulin. Pero nang tawagin siya ng Diyos, sinabi Niya, “Bago kita inanyuan sa sinapupunan ay kilala na kita” (1:5). Hindi kailanman nasukat ang tagumpay ni Jeremias sa dami ng nakinig. Nasukat ito sa kung sinabi niya ang sinabi ng Diyos. Makalipas ang maraming siglo, nang magtanong ang mga tao kung sino si Hesus, may nagsabing, “Si Jeremias” (Mateo 16:14). Ang nakalimutang kabiguan ay naging panukat ng isang tunay na propeta."
          ),
          t(
            "William Carey, the English shoemaker who became a missionary to India, arrived there in 1793 and waited about seven years before baptizing the first Indian believer he had led to Christ. He kept translating, teaching and preaching through illness, grief and the loss of years of work in a fire. Near the end of his life he reportedly told his nephew that if anyone wrote about him, they could describe him as a plodder, because he could plod. That is faithfulness. Not brilliance. Plodding, for Jesus, one day at a time.",
            "Si William Carey, ang Ingles na sapatero na naging misyonero sa India, ay dumating doon noong 1793 at naghintay nang mga pitong taon bago niya binautismuhan ang unang Indianong mananampalatayang naakay niya kay Cristo. Nagpatuloy siya sa pagsasalin, pagtuturo at pangangaral sa gitna ng sakit, pagdadalamhati, at pagkasunog ng mga taon ng kanyang gawa. Malapit sa katapusan ng buhay niya, sinasabing sinabi niya sa pamangkin niya na kung may susulat tungkol sa kanya, puwede siyang ilarawan bilang isang taong masipag na tuloy-tuloy lang, dahil iyon ang kaya niya. Iyan ang katapatan. Hindi katalinuhan. Tuloy-tuloy na pagsisikap, para kay Hesus, isang araw sa bawat pagkakataon."
          ),
        ],
      },
      {
        heading: t("The audience of One", "Iisang Manonood"),
        body: [
          t(
            "Paul knew what it was to be judged by people. The Corinthians compared him to other preachers and found him unimpressive. His answer is one of the freest sentences in the Bible: “With me it is a very small thing that I should be judged by you or by any human court. In fact, I do not even judge myself... It is the Lord who judges me” (1 Corinthians 4:3-4). Imagine living like that. Not crushed by criticism, not puffed up by praise, because only one opinion finally counts.",
            "Alam ni Pablo kung ano ang mahusgahan ng tao. Ikinumpara siya ng mga taga-Corinto sa ibang mangangaral at hindi sila humanga. Ang sagot niya ay isa sa pinakamalayang pangungusap sa Bibliya: “Para sa akin, napakaliit na bagay na ako'y hatulan ninyo o ng anumang hukuman ng tao. Sa katunayan, hindi ko man lang hinahatulan ang aking sarili... Ang Panginoon ang humahatol sa akin” (1 Corinto 4:3-4). Isipin mong mamuhay nang ganyan. Hindi nadudurog sa pintas, hindi lumalaki ang ulo sa papuri, dahil iisang opinyon lang ang mahalaga sa huli."
          ),
          t(
            "And Paul tells us what that Judge will look at: He “will bring to light the things now hidden in darkness and will disclose the purposes of the heart. Then each one will receive his commendation from God” (4:5). Commendation from God. Not from the barangay, not from the in-laws, not from the comment section. On that day, there will be people praised whom no one on earth ever praised: the helper who prayed for her employer's children, the security guard who returned the lost wallet, the mother who stayed faithful through a hard marriage.",
            "At sinabi ni Pablo kung ano ang titingnan ng Hukom na iyon: “Ilalantad Niya ang mga bagay na nakatago ngayon sa dilim at ibubunyag ang mga layunin ng puso. Saka tatanggapin ng bawat isa ang kanyang papuri mula sa Diyos” (4:5). Papuri mula sa Diyos. Hindi mula sa barangay, hindi mula sa mga biyenan, hindi mula sa comment section. Sa araw na iyon, may mga pupurihing hindi kailanman pinuri ng sinuman sa lupa: ang helper na nanalangin para sa mga anak ng amo niya, ang security guard na nagsauli ng nawawalang pitaka, ang nanay na nanatiling tapat sa mahirap na pagsasama."
          ),
          t(
            "God told Jeremiah what is worth boasting about: “Let not the wise man boast in his wisdom, let not the mighty man boast in his might, let not the rich man boast in his riches, but let him who boasts boast in this, that he understands and knows Me” (Jeremiah 9:23-24). Diplomas fade in the frame. Titles are forgotten a generation later. But to know God is a treasure no flood can wash away.",
            "Sinabi ng Diyos kay Jeremias kung ano ang dapat ipagmalaki: “Huwag magmalaki ang marunong sa kanyang karunungan, huwag magmalaki ang malakas sa kanyang lakas, huwag magmalaki ang mayaman sa kanyang kayamanan, kundi ang nagmamalaki ay magmalaki rito, na nauunawaan at kilala niya Ako” (Jeremias 9:23-24). Kumukupas ang diploma sa frame. Nakakalimutan ang mga titulo pagkalipas ng isang henerasyon. Pero ang makilala ang Diyos ay kayamanang hindi kayang tangayin ng anumang baha."
          ),
        ],
      },
      {
        heading: t("Measured at the finish line", "Sinusukat sa dulo ng karera"),
        body: [
          t(
            "Picture Paul in his last Roman prison. He is old, cold and mostly alone. He asks Timothy to bring the cloak he left in Troas, and his books and parchments (2 Timothy 4:13). Some friends have deserted him. He knows the executioner is near. By every worldly measure this is the end of a failed man, a prisoner with a borrowed coat. And from that cell he writes the most triumphant words of his life.",
            "Isipin mo si Pablo sa huli niyang bilangguan sa Roma. Matanda na siya, giniginaw at halos nag-iisa. Hiniling niya kay Timoteo na dalhin ang balabal na naiwan niya sa Troas, at ang mga aklat at mga sulat sa balat (2 Timoteo 4:13). Iniwan siya ng ilang kaibigan. Alam niyang malapit na ang berdugo. Sa bawat sukatan ng mundo, ito ang katapusan ng isang bigong lalaki, isang bilanggong nanghihiram ng balabal. At mula sa seldang iyon, isinulat niya ang pinakamatagumpay na mga salita ng buhay niya."
          ),
          t(
            "“I have fought the good fight, I have finished the race, I have kept the faith. Henceforth there is laid up for me the crown of righteousness, which the Lord, the righteous judge, will award to me on that Day, and not only to me but also to all who have loved His appearing” (2 Timothy 4:7-8). He did not list churches planted or books written, though there were many. He said: I fought, I finished, I kept. Success in God's eyes is measured at the finish line, and the finish line is faithfulness.",
            "“Nakipaglaban ako ng mabuting pakikipaglaban, natapos ko ang takbuhin, iningatan ko ang pananampalataya. Mula ngayon ay nakalaan sa akin ang korona ng katuwiran, na ibibigay sa akin ng Panginoon, ang matuwid na hukom, sa Araw na iyon, at hindi lamang sa akin kundi sa lahat ng umiibig sa Kanyang pagpapakita” (2 Timoteo 4:7-8). Hindi niya inilista ang mga simbahang itinanim o mga liham na isinulat, kahit marami iyon. Ang sinabi niya: nakipaglaban ako, natapos ko, iningatan ko. Sa paningin ng Diyos, sinusukat ang tagumpay sa dulo ng karera, at ang dulo ng karera ay katapatan."
          ),
          t(
            "This does not mean ambition is sinful or excellence unimportant. Work hard. Study well. Build the business. Pass the board if you can, and thank God if you do. But do it as a steward, not as a slave of other people's opinion. Jesus said, “One who is faithful in a very little is also faithful in much” (Luke 16:10). Start where you are. Be faithful with the little that is in your hands today. That is not a smaller life. It is the only kind that hears “Well done.”",
            "Hindi ibig sabihin nito na kasalanan ang ambisyon o hindi mahalaga ang kahusayan. Magsipag ka. Mag-aral nang mabuti. Itayo mo ang negosyo. Ipasa mo ang board kung kaya mo, at magpasalamat ka sa Diyos kapag nangyari. Pero gawin mo ito bilang katiwala, hindi bilang alipin ng opinyon ng iba. Sinabi ni Hesus, “Ang tapat sa napakaliit ay tapat din sa malaki” (Lucas 16:10). Magsimula ka kung nasaan ka. Maging tapat ka sa kaunting nasa kamay mo ngayon. Hindi iyan mas maliit na buhay. Iyan lang ang uri ng buhay na makaririnig ng “Magaling.”"
          ),
        ],
      },
    ],
    pullQuote: t(
      "God will not ask how high you climbed; He will ask what you did with what He placed in your hands.",
      "Hindi itatanong ng Diyos kung gaano kataas ang inakyat mo; itatanong Niya kung ano ang ginawa mo sa inilagay Niya sa iyong mga kamay."
    ),
    pastoralWord: [
      t(
        "My dear friend, if you are the one at the end of the table, the one who failed, the one whose name was never on a tarpaulin, I want you to lift your head. Your Master is not comparing you with your cousin. He knows exactly how many talents He gave you, and He is watching with a Father's eyes to see you use them in love. The bar exam of heaven is not brilliance. It is faithfulness, and by His grace you can pass it.",
        "Mahal kong kapatid, kung ikaw ang nasa dulo ng mesa, ang bumagsak, ang hindi kailanman nailagay ang pangalan sa tarpaulin, gusto kong itaas mo ang ulo mo. Hindi ka ikinukumpara ng Panginoon mo sa pinsan mo. Alam Niya kung ilang talento ang ibinigay Niya sa iyo, at nakatingin Siya nang may mata ng Ama para makita kang gamitin ang mga iyon sa pag-ibig. Hindi katalinuhan ang board exam ng langit. Katapatan ito, at sa biyaya Niya, kaya mo itong ipasa."
      ),
      t(
        "And if you are the one at the head of the table, successful and admired, I say this with love: check the scoreboard you are playing for. Sit down this week and write two sentences. First, how you have been measuring success. Second, how you want to finish your life, in the spirit of 2 Timothy 4:7. Pray over those sentences every day. Let God rewrite them until the only applause you live for is the sound of your Master saying, “Well done.”",
        "At kung ikaw ang nasa ulunan ng mesa, matagumpay at hinahangaan, sinasabi ko ito nang may pagmamahal: tingnan mo kung anong scoreboard ang pinaglalaruan mo. Umupo ka ngayong linggo at sumulat ng dalawang pangungusap. Una, kung paano mo sinusukat ang tagumpay hanggang ngayon. Ikalawa, kung paano mo gustong tapusin ang buhay mo, sa diwa ng 2 Timoteo 4:7. Ipanalangin mo ang mga pangungusap na iyon araw-araw. Hayaan mong isulat itong muli ng Diyos hanggang ang tanging palakpak na hinahanap mo ay ang tinig ng Panginoon mong nagsasabing, “Magaling.”"
      ),
    ],
    benediction: t(
      "May the Lord free you from every scoreboard that is not His. May He make you faithful in little things and joyful in hidden places. And on that Day, may you hear the voice you have lived for say, “Well done, good and faithful servant; enter into the joy of your master.” Amen.",
      "Palayain ka nawa ng Panginoon sa bawat scoreboard na hindi sa Kanya. Gawin ka nawa Niyang tapat sa maliliit na bagay at masaya sa mga tagong lugar. At sa Araw na iyon, marinig mo nawa ang tinig na pinamuhayan mo na nagsasabing, “Magaling, mabuti at tapat na alipin; pumasok ka sa kagalakan ng iyong panginoon.” Amen."
    ),
  },

  "c-bahala-na-vs-trust": {
    epigraph: {
      text: t(
        "The horse is made ready for the day of battle, but the victory belongs to the Lord.",
        "Inihahanda ang kabayo para sa araw ng labanan, ngunit ang tagumpay ay sa Panginoon."
      ),
      ref: t("Proverbs 21:31", "Kawikaan 21:31"),
    },
    opening: [
      t(
        "The radio announces that Signal Number Three has been raised over the province. On one side of the street, a family is busy. The father is on the roof tying down the yero with wire and sandbags. The mother is filling every pail and bottle with water. The children are putting documents into plastic bags and charging the flashlight. On the other side of the street, a neighbor sits on his bench with his coffee and watches them with an amused smile. “Bahala na,” he says. “Kung tatamaan, tatamaan.”",
        "Ibinalita sa radyo na itinaas na ang Signal Number Three sa probinsya. Sa isang panig ng kalye, abala ang isang pamilya. Nasa bubong ang tatay, tinatalian ng alambre at pinapatungan ng sako ng buhangin ang yero. Pinupuno ng nanay ng tubig ang bawat timba at bote. Isinisilid ng mga bata sa plastik ang mga dokumento at chinacharge ang flashlight. Sa kabilang panig ng kalye, nakaupo ang isang kapitbahay sa bangko niya na may hawak na kape at nakangiting pinanonood sila. “Bahala na,” sabi niya. “Kung tatamaan, tatamaan.”"
      ),
      t(
        "Which of the two trusts God more? Many would say the neighbor. He is so calm. He is leaving it to heaven. But when the wind dies down and the sun comes out, you will usually find that the family who prepared is praying a prayer of thanks, and the neighbor is praying a prayer of panic.",
        "Sino sa dalawa ang mas nagtitiwala sa Diyos? Marami ang magsasabing ang kapitbahay. Napakahinahon niya. Ipinapaubaya niya sa langit. Pero kapag humina na ang hangin at sumikat na ang araw, kadalasan makikita mong panalangin ng pasasalamat ang dasal ng pamilyang naghanda, at panalangin ng pagkataranta ang dasal ng kapitbahay."
      ),
      t(
        "Few phrases are more Filipino than “bahala na.” Some believe it comes from “Bathala na,” leave it to God. It has carried our people through wars, floods and poverty with a kind of stubborn courage. But it has also carried many of us into debt, unwanted pregnancies, failed exams and illegal recruiters. In this chapter I want to separate the gold in that phrase from the rust.",
        "Kakaunti ang pariralang mas Pilipino pa kaysa sa “bahala na.” Naniniwala ang ilan na galing ito sa “Bathala na,” ipaubaya sa Diyos. Dinala nito ang bayan natin sa gitna ng digmaan, baha at kahirapan nang may matigas na uri ng tapang. Pero dinala rin nito ang marami sa atin sa utang, sa hindi planadong pagbubuntis, sa bagsak na exam at sa mga illegal recruiter. Sa kabanatang ito, gusto kong paghiwalayin ang ginto sa pariralang iyan at ang kalawang."
      ),
    ],
    sections: [
      {
        heading: t("A phrase with two faces", "Pariralang may dalawang mukha"),
        body: [
          t(
            "There is a “bahala na” that is close to faith. Think of Queen Esther. Her people faced extermination, and the only hope was for her to go to the king uninvited, which could mean death. She did not shrug. She called the Jews of the city to fast for three days, and she and her maids fasted too. Then she said, “I will go to the king, though it is against the law, and if I perish, I perish” (Esther 4:16). That is courage that has prayed, planned and then stepped forward, leaving the outcome to God.",
            "May “bahala na” na malapit sa pananampalataya. Isipin mo si Reyna Ester. Haharapin ng bayan niya ang paglipol, at ang tanging pag-asa ay lumapit siya sa hari nang hindi ipinatatawag, na maaaring mangahulugan ng kamatayan. Hindi siya nagkibit-balikat. Tinawag niya ang mga Judio sa lungsod na mag-ayuno nang tatlong araw, at nag-ayuno rin siya at ang mga alalay niya. Saka niya sinabi, “Pupunta ako sa hari, kahit labag ito sa batas, at kung mamatay ako, mamatay ako” (Ester 4:16). Iyan ang tapang na nanalangin, nagplano, saka humakbang pasulong, ipinauubaya sa Diyos ang kalalabasan."
          ),
          t(
            "But there is another “bahala na,” and it wears a religious costume over a very unspiritual heart. “Bahala na kung mabuntis.” “Bahala na sa exam.” “Bahala na kung saan mapunta ang pera.” “Bahala na sa agency, basta makaalis.” This is not trust. It is avoidance. It is the decision not to think about something hard, and then calling that decision faith.",
            "Pero may isa pang “bahala na,” at nakadamit-relihiyoso ito sa ibabaw ng pusong hindi naman espirituwal. “Bahala na kung mabuntis.” “Bahala na sa exam.” “Bahala na kung saan mapunta ang pera.” “Bahala na sa agency, basta makaalis.” Hindi iyan pagtitiwala. Pag-iwas iyan. Iyan ang pasyang huwag isipin ang isang mahirap na bagay, saka tinatawag ang pasyang iyon na pananampalataya."
          ),
          t(
            "The difference is not in the words. It is in what came before them. Esther fasted three days before she said, “If I perish, I perish.” The neighbor on the bench said “bahala na” instead of climbing the roof. One is faith at the end of obedience. The other is laziness at the beginning of disaster.",
            "Wala sa mga salita ang pagkakaiba. Nasa nauna sa mga ito. Tatlong araw nag-ayuno si Ester bago niya sinabing, “Kung mamatay ako, mamatay ako.” Sinabi ng kapitbahay sa bangko ang “bahala na” sa halip na umakyat sa bubong. Ang isa ay pananampalataya sa dulo ng pagsunod. Ang isa ay katamaran sa simula ng sakuna."
          ),
        ],
      },
      {
        heading: t("Nehemiah's two hands", "Ang dalawang kamay ni Nehemias"),
        body: [
          t(
            "When Nehemiah came back to rebuild the walls of Jerusalem, the city was a heap of burned stones. Enemies laughed. Sanballat mocked them: “Will they revive the stones out of the heaps of rubbish, and burned ones at that?” (Nehemiah 4:2). Then the mockery became a plot. They planned to attack and throw the work into confusion.",
            "Nang bumalik si Nehemias para itayong muli ang mga pader ng Jerusalem, tambak na lang ng sunog na bato ang lungsod. Pinagtawanan sila ng mga kaaway. Kinutya sila ni Sanbalat: “Bubuhayin ba nila ang mga bato mula sa tambak ng basura, at sunog pa ang mga iyon?” (Nehemias 4:2). Saka naging balak ang pangungutya. Nagplano silang sumalakay at guluhin ang gawain."
          ),
          t(
            "Here is what Nehemiah did, in one verse that every Filipino believer should memorize: “And we prayed to our God and set a guard as a protection against them day and night” (4:9). Prayed and set a guard. Not one or the other. He organized the people by families behind the low places of the wall with swords, spears and bows. Half the men worked while half held the spears. The builders worked with one hand and held a weapon with the other (4:16-17). A trumpeter stood beside Nehemiah so that if an attack came anywhere, everyone would rally there.",
            "Ito ang ginawa ni Nehemias, sa isang talatang dapat isaulo ng bawat mananampalatayang Pilipino: “Kaya nanalangin kami sa aming Diyos at naglagay ng bantay laban sa kanila araw at gabi” (4:9). Nanalangin at naglagay ng bantay. Hindi isa lang sa dalawa. Inayos niya ang mga tao ayon sa pamilya sa likod ng mabababang bahagi ng pader na may mga tabak, sibat at pana. Kalahati ng mga lalaki ang nagtatrabaho habang ang kalahati ay may hawak na sibat. Isang kamay ang ginagamit ng mga nagtatayo sa trabaho at ang isa ay may hawak na sandata (4:16-17). May tagahihip ng trumpeta sa tabi ni Nehemias para kung saan man may sumalakay, doon magtitipon ang lahat."
          ),
          t(
            "And then he said, “Our God will fight for us” (4:20). Do you see it? The man who posted guards and armed builders was the same man who declared that God would fight. He did not see any contradiction. His planning did not mean he doubted God. His faith did not mean he stopped planning. And the wall that the enemies laughed at was finished in fifty-two days, so that even the surrounding nations “perceived that this work had been accomplished with the help of our God” (6:15-16).",
            "At saka niya sinabi, “Ang ating Diyos ang makikipaglaban para sa atin” (4:20). Nakikita mo ba? Ang lalaking naglagay ng bantay at nag-armas sa mga nagtatayo ay siya ring nagpahayag na ang Diyos ang makikipaglaban. Wala siyang nakitang salungatan doon. Hindi nangangahulugan ang pagpaplano niya na nag-aalinlangan siya sa Diyos. Hindi nangangahulugan ang pananampalataya niya na tumigil na siyang magplano. At ang pader na pinagtawanan ng mga kaaway ay natapos sa limampu't dalawang araw, anupa't kahit ang mga bansa sa paligid ay “nakilala na ang gawaing ito ay natapos sa tulong ng ating Diyos” (6:15-16)."
          ),
        ],
      },
      {
        heading: t("Getting the horse ready", "Paghahanda sa kabayo"),
        body: [
          t(
            "Solomon put it in one line: “The horse is made ready for the day of battle, but the victory belongs to the Lord” (Proverbs 21:31). Both halves are true at the same time. You feed the horse, train the horse, check its shoes, sharpen your sword. And then you go into battle knowing that the outcome is not finally in your hands.",
            "Inilagay ito ni Solomon sa iisang linya: “Inihahanda ang kabayo para sa araw ng labanan, ngunit ang tagumpay ay sa Panginoon” (Kawikaan 21:31). Sabay na totoo ang dalawang bahagi. Pinakakain mo ang kabayo, sinasanay, tinitingnan ang sapatos nito, hinahasa ang espada mo. Saka ka papasok sa labanan na alam mong wala sa kamay mo, sa huli, ang kalalabasan."
          ),
          t(
            "What does it look like to get the horse ready in your life? For an aspiring OFW, it means checking whether the agency is licensed with the proper government office before paying a single peso, reading the contract, and asking a pastor or a trusted friend for counsel. For a family, it means an emergency fund, even a small one, and a go-bag before typhoon season. For your body, it means the checkup you have been putting off. For a student, it means studying for the exam, not just praying the night before.",
            "Ano ang hitsura ng paghahanda ng kabayo sa buhay mo? Para sa nagbabalak mag-OFW, ibig sabihin nito ay alamin kung lisensyado ang agency sa tamang opisina ng gobyerno bago magbayad ng kahit isang piso, basahin ang kontrata, at humingi ng payo sa pastor o sa isang pinagkakatiwalaang kaibigan. Para sa isang pamilya, ibig sabihin nito ay emergency fund, kahit maliit, at go-bag bago ang tag-ulan. Para sa katawan mo, ibig sabihin nito ay ang checkup na matagal mo nang ipinagpapaliban. Para sa estudyante, ibig sabihin nito ay mag-aral para sa exam, hindi lang manalangin sa gabi bago ito."
          ),
          t(
            "“The prudent sees danger and hides himself, but the simple go on and suffer for it” (Proverbs 27:12). God gave you eyes to see danger and a mind to respond to it. Using them is not a lack of faith. Refusing to use them is not a sign of great faith. It is what Proverbs calls being simple. Joseph did not tell Pharaoh, “God showed us seven years of famine, so bahala na.” He built storehouses for seven years (Genesis 41:33-36). That is faith with a shovel in its hand.",
            "“Nakikita ng matalino ang panganib at nagtatago siya, ngunit nagpapatuloy ang walang muwang at nagdurusa dahil dito” (Kawikaan 27:12). Binigyan ka ng Diyos ng mata para makita ang panganib at isip para tumugon dito. Ang paggamit sa mga iyon ay hindi kakulangan ng pananampalataya. Ang pagtangging gamitin ang mga iyon ay hindi tanda ng malaking pananampalataya. Iyan ang tinatawag ng Kawikaan na pagiging walang muwang. Hindi sinabi ni Jose kay Faraon, “Ipinakita ng Diyos sa atin ang pitong taon ng taggutom, kaya bahala na.” Nagtayo siya ng mga kamalig sa loob ng pitong taon (Genesis 41:33-36). Iyan ang pananampalatayang may hawak na pala."
          ),
        ],
      },
      {
        heading: t("When planning becomes its own idol", "Kapag naging diyus-diyosan na ang pagpaplano"),
        body: [
          t(
            "Now I must turn to the other side, because some of you reading this have never said “bahala na” in your life. You have a plan A, B and C. You have spreadsheets for your spreadsheets. And you cannot sleep. Your problem is not careless faith. It is anxious control. And it is just as far from biblical trust.",
            "Ngayon, kailangan kong humarap sa kabilang panig, dahil may ilan sa inyong nagbabasa nito na hindi kailanman nagsabi ng “bahala na” sa buong buhay ninyo. May plan A, B at C kayo. May spreadsheet pa ang mga spreadsheet ninyo. At hindi kayo makatulog. Hindi pabayang pananampalataya ang problema mo. Balisang pagkontrol ito. At kasinlayo rin ito sa biblikal na pagtitiwala."
          ),
          t(
            "James wrote to people like this: “Come now, you who say, ‘Today or tomorrow we will go into such and such a town and spend a year there and trade and make a profit’; yet you do not know what tomorrow will bring. What is your life? For you are a mist... Instead you ought to say, ‘If the Lord wills, we will live and do this or that’” (James 4:13-15). James does not forbid the plan. He forbids the plan that has forgotten God.",
            "Sumulat si Santiago sa mga taong ganito: “Halikayo ngayon, kayong nagsasabing, ‘Ngayon o bukas ay pupunta kami sa ganitong lungsod at mananatili roon nang isang taon, makikipagkalakalan at kikita’; gayong hindi ninyo alam kung ano ang mangyayari bukas. Ano ang inyong buhay? Sapagkat kayo ay ulap... Sa halip ay dapat ninyong sabihin, ‘Kung loloobin ng Panginoon, mabubuhay kami at gagawin namin ito o iyon’” (Santiago 4:13-15). Hindi ipinagbabawal ni Santiago ang plano. Ipinagbabawal niya ang planong nakalimot na sa Diyos."
          ),
          t(
            "Think of Martha in Bethany, “distracted with much serving,” working hard for Jesus while being unable to sit with Him (Luke 10:40-42). Her problem was not that she cooked. Somebody had to cook. Her problem was that her work had swallowed her peace. Jesus said, “You are anxious and troubled about many things, but one thing is necessary.” The cure for anxious control is not to stop planning. It is to plan at the feet of Jesus.",
            "Isipin mo si Marta sa Betania, “abalang-abala sa maraming paglilingkod,” masipag na nagtatrabaho para kay Hesus pero hindi makaupo kasama Niya (Lucas 10:40-42). Hindi ang pagluluto ang problema niya. May kailangang magluto. Ang problema ay nilamon na ng trabaho niya ang kapayapaan niya. Sinabi ni Hesus, “Nababalisa ka at nababagabag sa maraming bagay, ngunit iisa lang ang kailangan.” Ang lunas sa balisang pagkontrol ay hindi pagtigil sa pagpaplano. Ito ay pagpaplano sa paanan ni Hesus."
          ),
        ],
      },
      {
        heading: t("Trust has feet", "May mga paa ang pagtitiwala"),
        body: [
          t(
            "When Israel finally reached the Jordan, it was harvest season and the river was overflowing its banks (Joshua 3:15). God had promised to open the way. But He gave the priests carrying the ark an instruction: walk into the water. Not stand on the bank and pray for the river to part. Walk in. And Scripture says that “as soon as the feet of the priests bearing the ark were dipped in the brink of the water,” the waters upstream stopped and rose up in a heap (3:15-16).",
            "Nang sa wakas ay makarating ang Israel sa Jordan, panahon ng anihan at umaapaw ang ilog sa mga pampang nito (Josue 3:15). Nangako ang Diyos na bubuksan Niya ang daan. Pero binigyan Niya ng bilin ang mga paring nagpapasan ng kaban: lumakad sa tubig. Hindi tumayo sa pampang at manalanging mahati ang ilog. Lumakad. At sinasabi ng Kasulatan na “nang lumubog sa gilid ng tubig ang mga paa ng mga paring nagpapasan ng kaban,” tumigil ang tubig sa itaas at nagbunton (3:15-16)."
          ),
          t(
            "That is what biblical trust looks like. It has feet. It takes the step God has shown, even when the outcome is not yet visible, and then it watches God do what only God can do. “Commit your work to the Lord, and your plans will be established” (Proverbs 16:3). Notice: your work, your plans. God does not establish plans you never made or bless work you never did.",
            "Ganyan ang hitsura ng biblikal na pagtitiwala. May mga paa ito. Ginagawa nito ang hakbang na ipinakita ng Diyos, kahit hindi pa nakikita ang kalalabasan, saka pinanonood ang Diyos na gawin ang Siya lang ang makagagawa. “Ipagkatiwala mo ang iyong gawain sa Panginoon, at matatatag ang iyong mga plano” (Kawikaan 16:3). Pansinin mo: ang iyong gawain, ang iyong mga plano. Hindi itinatatag ng Diyos ang mga planong hindi mo ginawa o pinagpapala ang trabahong hindi mo tinrabaho."
          ),
          t(
            "So I want to give you a new phrase, one that keeps the gold of our old one and throws away the rust: “Bahala ang Diyos, pero gagawin ko ang bahagi ko.” God is in charge, and I will do my part. Pray, then plan. Prepare, then trust. Do the next right thing God has shown you, then lay your head on the pillow and sleep, because the One who watches over you neither slumbers nor sleeps (Psalm 121:4).",
            "Kaya gusto kong bigyan ka ng bagong parirala, isang nagtatago ng ginto ng dati nating parirala at nagtatapon ng kalawang: “Bahala ang Diyos, pero gagawin ko ang bahagi ko.” Manalangin, saka magplano. Maghanda, saka magtiwala. Gawin ang susunod na tamang hakbang na ipinakita ng Diyos, saka ihiga ang ulo sa unan at matulog, dahil ang nagbabantay sa iyo ay hindi umiidlip ni natutulog (Awit 121:4)."
          ),
        ],
      },
    ],
    pullQuote: t(
      "“Bahala na” shrugs at the future; faith kneels before the God who holds it, then stands up and gets to work.",
      "Nagkikibit-balikat ang “bahala na” sa kinabukasan; lumuluhod ang pananampalataya sa Diyos na may hawak nito, saka tumatayo at nagtatrabaho."
    ),
    pastoralWord: [
      t(
        "Beloved, there is probably one area of your life where you have been saying “bahala na” because looking at it squarely is too frightening. The debt you have not added up. The lump you have not had checked. The conversation with your teenager you keep postponing. The contract you signed without reading. I am not saying this to shame you. I am saying it because your Father loves you too much to let you drift. This week, take one step toward the thing you have been avoiding. Just one.",
        "Minamahal, malamang may isang bahagi ng buhay mo kung saan sinasabi mong “bahala na” dahil nakakatakot itong harapin nang diretso. Ang utang na hindi mo pa kinukuwenta. Ang bukol na hindi mo pa ipinatitingin. Ang usapan sa anak mong teenager na lagi mong ipinagpapaliban. Ang kontratang pinirmahan mo nang hindi binabasa. Hindi ko ito sinasabi para ipahiya ka. Sinasabi ko ito dahil mahal ka ng Ama mo nang sobra para hayaan kang magpaanod. Ngayong linggo, humakbang ka ng isa papunta sa bagay na iniiwasan mo. Isa lang."
      ),
      t(
        "And if you are the one who controls everything and cannot rest, then your step is different. Write down your plans, every one of them, and then pray over the list and say, “Lord, if You will.” Then put the list down and go to sleep. Both of you, the drifter and the worrier, are invited to the same place: the feet of Jesus, where we learn to work hard and rest deeply at the same time.",
        "At kung ikaw naman ang kumokontrol sa lahat at hindi makapagpahinga, iba ang hakbang mo. Isulat mo ang mga plano mo, lahat ng iyon, saka ipanalangin ang listahan at sabihin, “Panginoon, kung loloobin Mo.” Pagkatapos, ibaba mo ang listahan at matulog ka. Kayong dalawa, ang nagpapaanod at ang nag-aalala, ay inaanyayahan sa iisang lugar: ang paanan ni Hesus, kung saan natututo tayong magsipag at magpahinga nang malalim nang sabay."
      ),
    ],
    benediction: t(
      "May the God who parted the Jordan give you courage to step into the water. May He teach your hands to work and your heart to rest. And may every plan you commit to Him be established, for the victory belongs to the Lord. Amen.",
      "Ang Diyos na naghati sa Jordan ay bigyan ka nawa ng tapang na humakbang sa tubig. Turuan nawa Niya ang mga kamay mong magtrabaho at ang puso mong magpahinga. At ang bawat planong ipagkatiwala mo sa Kanya nawa'y matatag, sapagkat ang tagumpay ay sa Panginoon. Amen."
    ),
  },

  "c-yolo-vs-eternity": {
    epigraph: {
      text: t(
        "So teach us to number our days that we may get a heart of wisdom.",
        "Kaya turuan Mo kaming bilangin ang aming mga araw, upang magkaroon kami ng pusong may karunungan."
      ),
      ref: t("Psalm 90:12", "Awit 90:12"),
    },
    opening: [
      t(
        "Every Filipino knows the sounds of a lamay. The low murmur of relatives in plastic chairs. The clink of coffee cups. The shuffle of cards at a table near the gate, because someone has to keep the family awake through the night. And at the front, the coffin with the photo on a stand, and below it two dates separated by a little dash.",
        "Kilala ng bawat Pilipino ang mga tunog ng lamay. Ang mahinang usapan ng mga kamag-anak sa mga plastik na upuan. Ang kalansing ng mga tasa ng kape. Ang balasa ng baraha sa mesang malapit sa gate, dahil may kailangang magpuyat kasama ng pamilya. At sa harap, ang kabaong na may litrato sa patungan, at sa ilalim nito ay dalawang petsang pinaghihiwalay ng isang maliit na guhit."
      ),
      t(
        "Stand at the back long enough and you will notice what people talk about. Nobody mentions the brand of his cellphone. Nobody brings up how many likes her posts used to get. They talk about how he made everyone laugh, how she prayed for each of her grandchildren by name, how he lent money and never asked for it back, or, sadly, how he was never home. The dash, it turns out, is what everyone remembers.",
        "Tumayo ka nang matagal sa likod at mapapansin mo kung ano ang pinag-uusapan ng mga tao. Walang bumabanggit sa brand ng cellphone niya. Walang nagkukuwento kung ilang likes ang nakukuha ng mga post niya. Pinag-uusapan kung paano niya pinatatawa ang lahat, kung paano niya ipinapanalangin isa-isa sa pangalan ang mga apo niya, kung paano siya nagpapahiram ng pera at hindi na sinisingil, o, nakalulungkot, kung paano siya hindi kailanman nasa bahay. Ang guhit pala ang naaalala ng lahat."
      ),
      t(
        "Our generation has a word for how to live the dash: YOLO. You only live once. Book the trip. Buy the phone. Do the thing. And I will tell you something that may surprise you. The slogan is half true. The tragedy is in which half people choose to believe.",
        "May salita ang henerasyon natin kung paano ipamuhay ang guhit na iyon: YOLO. You only live once. I-book ang biyahe. Bilhin ang phone. Gawin mo na. At may sasabihin akong baka ikagulat mo. Kalahating totoo ang slogan. Ang trahedya ay nasa kung aling kalahati ang pinipiling paniwalaan ng mga tao."
      ),
    ],
    sections: [
      {
        heading: t("Half a truth is a whole lie", "Ang kalahating katotohanan ay buong kasinungalingan"),
        body: [
          t(
            "Scripture agrees with the first half. We do live once on this earth. “It is appointed for man to die once, and after that comes judgment” (Hebrews 9:27). There is no second run, no reincarnation, no reset button. James puts it bluntly: “What is your life? For you are a mist that appears for a little time and then vanishes” (James 4:14). Like the steam rising from your morning coffee. There, and then gone.",
            "Sang-ayon ang Kasulatan sa unang kalahati. Minsan lang talaga tayong mabubuhay sa lupang ito. “Itinakda sa tao na mamatay nang minsan, at pagkatapos nito ay ang paghuhukom” (Hebreo 9:27). Walang ikalawang takbo, walang reincarnation, walang reset button. Diretsahan si Santiago: “Ano ang inyong buhay? Sapagkat kayo ay singaw na lumilitaw nang sandali at pagkatapos ay naglalaho” (Santiago 4:14). Gaya ng usok na umaakyat mula sa kape mo sa umaga. Nandiyan, tapos wala na."
          ),
          t(
            "But YOLO draws the wrong conclusion from a true premise. It says: because life is short, grab everything now. It is not a new idea. Paul quoted the YOLO of his own day: “If the dead are not raised, ‘Let us eat and drink, for tomorrow we die’” (1 Corinthians 15:32). And Paul was himself quoting Isaiah, who heard those words in Jerusalem while an enemy army surrounded the city. God had called the people to weeping and repentance, and instead they slaughtered oxen and opened the wine (Isaiah 22:12-13). The enemy was at the gate, and they threw a party.",
            "Pero mali ang konklusyong hinuhugot ng YOLO mula sa totoong simula. Sinasabi nito: dahil maikli ang buhay, kunin mo na ang lahat ngayon. Hindi ito bagong ideya. Sinipi ni Pablo ang YOLO ng panahon niya: “Kung hindi ibinabangon ang mga patay, ‘Kumain tayo at uminom, sapagkat bukas tayo ay mamamatay’” (1 Corinto 15:32). At si Pablo mismo ay sumisipi kay Isaias, na nakarinig ng mga salitang iyon sa Jerusalem habang nakapalibot sa lungsod ang hukbo ng kaaway. Tinawag ng Diyos ang bayan sa pagtangis at pagsisisi, pero sa halip ay nagkatay sila ng baka at nagbukas ng alak (Isaias 22:12-13). Nasa pintuan na ang kaaway, at nagparty sila."
          ),
          t(
            "That is the deep problem with YOLO. It is not just that it wastes money. It is that it assumes death is the end of the story. Paul's whole argument is: if Christ is not raised, then fine, party. But Christ has been raised (15:20). And if He is risen, then the dash between your two dates is not a short story that ends in silence. It is the first chapter of a book that never ends.",
            "Iyan ang malalim na problema ng YOLO. Hindi lang na nag-aaksaya ito ng pera. Ipinapalagay nito na ang kamatayan ang katapusan ng kuwento. Ang buong argumento ni Pablo ay: kung hindi nabuhay na muli si Cristo, sige, magparty kayo. Pero nabuhay na muli si Cristo (15:20). At kung buhay Siya, ang guhit sa pagitan ng dalawang petsa mo ay hindi maikling kuwentong nagtatapos sa katahimikan. Ito ang unang kabanata ng isang aklat na hindi natatapos."
          ),
        ],
      },
      {
        heading: t("Moses counts the days", "Binibilang ni Moises ang mga araw"),
        body: [
          t(
            "Psalm 90 is the only psalm that bears the name of Moses, and when you know his life you understand why it sounds the way it does. He led a generation out of Egypt and then buried that generation in the wilderness, one grave after another, for forty years. If any man knew the shortness of life, it was Moses. “The years of our life are seventy, or even by reason of strength eighty; yet their span is but toil and trouble; they are soon gone, and we fly away” (Psalm 90:10).",
            "Ang Awit 90 lang ang awit na may pangalan ni Moises, at kapag kilala mo ang buhay niya, mauunawaan mo kung bakit ganito ang tunog nito. Inilabas niya ang isang henerasyon mula sa Egipto at pagkatapos ay inilibing ang henerasyong iyon sa ilang, isang libingan pagkatapos ng isa, sa loob ng apatnapung taon. Kung may taong nakaaalam kung gaano kaikli ang buhay, si Moises iyon. “Ang mga taon ng aming buhay ay pitumpu, o kung malakas ay walumpu; gayunma'y pagod at kabagabagan ang mga iyon; madaling lumilipas, at kami ay lumilipad” (Awit 90:10)."
          ),
          t(
            "But notice what Moses does with that knowledge. He does not say, “So let's eat and drink.” He prays, “So teach us to number our days that we may get a heart of wisdom” (90:12). Numbering your days is not morbid. It is clarifying. When you realize the days are numbered, you start asking which of them you are wasting, and on what.",
            "Pero pansinin mo kung ano ang ginawa ni Moises sa kaalamang iyon. Hindi niya sinabing, “Kaya kumain at uminom tayo.” Nanalangin siya, “Kaya turuan Mo kaming bilangin ang aming mga araw, upang magkaroon kami ng pusong may karunungan” (90:12). Hindi nakakapanlumo ang pagbilang sa mga araw mo. Nililinaw nito ang lahat. Kapag naunawaan mong bilang ang mga araw, magsisimula kang magtanong kung alin sa mga iyon ang sinasayang mo, at saan."
          ),
          t(
            "Try this. Take your age and imagine you are given Moses' seventy years. Subtract. Now multiply the remaining years by fifty-two. That is roughly how many Sundays you may have left, how many weeks to love your parents, to raise your children, to tell your barkada about Jesus. For a man of thirty-five, it is around eighteen hundred weeks. That is not very many. Moses would say: then do not waste them on things that will not matter at your lamay.",
            "Subukan mo ito. Kunin mo ang edad mo at isipin mong binigyan ka ng pitumpung taon gaya ng kay Moises. Ibawas mo. Ngayon, i-multiply mo sa limampu't dalawa ang natitirang mga taon. Iyan, humigit-kumulang, ang bilang ng mga Linggong maaaring natitira sa iyo, ilang linggo pa para mahalin ang mga magulang mo, palakihin ang mga anak mo, sabihin sa barkada mo ang tungkol kay Hesus. Para sa lalaking tatlumpu't limang taong gulang, mga isang libo't walong daang linggo iyan. Hindi iyan napakarami. Sasabihin ni Moises: kung gayon, huwag mo itong sayangin sa mga bagay na walang halaga sa lamay mo."
          ),
        ],
      },
      {
        heading: t("Esau's bowl of stew", "Ang mangkok ng nilaga ni Esau"),
        body: [
          t(
            "If YOLO has a patron saint in the Bible, it is Esau. He came in from the field exhausted and starving, and smelled the red lentil stew his brother Jacob was cooking. “Let me eat some of that red stew, for I am exhausted!” Jacob, sly as ever, asked for his birthright in exchange: the double inheritance and the spiritual leadership of the family, the line of the promise of God. And Esau said the most YOLO sentence in Scripture: “I am about to die; of what use is a birthright to me?” (Genesis 25:30-32).",
            "Kung may patron ang YOLO sa Bibliya, si Esau iyon. Galing siya sa bukid, pagod na pagod at gutom na gutom, at naamoy niya ang pulang nilagang lentehas na niluluto ng kapatid niyang si Jacob. “Pakainin mo ako ng pulang nilagang iyan, sapagkat pagod na pagod ako!” Si Jacob, tuso gaya ng dati, ay humingi ng kanyang pagkapanganay kapalit nito: ang dobleng mana at ang espirituwal na pamumuno sa pamilya, ang linya ng pangako ng Diyos. At sinabi ni Esau ang pinaka-YOLO na pangungusap sa Kasulatan: “Malapit na akong mamatay; ano ang silbi sa akin ng pagkapanganay?” (Genesis 25:30-32)."
          ),
          t(
            "Then come four short verbs that describe so many lives: “He ate and drank and rose and went his way. Thus Esau despised his birthright” (25:34). He traded something eternal for something that would be digested by evening. Hebrews later warns us not to be like Esau, “who sold his birthright for a single meal,” and adds that afterward, when he wanted the blessing, he could not get it back, though he sought it with tears (Hebrews 12:16-17).",
            "Saka dumating ang apat na maiikling pandiwang naglalarawan sa napakaraming buhay: “Kumain siya at uminom, tumayo at umalis. Ganito hinamak ni Esau ang kanyang pagkapanganay” (25:34). Ipinagpalit niya ang isang bagay na walang hanggan sa isang bagay na matutunaw na sa tiyan pagsapit ng gabi. Kalaunan, nagbabala ang Hebreo na huwag tayong maging gaya ni Esau, “na ipinagbili ang kanyang pagkapanganay dahil sa isang kainan,” at idinagdag na pagkatapos, nang gustuhin niya ang pagpapala, hindi na niya ito nabawi, kahit hinanap niya ito nang may luha (Hebreo 12:16-17)."
          ),
          t(
            "Esau's stew comes in many flavors today. The weekend binge that costs a marriage. The shortcut at work that costs a conscience. The relationship that feels urgent tonight and costs years of regret. The endless scrolling that costs the hours you meant to give to God and your children. Every one of them comes with the same voice: “I'm starving now. What use is eternity to me?” Learn to recognize that voice. It is the voice of the stew.",
            "Maraming lasa ang nilaga ni Esau ngayon. Ang weekend na labis na pagpapakasaya na ang kapalit ay pagsasama ng mag-asawa. Ang shortcut sa trabaho na ang kapalit ay konsensya. Ang relasyong parang hindi na makapaghintay ngayong gabi at ang kapalit ay mga taon ng pagsisisi. Ang walang-katapusang pag-scroll na ang kapalit ay mga oras na balak mo sanang ibigay sa Diyos at sa mga anak mo. Iisang boses ang kasama ng bawat isa: “Gutom na gutom ako ngayon. Ano ang silbi ng walang hanggan sa akin?” Matutunan mong kilalanin ang boses na iyan. Boses iyan ng nilaga."
          ),
        ],
      },
      {
        heading: t("Treasure where moths cannot follow", "Kayamanang hindi maaabot ng gamugamo"),
        body: [
          t(
            "Jesus never told us to stop storing up treasure. He told us where to store it. “Do not lay up for yourselves treasures on earth, where moth and rust destroy and where thieves break in and steal, but lay up for yourselves treasures in heaven... For where your treasure is, there your heart will be also” (Matthew 6:19-21). Every balikbayan box eventually gets emptied. Every new phone becomes an old phone. But some things you can send ahead.",
            "Hindi kailanman sinabi ni Hesus na tumigil tayo sa pag-iipon ng kayamanan. Sinabi Niya kung saan ito iipunin. “Huwag kayong mag-ipon para sa inyong sarili ng kayamanan sa lupa, kung saan sinisira ito ng gamugamo at kalawang at kung saan pumapasok ang mga magnanakaw at nagnanakaw, kundi mag-ipon kayo para sa inyong sarili ng kayamanan sa langit... Sapagkat kung nasaan ang iyong kayamanan, naroon din ang iyong puso” (Mateo 6:19-21). Bawat balikbayan box ay nauubos din sa huli. Bawat bagong phone ay nagiging lumang phone. Pero may mga bagay na puwede mong ipadala nang maaga."
          ),
          t(
            "What goes ahead? People. A soul you led to Christ will be in heaven. A young believer you discipled will be there. The prayers you prayed are kept before God like incense (Revelation 5:8). The cup of cold water given in Jesus' name will not lose its reward (Matthew 10:42). Character shaped by the Spirit is not left at the grave. These are the only investments with an eternal return.",
            "Ano ang nauuna? Mga tao. Ang kaluluwang naakay mo kay Cristo ay nasa langit. Ang batang mananampalatayang dinisipulo mo ay naroon. Ang mga panalanging ipinanalangin mo ay iniingatan sa harap ng Diyos gaya ng insenso (Pahayag 5:8). Ang basong malamig na tubig na ibinigay sa pangalan ni Hesus ay hindi mawawalan ng gantimpala (Mateo 10:42). Ang pagkataong hinubog ng Espiritu ay hindi naiiwan sa libingan. Ito lang ang mga pamumuhunang may walang hanggang tubo."
          ),
          t(
            "Charles Thomas Studd was one of the most famous cricketers in England in the 1880s. He had wealth, fame and a bright future. He gave much of his inheritance away and went to China as one of a group of Cambridge students who became known as the Cambridge Seven, and later served in India and Africa. He wrote a short poem that has hung on the walls of many Filipino homes and churches: “Only one life, 'twill soon be past, only what's done for Christ will last.” That is the true answer to YOLO. Yes, you only live once. That is precisely why it must be lived for Him.",
            "Si Charles Thomas Studd ay isa sa pinakasikat na manlalaro ng cricket sa Inglatera noong dekada 1880. May yaman siya, kasikatan at magandang kinabukasan. Ipinamigay niya ang malaking bahagi ng kanyang mana at pumunta sa Tsina bilang isa sa grupo ng mga estudyante ng Cambridge na nakilala bilang Cambridge Seven, at kalaunan ay naglingkod sa India at Aprika. Sumulat siya ng maikling tula na nakasabit sa pader ng maraming tahanan at simbahang Pilipino: “Only one life, 'twill soon be past, only what's done for Christ will last.” Iisa lang ang buhay, at lilipas din; ang ginawa lang para kay Cristo ang mananatili. Iyan ang tunay na sagot sa YOLO. Oo, minsan ka lang mabubuhay. Iyan mismo ang dahilan kung bakit dapat itong ipamuhay para sa Kanya."
          ),
        ],
      },
      {
        heading: t("Not less joy, but deeper", "Hindi mas kaunting saya, kundi mas malalim"),
        body: [
          t(
            "Some people hear all this and imagine that living for eternity means a grey, joyless life with no birthday parties and no beach trips. Nothing could be further from the Bible. The same Preacher who said “Remember also your Creator in the days of your youth” (Ecclesiastes 12:1) also said, “Go, eat your bread with joy, and drink your wine with a merry heart, for God has already approved what you do” (9:7). Paul wrote that God “richly provides us with everything to enjoy” (1 Timothy 6:17).",
            "May mga taong nakaririnig nito at iniisip na ang pamumuhay para sa walang hanggan ay malamlam at walang sayang buhay na walang birthday party at walang outing sa beach. Napakalayo niyan sa Bibliya. Ang Mangangaral na nagsabing “Alalahanin mo rin ang iyong Lumikha sa mga araw ng iyong kabataan” (Eclesiastes 12:1) ay siya ring nagsabing, “Humayo ka, kainin mo ang iyong tinapay nang may kagalakan, at inumin mo ang iyong alak nang may masayang puso, sapagkat sinang-ayunan na ng Diyos ang iyong ginagawa” (9:7). Isinulat ni Pablo na ang Diyos ay “saganang nagbibigay sa atin ng lahat ng bagay upang ating tamasahin” (1 Timoteo 6:17)."
          ),
          t(
            "In fact, the person living for eternity is the one most free to enjoy today. The YOLO person must squeeze every drop out of this life because it is all he has, and so he is anxious, always afraid of missing out. The believer can rest, laugh, give things away and miss a few things, because the best is not behind him. It is ahead. “This light momentary affliction is preparing for us an eternal weight of glory beyond all comparison” (2 Corinthians 4:17).",
            "Sa katunayan, ang taong nabubuhay para sa walang hanggan ang pinakamalayang magsaya ngayon. Kailangang pigain ng taong YOLO ang bawat patak ng buhay na ito dahil ito lang ang mayroon siya, kaya balisa siya, laging takot na maiwan. Kayang magpahinga, tumawa, mamigay at maiwan sa ilang bagay ng mananampalataya, dahil wala sa likod niya ang pinakamaganda. Nasa unahan ito. “Ang magaan at panandaliang kapighatiang ito ay naghahanda para sa atin ng walang hanggang bigat ng kaluwalhatian na hindi maihahambing” (2 Corinto 4:17)."
          ),
          t(
            "So enjoy your merienda. Take the family to the beach. Laugh until your stomach hurts at the reunion. But hold it all with an open hand, and keep your eyes lifted. You only live once on this earth. Live it so that when the dash is finished and the cards are being shuffled at your lamay, someone will say, “He lived for Jesus,” and in heaven a crowd you helped bring there will be waiting to welcome you home.",
            "Kaya i-enjoy mo ang merienda mo. Isama mo ang pamilya sa beach. Tumawa ka hanggang sumakit ang tiyan mo sa reunion. Pero hawakan mo ang lahat nang bukas ang palad, at panatilihin mong nakataas ang mga mata mo. Minsan ka lang mabubuhay sa lupang ito. Ipamuhay mo ito sa paraang kapag natapos na ang guhit at binabalasa na ang baraha sa lamay mo, may magsasabing, “Nabuhay siya para kay Hesus,” at sa langit, naghihintay ang mga taong tinulungan mong makarating doon para salubungin ka pauwi."
          ),
        ],
      },
    ],
    pullQuote: t(
      "You only live once; that is exactly why you cannot afford to spend your one life on what will not outlive you.",
      "Minsan ka lang mabubuhay; iyan mismo ang dahilan kung bakit hindi mo kayang gugulin ang iisa mong buhay sa mga bagay na hindi hihigit sa iyo."
    ),
    pastoralWord: [
      t(
        "Beloved, the dash is being written right now, in this ordinary week. I want you to do something tonight before you sleep. Ask yourself, “What did I do today that will matter in eternity?” Some nights the answer will be nothing, and that honesty is the beginning of wisdom. Other nights it will be a prayer for your mother, a kind word to the new kababayan at work, a Bible verse sent to your child. Write it down. Let the list grow.",
        "Minamahal, isinusulat na ngayon ang guhit, sa ordinaryong linggong ito. Gusto kong gumawa ka ng isang bagay ngayong gabi bago ka matulog. Itanong mo sa sarili mo, “Ano ang ginawa ko ngayong araw na may halaga sa walang hanggan?” May mga gabing wala ang sagot, at ang katapatang iyan ang simula ng karunungan. May mga gabing ito ay isang panalangin para sa nanay mo, isang mabait na salita sa bagong kababayan sa trabaho, isang talata ng Bibliya na ipinadala mo sa anak mo. Isulat mo. Hayaan mong humaba ang listahan."
      ),
      t(
        "And if you look back and see years spent on stew, do not sit in regret. Esau could not get back his birthright, but you are not Esau. You belong to a Savior who restores what the locusts have eaten (Joel 2:25). Give Him the years you have left, however many they are. Start today. A life handed to Jesus late is still a life He can fill with eternal things.",
        "At kung lilingon ka at makikita mong maraming taon ang nagugol sa nilaga, huwag kang malugmok sa panghihinayang. Hindi na nabawi ni Esau ang pagkapanganay niya, pero hindi ka si Esau. Pag-aari ka ng Tagapagligtas na nagbabalik ng kinain ng mga balang (Joel 2:25). Ibigay mo sa Kanya ang mga taong natitira, gaano man karami. Magsimula ka ngayon. Ang buhay na ibinigay kay Hesus nang huli ay buhay pa rin na kaya Niyang punuin ng mga bagay na walang hanggan."
      ),
    ],
    benediction: t(
      "May the eternal God teach you to number your days and fill each one with wisdom. May your treasure be stored where no moth or thief can reach it. And when your dash is complete, may you close your eyes on earth and open them in the presence of the risen Christ. Amen.",
      "Turuan ka nawa ng walang hanggang Diyos na bilangin ang iyong mga araw at punuin ang bawat isa ng karunungan. Maimbak nawa ang kayamanan mo sa lugar na hindi maaabot ng gamugamo o ng magnanakaw. At kapag kumpleto na ang guhit mo, ipikit mo nawa ang mga mata mo sa lupa at imulat ang mga ito sa presensya ng muling nabuhay na Cristo. Amen."
    ),
  },

  "c-all-religions-vs-jesus": {
    epigraph: {
      text: t(
        "Jesus said to him, “I am the way, and the truth, and the life. No one comes to the Father except through Me.”",
        "Sinabi sa kanya ni Hesus, “Ako ang daan, at ang katotohanan, at ang buhay. Walang makararating sa Ama malibang sa pamamagitan Ko.”"
      ),
      ref: t("John 14:6", "Juan 14:6"),
    },
    opening: [
      t(
        "Picture the break room in a hospital in the Gulf. At one table, a Filipina nurse unwraps the adobo she cooked last night. Beside her sits a colleague from Kerala who keeps a small image of his god in his locker, a quiet Egyptian who steps out five times a day to pray, and a cheerful young Filipino who stopped going to Mass years ago and now says he is “spiritual but not religious.” They are kind to each other. They cover each other's shifts. One evening the conversation drifts to faith, and someone says what everyone else is thinking: “Pare-pareho lang naman tayo. Iisang Diyos lang 'yan, iba-iba lang ng daan. Basta mabait ka.”",
        "Isipin mo ang break room ng isang ospital sa Gulf. Sa isang mesa, binubuksan ng isang Pilipinang nurse ang adobong niluto niya kagabi. Katabi niya ang isang kasamahang taga-Kerala na may maliit na larawan ng kanyang diyos sa locker, isang tahimik na Ehipsiyong lumalabas nang limang beses isang araw para manalangin, at isang masayahing batang Pilipinong matagal nang hindi nagsisimba at ngayon ay nagsasabing “spiritual but not religious” siya. Mababait sila sa isa't isa. Nagsasaluhan sila sa shift. Isang gabi, napunta ang usapan sa pananampalataya, at may nagsabi ng iniisip ng lahat: “Pare-pareho lang naman tayo. Iisang Diyos lang 'yan, iba-iba lang ng daan. Basta mabait ka.”"
      ),
      t(
        "It sounds so gracious. It keeps the peace. And the nurse, who loves Jesus, feels something tighten in her chest. She does not want to be arrogant. She does not want to lose her friends. But she also remembers the words of her Lord, and they do not sound like “iba-iba lang ng daan.”",
        "Napakabait pakinggan. Napapanatili ang kapayapaan. At ang nurse, na umiibig kay Hesus, ay nakaramdam ng paninikip sa dibdib. Ayaw niyang maging mayabang. Ayaw niyang mawalan ng kaibigan. Pero naaalala rin niya ang mga salita ng kanyang Panginoon, at hindi tunog “iba-iba lang ng daan” ang mga iyon."
      ),
      t(
        "If you have ever been at that table, this chapter is for you. I want to show you why Christians cannot say all religions are the same, and also why the One who said He is the only way is the gentlest, most welcoming Person who ever lived.",
        "Kung naupo ka na sa mesang iyon, para sa iyo ang kabanatang ito. Gusto kong ipakita sa iyo kung bakit hindi masasabi ng mga Kristiyano na pare-pareho ang lahat ng relihiyon, at kung bakit din ang nagsabing Siya lang ang daan ay ang pinakamahinahon at pinakamapagtanggap na Personang nabuhay kailanman."
      ),
    ],
    sections: [
      {
        heading: t("The night He said it", "Ang gabing sinabi Niya ito"),
        body: [
          t(
            "We usually quote John 14:6 as if Jesus shouted it from a stage at His critics. He did not. He said it in a quiet upper room on the night before He died, to eleven frightened friends. Judas had just gone out into the night. Jesus had just told Peter he would deny Him three times. The disciples' hearts were troubled, so He began, “Let not your hearts be troubled. Believe in God; believe also in Me. In My Father's house are many rooms” (John 14:1-2).",
            "Kadalasan, sinisipi natin ang Juan 14:6 na parang isinigaw ito ni Hesus mula sa entablado sa Kanyang mga kritiko. Hindi ganoon. Sinabi Niya ito sa isang tahimik na silid sa itaas noong gabi bago Siya namatay, sa labing-isang takot na kaibigan. Kalalabas lang ni Judas sa dilim. Kasasabi lang ni Hesus kay Pedro na tatlong beses siyang magkakaila sa Kanya. Nababagabag ang puso ng mga alagad, kaya nagsimula Siya, “Huwag mabagabag ang inyong puso. Manampalataya kayo sa Diyos; manampalataya rin kayo sa Akin. Sa bahay ng Aking Ama ay maraming silid” (Juan 14:1-2)."
          ),
          t(
            "Then honest Thomas spoke up: “Lord, we do not know where You are going. How can we know the way?” (14:5). It was a confused question, almost a complaint. And Jesus did not answer, “Here is a set of directions.” He said, “I am the way.” Not I show the way, or I teach about the way. I am it. The road to the Father is not a philosophy or a ritual. It is a Person, and that Person was about to lay down His life to open it.",
            "Saka nagsalita ang tapat na si Tomas: “Panginoon, hindi namin alam kung saan Kayo pupunta. Paano namin malalaman ang daan?” (14:5). Nalilitong tanong ito, halos reklamo. At hindi sumagot si Hesus ng, “Heto ang direksyon.” Sinabi Niya, “Ako ang daan.” Hindi Ako ang nagtuturo ng daan, o Ako ang nagpapaliwanag tungkol sa daan. Ako mismo iyon. Ang daan patungo sa Ama ay hindi pilosopiya o ritwal. Isa itong Persona, at ang Personang iyon ay malapit nang mag-alay ng Kanyang buhay para buksan ito."
          ),
          t(
            "So the exclusive claim of Jesus was first spoken as comfort, not as a weapon. “You are afraid you will not find your way home? You do not need a map. You have Me.” We must never use His words in a tone He never used.",
            "Kaya ang eksklusibong pahayag ni Hesus ay unang sinabi bilang aliw, hindi bilang sandata. “Takot kayong hindi ninyo mahanap ang daan pauwi? Hindi ninyo kailangan ng mapa. Nasa inyo Ako.” Hindi natin dapat gamitin kailanman ang mga salita Niya sa tonong hindi Niya kailanman ginamit."
          ),
        ],
      },
      {
        heading: t("Same rules, different answers", "Parehong patakaran, magkakaibang sagot"),
        body: [
          t(
            "There is a famous parable about several blind men touching an elephant. One feels the trunk and says it is a snake, another the leg and says it is a tree, another the ear and says it is a fan. The point usually drawn is that all religions touch a part of God and none sees the whole. But someone has wisely noticed the problem with that story. The person telling it claims to see the whole elephant. To say “all religions are only partly right” is itself a big religious claim about God.",
            "May kilalang talinghaga tungkol sa ilang bulag na humihipo sa isang elepante. Hinipo ng isa ang nguso at sinabing ahas ito, ng isa ang paa at sinabing puno ito, ng isa ang tainga at sinabing pamaypay ito. Ang karaniwang aral na hinuhugot ay na ang bawat relihiyon ay may nahihipong bahagi ng Diyos at walang nakakikita sa kabuuan. Pero may matalinong nakapansin sa problema ng kuwentong iyan. Ang nagkukuwento mismo ay nagsasabing nakikita niya ang buong elepante. Ang pagsasabing “bahagi lang ang tama sa lahat ng relihiyon” ay isa ring malaking pahayag-relihiyoso tungkol sa Diyos."
          ),
          t(
            "It is true that many religions share moral teachings. Honor your parents. Do not steal. Be kind to strangers. But on the questions that matter most, they do not agree at all. Is God personal, or an impersonal force? Is there one God, many, or none? Who is Jesus: a prophet, an enlightened teacher, a myth, or God in the flesh? Did He die on a cross, or not? Is our problem ignorance, desire, or sin? Are we saved by our efforts, or by grace? These answers contradict each other. They cannot all be true at once.",
            "Totoo na maraming relihiyon ang may magkakatulad na moral na turo. Igalang ang magulang. Huwag magnakaw. Maging mabait sa dayuhan. Pero sa mga tanong na pinakamahalaga, hindi sila nagkakasundo. Personal ba ang Diyos, o isang puwersang walang pagkatao? Iisa ba ang Diyos, marami, o wala? Sino si Hesus: propeta, naliwanagang guro, alamat, o Diyos na nagkatawang-tao? Namatay ba Siya sa krus, o hindi? Ang problema ba natin ay kamangmangan, pagnanasa, o kasalanan? Naliligtas ba tayo sa sarili nating pagsisikap, o sa biyaya? Nagsasalungatan ang mga sagot na ito. Hindi maaaring totoo silang lahat nang sabay."
          ),
          t(
            "Here is something I want you to see. Saying all religions are the same is actually not very respectful. It means you have not listened carefully to what your Hindu, Muslim or Buddhist friend truly believes. They know their faith differs from yours, and they usually hold their convictions with great seriousness. Real respect takes the differences seriously, and then loves people across them.",
            "Narito ang isang bagay na gusto kong makita mo. Ang pagsasabing pare-pareho ang lahat ng relihiyon ay hindi talaga magalang. Ibig sabihin nito ay hindi mo pinakinggang mabuti kung ano talaga ang pinaniniwalaan ng kaibigan mong Hindu, Muslim o Buddhist. Alam nilang iba ang pananampalataya nila sa iyo, at kadalasan ay napakaseryoso nila sa kanilang paniniwala. Sineseryoso ng tunay na paggalang ang mga pagkakaiba, at saka nagmamahal sa mga tao sa kabila ng mga ito."
          ),
        ],
      },
      {
        heading: t("A tower going up, a ladder coming down", "Toreng paakyat, hagdang pababa"),
        body: [
          t(
            "Early in Genesis, people gathered on the plain of Shinar and said, “Come, let us build ourselves a city and a tower with its top in the heavens, and let us make a name for ourselves” (Genesis 11:4). That tower is a picture of human religion at its core: people stacking bricks of effort, hoping to reach high enough to touch God. Pray more, give more, fast more, be good enough, and maybe you will get there.",
            "Sa unang bahagi ng Genesis, nagtipon ang mga tao sa kapatagan ng Sinar at nagsabing, “Halikayo, magtayo tayo ng lungsod at ng toreng ang tuktok ay aabot sa langit, at gumawa tayo ng pangalan para sa ating sarili” (Genesis 11:4). Larawan ang toreng iyon ng relihiyon ng tao sa kaibuturan nito: mga taong nagpapatong-patong ng laryo ng pagsisikap, umaasang makaaabot nang sapat na taas para mahawakan ang Diyos. Manalangin nang mas madalas, magbigay nang mas marami, mag-ayuno nang mas matagal, maging sapat na mabait, at baka makarating ka roon."
          ),
          t(
            "A few chapters later, Jacob is running away from home after deceiving his father. He lies down in the dust with a stone for a pillow, and he dreams of a ladder set up on earth whose top reached heaven, with angels going up and down, and the Lord standing above it, making promises to a man who deserved nothing (Genesis 28:12-15). Do you see the difference? At Babel, people tried to climb up. At Bethel, heaven came down to a sinner who was not even looking for God.",
            "Ilang kabanata pagkatapos, tumatakas si Jacob mula sa tahanan matapos dayain ang kanyang ama. Humiga siya sa alikabok na may batong unan, at nanaginip siya ng isang hagdang nakatayo sa lupa na ang tuktok ay umaabot sa langit, may mga anghel na umaakyat at bumababa, at ang Panginoon ay nakatayo sa itaas nito, nangangako sa isang lalaking walang karapatang tumanggap ng anuman (Genesis 28:12-15). Nakikita mo ba ang pagkakaiba? Sa Babel, sinubukan ng tao na umakyat. Sa Betel, bumaba ang langit sa isang makasalanang hindi man lang naghahanap sa Diyos."
          ),
          t(
            "And Jesus later told Nathanael, “You will see heaven opened, and the angels of God ascending and descending on the Son of Man” (John 1:51). He was saying, “I am Jacob's ladder.” That is the gospel. Not a better tower, but a Savior who came down. “By grace you have been saved through faith. And this is not your own doing; it is the gift of God, not a result of works, so that no one may boast” (Ephesians 2:8-9). Every other path tells you how to climb. Only the gospel tells you that God came down and carried you up.",
            "At kalaunan, sinabi ni Hesus kay Natanael, “Makikita ninyong bukas ang langit, at ang mga anghel ng Diyos na umaakyat at bumababa sa Anak ng Tao” (Juan 1:51). Sinasabi Niya, “Ako ang hagdan ni Jacob.” Iyan ang ebanghelyo. Hindi mas magandang tore, kundi isang Tagapagligtas na bumaba. “Sa biyaya kayo ay naligtas sa pamamagitan ng pananampalataya. At ito ay hindi sa inyong sariling gawa; ito ay kaloob ng Diyos, hindi bunga ng mga gawa, upang walang sinumang makapagmalaki” (Efeso 2:8-9). Bawat ibang daan ay nagsasabi sa iyo kung paano umakyat. Ang ebanghelyo lang ang nagsasabing bumaba ang Diyos at binuhat ka pataas."
          ),
          t(
            "That is why “basta mabait ka” is not good news at all. How kind is kind enough? Kinder than your neighbor? Kind every day of your life? The tower never reaches heaven. But the ladder does, because it is not built from our side. “There is one God, and there is one mediator between God and men, the man Christ Jesus, who gave Himself as a ransom for all” (1 Timothy 2:5-6).",
            "Kaya ang “basta mabait ka” ay hindi mabuting balita. Gaano kabait ang sapat? Mas mabait kaysa sa kapitbahay mo? Mabait araw-araw sa buong buhay mo? Hindi kailanman umaabot sa langit ang tore. Pero umaabot ang hagdan, dahil hindi ito itinayo mula sa ating panig. “May iisang Diyos, at may iisang tagapamagitan sa Diyos at sa mga tao, ang taong si Cristo Hesus, na ibinigay ang Kanyang sarili bilang pantubos para sa lahat” (1 Timoteo 2:5-6)."
          ),
        ],
      },
      {
        heading: t("Two fishermen before the council", "Dalawang mangingisda sa harap ng konseho"),
        body: [
          t(
            "The other great verse of this chapter, Acts 4:12, has a dramatic setting. Peter and John had healed a man lame from birth at the temple gate. The man was leaping and praising God, and a crowd gathered. The two apostles were arrested and brought before the same council that had condemned Jesus only weeks earlier: Annas, Caiaphas and the high priestly family. The question was blunt: “By what power or by what name did you do this?” (Acts 4:7).",
            "Ang isa pang dakilang talata ng kabanatang ito, ang Gawa 4:12, ay may madramang tagpuan. Pinagaling nina Pedro at Juan ang isang lalaking lumpo mula pagkapanganak sa pintuan ng templo. Lumulukso ang lalaki at nagpupuri sa Diyos, at nagtipon ang maraming tao. Inaresto ang dalawang apostol at dinala sa harap ng mismong konsehong humatol kay Hesus ilang linggo pa lang ang nakararaan: si Anas, si Caifas at ang pamilya ng mataas na saserdote. Diretso ang tanong: “Sa anong kapangyarihan o sa anong pangalan ninyo ginawa ito?” (Gawa 4:7)."
          ),
          t(
            "Remember who Peter was. A few weeks before, in a courtyard near this same high priest's house, he had denied even knowing Jesus to a servant girl. Now, filled with the Holy Spirit, he stood before the most powerful men in the nation and said, “By the name of Jesus Christ of Nazareth, whom you crucified, whom God raised from the dead... There is salvation in no one else, for there is no other name under heaven given among men by which we must be saved” (4:10-12).",
            "Alalahanin mo kung sino si Pedro. Ilang linggo pa lang ang nakararaan, sa isang patyo malapit sa bahay ng mismong mataas na saserdoteng ito, ikinaila niya sa isang alilang babae na kilala niya si Hesus. Ngayon, puspos ng Espiritu Santo, tumayo siya sa harap ng pinakamakapangyarihang mga lalaki sa bansa at nagsabing, “Sa pangalan ni Hesu-Cristo na taga-Nazaret, na inyong ipinako sa krus, na ibinangon ng Diyos mula sa mga patay... Walang kaligtasan sa iba, sapagkat walang ibang pangalan sa ilalim ng langit na ibinigay sa mga tao na sa pamamagitan nito ay dapat tayong maligtas” (4:10-12)."
          ),
          t(
            "The council was astonished, Luke says, because they saw that these were “uneducated, common men,” and they recognized “that they had been with Jesus” (4:13). That is the secret of their boldness. They were not winning a debate. They were testifying about Someone they had seen die and seen alive again. When you share Jesus at the break room table, you do not need a theology degree. You need to have been with Him.",
            "Namangha ang konseho, sabi ni Lucas, dahil nakita nilang ang mga ito ay “mga taong walang pinag-aralan at karaniwan,” at nakilala nilang “nakasama nila si Hesus” (4:13). Iyan ang sikreto ng tapang nila. Hindi sila nananalo sa debate. Nagpapatotoo sila tungkol sa Isang nakita nilang namatay at nakita nilang buhay muli. Kapag ibinabahagi mo si Hesus sa mesa ng break room, hindi mo kailangan ng degree sa teolohiya. Kailangan mong nakasama Siya."
          ),
        ],
      },
      {
        heading: t("Gentleness and respect, from Athens to the Gulf", "Kahinahunan at paggalang, mula Atenas hanggang sa Gulf"),
        body: [
          t(
            "When Paul arrived in Athens, “his spirit was provoked within him as he saw that the city was full of idols” (Acts 17:16). Yet when he stood to speak at the Areopagus, he did not begin with insults. He began, “Men of Athens, I perceive that in every way you are very religious” (17:22). He had walked their streets and read the inscription on their altar “To the unknown god.” He quoted their own poets. And then, having built a bridge of respect, he walked across it and told them about the risen Christ who will judge the world.",
            "Nang dumating si Pablo sa Atenas, “nabagabag ang kanyang espiritu nang makita niyang puno ng diyus-diyosan ang lungsod” (Gawa 17:16). Pero nang tumayo siya para magsalita sa Areopago, hindi siya nagsimula sa pang-iinsulto. Nagsimula siya, “Mga taga-Atenas, nakikita kong sa lahat ng paraan ay napakarelihiyoso ninyo” (17:22). Nilakad niya ang kanilang mga kalye at binasa ang nakasulat sa kanilang altar, “Sa diyos na hindi kilala.” Sinipi niya ang sarili nilang mga makata. At pagkatapos, nang makapagtayo ng tulay ng paggalang, tinawid niya ito at sinabi sa kanila ang tungkol sa muling nabuhay na Cristo na hahatol sa sanlibutan."
          ),
          t(
            "Peter, who once cut off a man's ear with a sword, later wrote the rule for every believer: “In your hearts honor Christ the Lord as holy, always being prepared to make a defense to anyone who asks you for a reason for the hope that is in you; yet do it with gentleness and respect” (1 Peter 3:15). Notice: to anyone who asks. Your life should be the kind that makes people ask.",
            "Si Pedro, na minsang pumutol ng tainga ng isang lalaki gamit ang tabak, ay sumulat kalaunan ng patakaran para sa bawat mananampalataya: “Sa inyong mga puso ay igalang ninyo si Cristo bilang banal na Panginoon, laging handang magtanggol sa sinumang nagtatanong sa inyo ng dahilan ng pag-asang nasa inyo; ngunit gawin ito nang may kahinahunan at paggalang” (1 Pedro 3:15). Pansinin mo: sa sinumang nagtatanong. Dapat ang buhay mo ay ang uri ng buhay na nagpapatanong sa mga tao."
          ),
          t(
            "For many OFWs, there is another layer of wisdom. You may be working in a country with strict laws about religion. Honor those laws and be wise, as Jesus said, “wise as serpents and innocent as doves” (Matthew 10:16). You can still pray daily for your colleagues by name. You can serve them with excellence and kindness. You can be the one who does not gossip, who covers the extra shift, who stays calm in a crisis. And when someone quietly asks why you have such peace, you can say, simply and gently, “Because of Jesus. Can I tell you what He did for me?”",
            "Para sa maraming OFW, may isa pang patong ng karunungan. Baka nagtatrabaho ka sa bansang may mahigpit na batas tungkol sa relihiyon. Igalang mo ang mga batas na iyon at maging marunong, gaya ng sinabi ni Hesus, “maingat gaya ng ahas at walang malay gaya ng kalapati” (Mateo 10:16). Kaya mo pa ring ipanalangin araw-araw sa pangalan ang mga kasamahan mo. Kaya mo pa rin silang paglingkuran nang may kahusayan at kabaitan. Puwede kang maging ang hindi nakikitsismis, ang sumasalo sa dagdag na shift, ang nananatiling kalmado sa krisis. At kapag may tahimik na nagtanong kung bakit ganoon ang kapayapaan mo, puwede mong sabihin nang simple at mahinahon, “Dahil kay Hesus. Puwede ko bang ikuwento ang ginawa Niya para sa akin?”"
          ),
        ],
      },
    ],
    pullQuote: t(
      "Sincerity can carry you across a bridge only if the bridge is real.",
      "Kaya kang itawid ng sinseridad sa isang tulay kung totoo lang ang tulay."
    ),
    pastoralWord: [
      t(
        "Beloved, if you have quietly drifted into believing that all roads lead to God, I do not condemn you. It is an easy place to drift when you love people who believe differently. But I ask you to go back to the upper room and listen again to the One who said, “I am the way.” He did not say it to shut people out. He said it while getting ready to die so the door could be opened to anyone. Let that settle in your heart until your conviction becomes gratitude.",
        "Minamahal, kung tahimik kang nadala sa paniniwalang lahat ng daan ay papunta sa Diyos, hindi kita hinahatulan. Madaling madala roon kapag mahal mo ang mga taong iba ang paniniwala. Pero hinihiling kong bumalik ka sa silid sa itaas at pakinggan muli ang nagsabing, “Ako ang daan.” Hindi Niya ito sinabi para isara ang pinto sa mga tao. Sinabi Niya ito habang naghahandang mamatay para mabuksan ang pinto sa kahit sino. Hayaan mong tumimo ito sa puso mo hanggang maging pasasalamat ang paninindigan mo."
      ),
      t(
        "Then choose one person of another faith, or of no faith, and begin to pray for them by name every day this week. Ask God to let you love them well. Prepare a short, simple account of what Jesus has done for you, in your own words, short enough to tell over a cup of coffee. You do not need to win an argument. You only need to be ready, gentle and faithful. The Spirit who filled two fishermen before the council will give you the words when the door opens.",
        "Pagkatapos, pumili ka ng isang taong iba ang pananampalataya, o walang pananampalataya, at simulan mo siyang ipanalangin sa pangalan araw-araw ngayong linggo. Hilingin mo sa Diyos na matulungan kang mahalin siya nang mabuti. Maghanda ka ng maikli at simpleng salaysay ng ginawa ni Hesus para sa iyo, sa sarili mong salita, sapat ang ikli para maikuwento habang nagkakape. Hindi mo kailangang manalo sa pagtatalo. Kailangan mo lang maging handa, mahinahon at tapat. Ang Espiritung pumuspos sa dalawang mangingisda sa harap ng konseho ang magbibigay sa iyo ng mga salita kapag bumukas ang pinto."
      ),
    ],
    benediction: t(
      "May Jesus, the Way, keep your feet on the road that leads home. May He make you bold like Peter and gentle like your Lord. And may many who sit at your table someday sit with you at His. Amen.",
      "Si Hesus, ang Daan, ang mag-ingat nawa sa mga paa mo sa landas pauwi. Gawin ka nawa Niyang matapang gaya ni Pedro at mahinahon gaya ng iyong Panginoon. At ang marami nawang nakaupo sa mesa mo ay maupo kasama mo balang araw sa mesa Niya. Amen."
    ),
  },

  "c-karma-vs-grace": {
    epigraph: {
      text: t(
        "He does not deal with us according to our sins, nor repay us according to our iniquities.",
        "Hindi Niya tayo pinakitunguhan ayon sa ating mga kasalanan, ni ginantihan ayon sa ating mga kasamaan."
      ),
      ref: t("Psalm 103:10", "Awit 103:10"),
    },
    opening: [
      t(
        "Picture a jeepney stuck in the long line on the highway at rush hour. A private car swerves onto the shoulder, overtakes twenty vehicles, and cuts in right in front. Everyone in the jeepney groans. Five minutes later, a traffic enforcer steps out and flags the car down. The whole jeepney erupts. “Karma!” someone shouts, and the passengers laugh and clap like the Ginebra just won.",
        "Isipin mo ang isang jeepney na nakapila sa mahabang trapik sa highway sa rush hour. Biglang lumiko sa balikat ng daan ang isang pribadong kotse, nilampasan ang dalawampung sasakyan, at sumingit mismo sa harap. Napaungol ang lahat sa jeepney. Makalipas ang limang minuto, may traffic enforcer na lumabas at pinara ang kotse. Nagsigawan ang buong jeepney. “Karma!” sigaw ng isa, at nagtawanan at nagpalakpakan ang mga pasahero na parang nanalo ang Ginebra."
      ),
      t(
        "I will admit it. There is something in us that loves that moment. We have a hunger for things to be set right, and when the cheater gets caught, it feels like the universe is working properly. So we say it about the ex who cheated, the boss who stole our overtime, the relative who borrowed and never paid: “May balik 'yan. Bahala na ang karma sa kanya.”",
        "Aaminin ko. May bahagi sa atin na gustong-gusto ang sandaling iyon. May gutom tayo na maituwid ang mga bagay, at kapag nahuli ang nandaraya, parang tama ang takbo ng sansinukob. Kaya sinasabi natin ito tungkol sa ex na nagtaksil, sa amo na nagnakaw ng overtime natin, sa kamag-anak na nangutang at hindi nagbayad: “May balik 'yan. Bahala na ang karma sa kanya.”"
      ),
      t(
        "But let me ask you a question, and answer it honestly in your heart. Do you want karma for yourself? Do you want every word you have spoken in anger, every lie, every secret thing done in the dark, to come back to you in full? I have never met a person who did. We love karma for other people. For ourselves, we want something else entirely. And that something else has a name.",
        "Pero hayaan mong magtanong ako, at sagutin mo nang tapat sa puso mo. Gusto mo ba ng karma para sa sarili mo? Gusto mo bang bumalik sa iyo nang buo ang bawat salitang binitiwan mo sa galit, bawat kasinungalingan, bawat lihim na ginawa mo sa dilim? Wala pa akong nakilalang taong gusto iyon. Gusto natin ang karma para sa ibang tao. Para sa sarili natin, iba ang gusto natin. At may pangalan ang ibang iyon."
      ),
    ],
    sections: [
      {
        heading: t("Where the word comes from", "Saan galing ang salita"),
        body: [
          t(
            "Karma is a word from the ancient religions of India. It means “deed” or “action,” and in those traditions it names a moral law that works like gravity. Every deed returns to the doer. Good brings good and evil brings evil, if not in this life then in the next, through cycle after cycle of rebirth. No one stands behind the law to forgive. No one interrupts it. It is fair in a cold way, like a machine that never makes a mistake and never shows mercy.",
            "Ang karma ay salita mula sa sinaunang mga relihiyon ng India. Ang ibig sabihin nito ay “gawa,” at sa mga tradisyong iyon, ito ang pangalan ng isang moral na batas na gumagana na parang grabidad. Bumabalik sa gumawa ang bawat gawa. Mabuti ang ibinubunga ng mabuti at masama ang ibinubunga ng masama, kung hindi man sa buhay na ito ay sa susunod, sa paulit-ulit na siklo ng muling pagsilang. Walang nakatayo sa likod ng batas para magpatawad. Walang humahadlang dito. Patas ito sa malamig na paraan, gaya ng makinang hindi nagkakamali at hindi rin naaawa."
          ),
          t(
            "Many of our Indian and Nepali friends in the Gulf hold this belief sincerely, and we should speak of it with respect. But we should also see clearly that it is not what the Bible teaches. Scripture does agree that actions have consequences. “Do not be deceived: God is not mocked, for whatever one sows, that will he also reap” (Galatians 6:7). Lies do catch up. Drunkenness does destroy the liver. Infidelity does break homes. The harvest is real.",
            "Marami sa mga kaibigan nating Indian at Nepali sa Gulf ang taimtim na naniniwala rito, at dapat natin itong pag-usapan nang may paggalang. Pero dapat din nating makita nang malinaw na hindi ito ang itinuturo ng Bibliya. Sang-ayon nga ang Kasulatan na may bunga ang mga gawa. “Huwag kayong padaya: hindi napaglalaruan ang Diyos, sapagkat anuman ang ihasik ng tao, iyon din ang kanyang aanihin” (Galacia 6:7). Talagang nahahabol ang kasinungalingan. Talagang sinisira ng paglalasing ang atay. Talagang winawasak ng pagtataksil ang tahanan. Totoo ang ani."
          ),
          t(
            "But notice who Paul names in that verse. Not a law. God. The harvest is governed by a Person, and that changes everything. A law cannot forgive. A Person can. A law cannot weep over the sinner. A Person can. A law cannot step into the field and take the harvest upon Himself. And that is exactly what our God did.",
            "Pero pansinin mo kung sino ang binanggit ni Pablo sa talatang iyon. Hindi batas. Diyos. Isang Persona ang namamahala sa ani, at binabago niyan ang lahat. Hindi kayang magpatawad ng batas. Kaya ng isang Persona. Hindi kayang iyakan ng batas ang makasalanan. Kaya ng isang Persona. Hindi kayang pumasok ng batas sa bukid at akuin ang ani. At iyan mismo ang ginawa ng ating Diyos."
          ),
        ],
      },
      {
        heading: t("Who sinned, this man or his parents?", "Sino ang nagkasala, ang taong ito o ang mga magulang niya?"),
        body: [
          t(
            "Karma thinking is not only an Asian idea. It was alive among Jesus' own disciples. One Sabbath in Jerusalem they passed a man who had been blind from birth, probably sitting by the road with his hand out. And the disciples, looking at him the way you might look at a puzzle, asked, “Rabbi, who sinned, this man or his parents, that he was born blind?” (John 9:2). They assumed someone must be paying for something.",
            "Hindi lang ideyang Asyano ang pag-iisip na karma. Buhay ito sa mismong mga alagad ni Hesus. Isang Sabbath sa Jerusalem, nadaanan nila ang isang lalaking bulag mula pagkapanganak, malamang nakaupo sa tabi ng daan at nakalahad ang kamay. At ang mga alagad, na tumitingin sa kanya na parang palaisipan, ay nagtanong, “Rabi, sino ang nagkasala, ang taong ito o ang kanyang mga magulang, kaya ipinanganak siyang bulag?” (Juan 9:2). Ipinalagay nilang may nagbabayad para sa isang bagay."
          ),
          t(
            "Jesus' answer must have startled them: “It was not that this man sinned, or his parents, but that the works of God might be displayed in him” (9:3). Then He spat on the ground, made mud, anointed the man's eyes, and sent him to wash in the pool of Siloam. The man came back seeing. Where the disciples saw a case to be explained, Jesus saw a person to be healed and a stage for the glory of God.",
            "Tiyak na ikinagulat nila ang sagot ni Hesus: “Hindi dahil nagkasala ang taong ito o ang kanyang mga magulang, kundi upang mahayag sa kanya ang mga gawa ng Diyos” (9:3). Saka Siya dumura sa lupa, gumawa ng putik, pinahiran ang mga mata ng lalaki, at pinapunta siya para maghugas sa paliguan ng Siloe. Bumalik ang lalaki na nakakikita na. Kung saan nakakita ang mga alagad ng kasong dapat ipaliwanag, nakakita si Hesus ng taong dapat pagalingin at ng entablado para sa kaluwalhatian ng Diyos."
          ),
          t(
            "Job's friends made the same mistake chapter after chapter. “Who that was innocent ever perished?” Eliphaz asked (Job 4:7). They sat with Job in the ashes and lectured him that he must have done something. In the end God said to them, “You have not spoken of Me what is right” (42:7). Hear me, beloved. When a typhoon flattens a barangay, when a child is born with a disability, when a faithful OFW comes home in a box, do not open your mouth to say “baka karma.” Open your arms. Open your wallet. Open your home. That is what the Lord does.",
            "Ganito rin ang pagkakamali ng mga kaibigan ni Job sa sunud-sunod na kabanata. “Sinong walang sala ang namatay kailanman?” tanong ni Elifaz (Job 4:7). Umupo sila kasama ni Job sa abo at sinermunan siya na tiyak may ginawa siya. Sa dulo, sinabi sa kanila ng Diyos, “Hindi kayo nagsalita nang tama tungkol sa Akin” (42:7). Pakinggan mo ako, minamahal. Kapag dinapa ng bagyo ang isang barangay, kapag may batang ipinanganak na may kapansanan, kapag umuwi sa kahon ang isang tapat na OFW, huwag mong buksan ang bibig mo para sabihing “baka karma.” Buksan mo ang mga bisig mo. Buksan mo ang pitaka mo. Buksan mo ang tahanan mo. Iyan ang ginagawa ng Panginoon."
          ),
          t(
            "Some suffering is the fruit of sin; David's household reaped bitterly after his adultery and murder (2 Samuel 12:10). But much suffering is simply the groaning of a broken world, and some of it, like the blind man's, is God preparing to show His glory. When people told Jesus about Galileans whom Pilate had killed and eighteen people crushed by a falling tower, He asked, “Do you think they were worse offenders than all the others?... No, I tell you; but unless you repent, you will all likewise perish” (Luke 13:4-5). Jesus turned the question from them to us. Not “What did they do?” but “Are you ready?”",
            "May paghihirap na bunga ng kasalanan; mapait ang inani ng sambahayan ni David pagkatapos ng kanyang pangangalunya at pagpatay (2 Samuel 12:10). Pero ang maraming paghihirap ay daing lang ng isang sirang mundo, at ang ilan, gaya ng sa lalaking bulag, ay paghahanda ng Diyos para ipakita ang Kanyang kaluwalhatian. Nang ikuwento kay Hesus ang mga taga-Galileang pinatay ni Pilato at ang labing-walong nadaganan ng bumagsak na tore, nagtanong Siya, “Akala ba ninyo ay mas makasalanan sila kaysa sa lahat ng iba?... Hindi, sinasabi Ko sa inyo; ngunit malibang magsisi kayo, mapapahamak din kayong lahat” (Lucas 13:4-5). Ibinaling ni Hesus ang tanong mula sa kanila papunta sa atin. Hindi “Ano ang ginawa nila?” kundi “Handa ka na ba?”"
          ),
        ],
      },
      {
        heading: t("The God who does not keep score", "Ang Diyos na hindi nagbibilang ng puntos"),
        body: [
          t(
            "Now listen to an old king singing. David had more reasons than most men to fear payback. He had taken another man's wife and arranged that man's death. And yet in Psalm 103 he cannot stop praising: “Bless the Lord, O my soul, and forget not all His benefits, who forgives all your iniquity, who heals all your diseases, who redeems your life from the pit” (103:2-4).",
            "Pakinggan mo ngayon ang isang matandang haring umaawit. Mas marami ang dahilan ni David kaysa sa karamihan para matakot sa ganti. Kinuha niya ang asawa ng ibang lalaki at ipinapatay ang lalaking iyon. Pero sa Awit 103, hindi siya mapigil sa pagpupuri: “Purihin mo ang Panginoon, O kaluluwa ko, at huwag mong kalimutan ang lahat ng Kanyang mga kabutihan, na nagpapatawad sa lahat ng iyong kasamaan, na nagpapagaling sa lahat ng iyong sakit, na tumutubos sa iyong buhay mula sa hukay” (103:2-4)."
          ),
          t(
            "Then comes the verse at the head of this chapter: “He does not deal with us according to our sins, nor repay us according to our iniquities” (103:10). Read that slowly. It is the exact opposite of karma. And David gives the measurements: “As high as the heavens are above the earth, so great is His steadfast love toward those who fear Him; as far as the east is from the west, so far does He remove our transgressions from us” (103:11-12). You can travel north until you reach the pole and start going south. But you can travel east forever and never start going west. That is how far.",
            "Saka dumating ang talatang nasa simula ng kabanatang ito: “Hindi Niya tayo pinakitunguhan ayon sa ating mga kasalanan, ni ginantihan ayon sa ating mga kasamaan” (103:10). Basahin mo nang dahan-dahan. Eksaktong kabaligtaran ito ng karma. At ibinigay ni David ang sukat: “Kung gaano kataas ang langit sa ibabaw ng lupa, gayon kadakila ang Kanyang tapat na pag-ibig sa mga natatakot sa Kanya; kung gaano kalayo ang silangan sa kanluran, gayon kalayo Niyang inalis sa atin ang ating mga pagsalangsang” (103:11-12). Puwede kang maglakbay pahilaga hanggang marating mo ang dulo at magsimulang pumunta patimog. Pero puwede kang maglakbay pasilangan magpakailanman at hindi ka magsisimulang pumunta pakanluran. Ganyan kalayo."
          ),
          t(
            "That is grace. Mercy is God not giving us what we deserve. Grace is God giving us what we could never deserve. Karma says, “You get exactly what you earned.” The gospel says, “Your account has been settled by Another.” If karma were the final law of the universe, heaven would be empty, because every one of us has sown things we would never want to reap.",
            "Iyan ang biyaya. Ang awa ay ang hindi pagbibigay ng Diyos ng nararapat sa atin. Ang biyaya ay ang pagbibigay ng Diyos ng hindi natin kailanman magiging karapat-dapat tanggapin. Sinasabi ng karma, “Makukuha mo ang eksaktong pinaghirapan mo.” Sinasabi ng ebanghelyo, “Binayaran na ng Iba ang utang mo.” Kung karma ang huling batas ng sansinukob, walang laman ang langit, dahil bawat isa sa atin ay nagtanim ng mga bagay na hindi natin gustong anihin kailanman."
          ),
        ],
      },
      {
        heading: t("The place where payback fell", "Ang lugar kung saan bumagsak ang ganti"),
        body: [
          t(
            "Do not misunderstand me. God does not simply ignore evil. That would not be love; it would be indifference. A God who shrugged at trafficking, abuse and murder would not be good. The Bible insists that every sin will be paid for. The question is only by whom.",
            "Huwag mo akong mamali ng intindi. Hindi basta binabalewala ng Diyos ang kasamaan. Hindi iyon pag-ibig; kawalang-pakialam iyon. Ang Diyos na nagkikibit-balikat sa human trafficking, pang-aabuso at pagpatay ay hindi mabuti. Ipinipilit ng Bibliya na mababayaran ang bawat kasalanan. Ang tanong lang ay kung sino ang magbabayad."
          ),
          t(
            "Seven hundred years before Calvary, Isaiah saw it: “He was pierced for our transgressions; He was crushed for our iniquities; upon Him was the chastisement that brought us peace, and with His wounds we are healed” (Isaiah 53:5). At the cross, the payback was real. The whole weight of what humanity had sown fell on the only Man who had sown nothing but good. And Paul marvels, “God shows His love for us in that while we were still sinners, Christ died for us” (Romans 5:8). Not after we cleaned up. While we were still sinners.",
            "Pitong daang taon bago ang Kalbaryo, nakita na ito ni Isaias: “Siya'y sinugatan dahil sa ating mga pagsalangsang; dinurog Siya dahil sa ating mga kasamaan; nasa Kanya ang parusang nagdulot sa atin ng kapayapaan, at sa Kanyang mga sugat ay gumaling tayo” (Isaias 53:5). Sa krus, totoo ang ganti. Ang buong bigat ng inihasik ng sangkatauhan ay bumagsak sa nag-iisang Taong walang inihasik kundi kabutihan. At namamangha si Pablo, “Ipinakita ng Diyos ang Kanyang pag-ibig sa atin sa ganito: noong tayo'y makasalanan pa, namatay si Cristo para sa atin” (Roma 5:8). Hindi pagkatapos nating magpakabait. Noong makasalanan pa tayo."
          ),
          t(
            "Remember the two criminals crucified beside Jesus. By any law of karma, they were getting exactly what they deserved. One of them admitted it: “We are receiving the due reward of our deeds; but this Man has done nothing wrong.” Then he turned his head and said, “Jesus, remember me when You come into Your kingdom.” And Jesus, dying, said, “Truly, I say to you, today you will be with Me in paradise” (Luke 23:41-43). A thief who had nothing left to offer received everything. That is the most un-karmic sentence ever spoken, and it is the heart of the gospel.",
            "Alalahanin mo ang dalawang kriminal na ipinako sa tabi ni Hesus. Sa anumang batas ng karma, nakukuha nila ang eksaktong nararapat sa kanila. Inamin ito ng isa sa kanila: “Tinatanggap natin ang nararapat na ganti sa ating mga gawa; ngunit ang Taong ito ay walang ginawang masama.” Saka niya ibinaling ang ulo at nagsabing, “Hesus, alalahanin Mo ako kapag dumating Ka sa Iyong kaharian.” At si Hesus, habang naghihingalo, ay nagsabing, “Tunay na sinasabi Ko sa iyo, ngayon din ay makakasama kita sa paraiso” (Lucas 23:41-43). Ang magnanakaw na wala nang maiaalok ay tumanggap ng lahat. Iyan ang pinakasalungat sa karma na pangungusap na nabigkas kailanman, at iyan ang puso ng ebanghelyo."
          ),
        ],
      },
      {
        heading: t("Leaving room for the Judge", "Pagbibigay-puwang sa Hukom"),
        body: [
          t(
            "So what do we do with the people who have wronged us? Paul answers: “Repay no one evil for evil... Beloved, never avenge yourselves, but leave it to the wrath of God, for it is written, ‘Vengeance is Mine, I will repay, says the Lord.’ To the contrary, ‘if your enemy is hungry, feed him; if he is thirsty, give him something to drink'... Do not be overcome by evil, but overcome evil with good” (Romans 12:17-21).",
            "Kaya ano ang gagawin natin sa mga taong nagkasala sa atin? Sumagot si Pablo: “Huwag gantihan ng masama ang masama... Mga minamahal, huwag kayong maghiganti, kundi ipaubaya ninyo ito sa poot ng Diyos, sapagkat nasusulat, ‘Akin ang paghihiganti, Ako ang gaganti, sabi ng Panginoon.’ Sa halip, ‘kung nagugutom ang iyong kaaway, pakainin mo siya; kung nauuhaw, painumin mo siya'... Huwag kayong padaig sa masama, kundi daigin ninyo ng mabuti ang masama” (Roma 12:17-21)."
          ),
          t(
            "Be honest. Often “bahala na ang karma sa kanya” is not surrender at all. It is revenge outsourced. We cannot hurt the person ourselves, so we wait and hope the universe will. We check their profile. We smile a little when we hear bad news. That is not leaving room for God. That is keeping our hands on the stone and asking someone else to throw it. Paul says something harder and freer: let go of the stone completely. Give the case to the Judge who sees everything, and then go feed your enemy.",
            "Maging tapat ka. Madalas, ang “bahala na ang karma sa kanya” ay hindi talaga pagsuko. Paghihigantiing ipinasa sa iba. Hindi natin kayang saktan ang tao, kaya naghihintay tayo at umaasang gagawin iyon ng sansinukob. Sinisilip natin ang profile niya. Napapangiti tayo nang kaunti kapag may masamang balita. Hindi iyan pagbibigay-puwang sa Diyos. Iyan ay paghawak pa rin sa bato at pakikiusap sa iba na ibato ito. Mas mahirap at mas nakapagpapalaya ang sinasabi ni Pablo: bitawan mo nang tuluyan ang bato. Ibigay mo ang kaso sa Hukom na nakakikita ng lahat, saka mo pakainin ang kaaway mo."
          ),
          t(
            "In 1947, Corrie ten Boom, who had survived the Ravensbrück concentration camp where her sister Betsie died, spoke about God's forgiveness in a church in Munich. Afterward a man came forward whom she recognized as one of the cruel guards from the camp. He told her he had become a Christian and asked if she would forgive him, and he held out his hand. She later wrote that she stood there unable to lift her arm, feeling nothing but coldness, and silently prayed for help. As she mechanically put out her hand, she felt warmth and love flood through her, and she was able to say, “I forgive you, brother, with all my heart.” She wrote that it was not her own love; it was God's.",
            "Noong 1947, si Corrie ten Boom, na nakaligtas sa kampong piitan ng Ravensbrück kung saan namatay ang kapatid niyang si Betsie, ay nagsalita tungkol sa kapatawaran ng Diyos sa isang simbahan sa Munich. Pagkatapos, may lumapit na lalaking nakilala niyang isa sa malulupit na bantay sa kampo. Sinabi nitong naging Kristiyano na siya at tinanong kung mapapatawad siya ni Corrie, at inilahad niya ang kamay. Isinulat ni Corrie kalaunan na nakatayo siya roon na hindi maitaas ang braso, walang nararamdaman kundi lamig, at tahimik na humingi ng tulong sa panalangin. Habang parang makinang iniaabot niya ang kamay, naramdaman niyang dumaloy sa kanya ang init at pag-ibig, at nasabi niya, “Pinatatawad kita, kapatid, nang buong puso.” Isinulat niyang hindi iyon sarili niyang pag-ibig; sa Diyos iyon."
          ),
          t(
            "That is the end of karma. Not a universe that settles accounts by itself, but a crucified and risen Judge who settled them on a cross, and who now pours His own love into hands that could not otherwise open. Leaving vengeance to God does not mean you never report a crime or seek protection; God gave authorities for justice (Romans 13:4). It means you refuse to carry the poison of revenge in your own heart. You hand it to Him. And then you are free.",
            "Iyan ang katapusan ng karma. Hindi isang sansinukob na kusang nag-aayos ng mga talaan, kundi isang ipinako at muling nabuhay na Hukom na nag-ayos ng mga ito sa krus, at ngayon ay nagbubuhos ng sarili Niyang pag-ibig sa mga kamay na kung hindi dahil sa Kanya ay hindi makabubukas. Ang pagpapaubaya sa Diyos ng paghihiganti ay hindi nangangahulugang hindi ka na magre-report ng krimen o hihingi ng proteksyon; nagbigay ang Diyos ng mga awtoridad para sa katarungan (Roma 13:4). Ibig sabihin nito ay tumatanggi kang pasanin ang lason ng paghihiganti sa sarili mong puso. Ibinibigay mo ito sa Kanya. At saka ka magiging malaya."
          ),
        ],
      },
    ],
    pullQuote: t(
      "We love karma for other people; for ourselves we beg for grace, and grace is exactly what God offers at the cross.",
      "Gusto natin ang karma para sa ibang tao; para sa sarili natin, nagmamakaawa tayo para sa biyaya, at biyaya mismo ang inaalok ng Diyos sa krus."
    ),
    pastoralWord: [
      t(
        "Beloved, maybe you have been living under karma without knowing it. Every time something goes wrong you think, “Pinaparusahan ako ng Diyos.” You are afraid of the payback for your past. Hear me: if you are in Christ, the payback has already fallen, and it fell on Him. Your sickness is not a bill God is collecting. Your hardship is not karma catching up. You are a child being carried by a Father who removed your sins as far as the east is from the west. Lift your head.",
        "Minamahal, baka namumuhay ka sa ilalim ng karma nang hindi mo namamalayan. Tuwing may nangyayaring masama, naiisip mo, “Pinaparusahan ako ng Diyos.” Takot ka sa ganti ng nakaraan mo. Pakinggan mo ako: kung nasa kay Cristo ka, bumagsak na ang ganti, at sa Kanya ito bumagsak. Hindi singil ng Diyos ang sakit mo. Hindi karmang humahabol ang hirap mo. Anak ka na binubuhat ng Amang nag-alis ng mga kasalanan mo nang kasinlayo ng silangan sa kanluran. Itaas mo ang ulo mo."
      ),
      t(
        "And maybe there is a name you have been holding, someone you are waiting to see fall. Write that name down this week. Pray over it, honestly, telling God everything that person did. Then write beside it, “Ibinigay ko na sa Hukom,” and ask Him for one good thing you can do for that person, even if it is only a prayer for their salvation. You will find that the stone you finally let go of was heavier for you than it ever would have been for them.",
        "At baka may pangalang hawak-hawak mo, isang taong hinihintay mong bumagsak. Isulat mo ang pangalang iyon ngayong linggo. Ipanalangin mo ito nang tapat, sinasabi sa Diyos ang lahat ng ginawa ng taong iyon. Saka mo isulat sa tabi nito, “Ibinigay ko na sa Hukom,” at hilingin mo sa Kanya ang isang mabuting bagay na magagawa mo para sa taong iyon, kahit panalangin lang para sa kanyang kaligtasan. Matutuklasan mong ang batong sa wakas ay binitawan mo ay mas mabigat pala para sa iyo kaysa sa magiging bigat nito sa kanya."
      ),
    ],
    benediction: t(
      "May the God who has not dealt with you according to your sins fill you with wonder at His grace. May every wrong done to you rest in the hands of the just Judge. And may you go out and overcome evil with good, as one who has been loved beyond all deserving. Amen.",
      "Ang Diyos na hindi nakitungo sa iyo ayon sa iyong mga kasalanan ay punuin ka nawa ng pagkamangha sa Kanyang biyaya. Ang bawat maling ginawa sa iyo nawa'y mapanatag sa mga kamay ng makatarungang Hukom. At nawa'y humayo ka at daigin ng mabuti ang masama, bilang isang minahal nang higit sa lahat ng nararapat. Amen."
    ),
  },

  "c-walang-forever-vs-steadfast-love": {
    epigraph: {
      text: t(
        "The steadfast love of the Lord never ceases; His mercies never come to an end; they are new every morning; great is Your faithfulness.",
        "Ang tapat na pag-ibig ng Panginoon ay hindi tumitigil; ang Kanyang mga habag ay hindi natatapos; bago ang mga ito tuwing umaga; dakila ang Iyong katapatan."
      ),
      ref: t("Lamentations 3:22-23", "Panaghoy 3:22-23"),
    },
    opening: [
      t(
        "Picture a small chapel in the province on a bright Saturday morning. Plastic flowers on the pews, a borrowed sound system, a groom in a barong that is a little too big for him and a bride whose hands will not stop shaking. They say the vows: “sa hirap at ginhawa, sa sakit at kalusugan, hanggang kamatayan.” Everyone cries. Everyone believes it.",
        "Isipin mo ang isang maliit na kapilya sa probinsya sa isang maaliwalas na Sabado ng umaga. Mga plastik na bulaklak sa mga upuan, hiniram na sound system, isang lalaking naka-barong na medyo maluwag sa kanya at isang babaeng hindi mapigil ang panginginig ng mga kamay. Binibigkas nila ang mga pangako: “sa hirap at ginhawa, sa sakit at kalusugan, hanggang kamatayan.” Umiiyak ang lahat. Naniniwala ang lahat."
      ),
      t(
        "Now picture the same couple eight years later. He is in Jeddah on his third contract. She is in the province with two children and a mother-in-law. The video calls that used to last two hours now last ten minutes, and most of it is about the padala. He has a co-worker who listens to him. She has an old classmate who messages her late at night. Nobody planned anything. But somewhere along the way, without a single dramatic night, they became strangers. And on her phone, a meme she shared months ago still sits in her timeline: “Walang forever.”",
        "Ngayon, isipin mo ang parehong mag-asawa makalipas ang walong taon. Nasa Jeddah ang lalaki, nasa ikatlong kontrata na. Nasa probinsya ang babae kasama ang dalawang anak at ang biyenan. Ang mga video call na dating dalawang oras ay sampung minuto na lang ngayon, at karamihan ay tungkol sa padala. May katrabaho ang lalaki na nakikinig sa kanya. May dating kaklase ang babae na nagme-message sa kanya sa hatinggabi. Walang nagplano ng anuman. Pero sa kung saang bahagi ng daan, nang walang iisang madramang gabi, naging estranghero sila sa isa't isa. At sa cellphone ng babae, nasa timeline pa rin ang meme na ibinahagi niya ilang buwan na ang nakararaan: “Walang forever.”"
      ),
      t(
        "We laugh at that hugot line in films and at the barkada table. But beloved, behind the laugh there is a wound. It is the hugot of a generation that has watched promises break: parents who separated, partners who cheated, families scattered across the world. This last chapter is for every heart that has quietly concluded that nothing lasts. I want to tell you about a love that does.",
        "Tinatawanan natin ang hugot line na iyan sa mga pelikula at sa mesa ng barkada. Pero minamahal, may sugat sa likod ng tawa. Hugot ito ng isang henerasyong nakasaksi ng mga napakong pangako: mga magulang na naghiwalay, karelasyong nagtaksil, mga pamilyang nagkalat sa buong mundo. Ang huling kabanatang ito ay para sa bawat pusong tahimik nang nagpasyang walang nagtatagal. Gusto kong ikuwento sa iyo ang isang pag-ibig na nagtatagal."
      ),
    ],
    sections: [
      {
        heading: t("A song sung among the ruins", "Awit na inawit sa gitna ng mga guho"),
        body: [
          t(
            "The words at the head of this chapter were not written on a sunny day. The book of Lamentations is a funeral song for a city. Babylon had besieged Jerusalem until people starved, then burned the temple and dragged the survivors into exile. The writer, traditionally Jeremiah, walks through the ashes and pours out grief poem after poem. “He has made my teeth grind on gravel, and made me cower in ashes; my soul is bereft of peace” (Lamentations 3:16-17).",
            "Hindi isinulat sa isang maaraw na araw ang mga salita sa simula ng kabanatang ito. Isang awit ng paglilibing para sa isang lungsod ang aklat ng Panaghoy. Kinubkob ng Babilonia ang Jerusalem hanggang magutom ang mga tao, saka sinunog ang templo at kinaladkad ang mga nakaligtas sa pagkabihag. Ang sumulat, na ayon sa tradisyon ay si Jeremias, ay naglalakad sa abo at nagbubuhos ng pighati, tula pagkatapos ng tula. “Pinangatngat Niya ang aking mga ngipin sa graba, at pinayuko ako sa abo; nawalan ng kapayapaan ang aking kaluluwa” (Panaghoy 3:16-17)."
          ),
          t(
            "And then, right in the middle of the book, in the middle of the ashes, he says, “But this I call to mind, and therefore I have hope: The steadfast love of the Lord never ceases; His mercies never come to an end; they are new every morning; great is Your faithfulness” (3:21-23). Notice what he does not say. He does not say, “Things are fine.” The city is still burned. He says that underneath the ruins there is something that did not burn. God's love.",
            "At pagkatapos, sa mismong gitna ng aklat, sa gitna ng abo, sinabi niya, “Ngunit ito ang aking inaalala, kaya ako'y may pag-asa: Ang tapat na pag-ibig ng Panginoon ay hindi tumitigil; ang Kanyang mga habag ay hindi natatapos; bago ang mga ito tuwing umaga; dakila ang Iyong katapatan” (3:21-23). Pansinin mo ang hindi niya sinabi. Hindi niya sinabing, “Ayos na ang lahat.” Sunog pa rin ang lungsod. Ang sinabi niya, sa ilalim ng mga guho ay may isang bagay na hindi nasunog. Ang pag-ibig ng Diyos."
          ),
          t(
            "The word he uses is the Hebrew hesed. There is no perfect English or Tagalog word for it. It is love bound to a promise, loyal love, covenant love, love that keeps showing up even when the other side has failed. Israel had broken covenant again and again. God's hesed had not broken. That is why the writer can find a morning in the middle of the night.",
            "Ang salitang ginamit niya ay ang Hebreong hesed. Walang perpektong salita sa Ingles o Tagalog para dito. Ito ay pag-ibig na nakatali sa pangako, tapat na pag-ibig, tipang pag-ibig, pag-ibig na patuloy na dumarating kahit nabigo na ang kabilang panig. Paulit-ulit na sinira ng Israel ang tipan. Hindi nasira ang hesed ng Diyos. Kaya nakahanap ang sumulat ng umaga sa gitna ng gabi."
          ),
        ],
      },
      {
        heading: t("Twenty-six times, in case we forget", "Dalawampu't anim na beses, baka sakaling makalimot tayo"),
        body: [
          t(
            "Psalm 136 is perhaps the most repetitive song in the Bible, and that is its genius. It walks through history line by line. God made the heavens: “for His steadfast love endures forever.” He spread out the earth: “for His steadfast love endures forever.” He struck Egypt, brought Israel out, divided the Red Sea, led them through the wilderness: “for His steadfast love endures forever.” Twenty-six verses, twenty-six times, the same refrain, probably sung back and forth between a leader and the congregation.",
            "Ang Awit 136 ay marahil ang pinakamapag-ulit na awit sa Bibliya, at iyan ang galing nito. Isa-isang nilalakad nito ang kasaysayan. Nilikha ng Diyos ang kalangitan: “sapagkat ang Kanyang tapat na pag-ibig ay magpakailanman.” Inilatag Niya ang lupa: “sapagkat ang Kanyang tapat na pag-ibig ay magpakailanman.” Hinampas Niya ang Egipto, inilabas ang Israel, hinati ang Dagat na Pula, inakay sila sa ilang: “sapagkat ang Kanyang tapat na pag-ibig ay magpakailanman.” Dalawampu't anim na talata, dalawampu't anim na beses, iisang koro, malamang na inaawit nang pabalik-balik ng isang tagapanguna at ng kongregasyon."
          ),
          t(
            "Why repeat it so often? Because the human heart forgets. We remember every person who left. We remember the exact words of the breakup message. But we forget the thousand mornings God's mercy met us. The psalm trains the memory. When the Levites brought the ark into Solomon's temple, they sang this refrain, and the glory of God filled the house (2 Chronicles 5:13-14). When King Jehoshaphat faced an enormous army, he sent singers ahead of the soldiers singing these same words (2 Chronicles 20:21). In celebration and in danger, the song was the same.",
            "Bakit ito inuulit nang ganoon kadalas? Dahil nakalilimot ang puso ng tao. Naaalala natin ang bawat taong umalis. Naaalala natin ang eksaktong salita ng break-up message. Pero nalilimutan natin ang libu-libong umagang sinalubong tayo ng awa ng Diyos. Sinasanay ng awit ang alaala. Nang ipasok ng mga Levita ang kaban sa templo ni Solomon, inawit nila ang koro na ito, at pinuno ng kaluwalhatian ng Diyos ang bahay (2 Cronica 5:13-14). Nang humarap si Haring Jehoshafat sa napakalaking hukbo, nagpadala siya ng mga mang-aawit sa unahan ng mga sundalo na umaawit ng mga salitang ito (2 Cronica 20:21). Sa pagdiriwang at sa panganib, iisa ang awit."
          ),
          t(
            "So here is my counsel to the person who says “walang forever.” Write your own Psalm 136. Start with the day you were born and walk forward. The time you were sick and recovered. The job that came through. The night you thought you could not go on and somehow woke up. After each line, write the refrain. You will discover that there has been a forever running through your whole life, and you did not notice because you were looking at people instead of at God.",
            "Kaya ito ang payo ko sa taong nagsasabing “walang forever.” Isulat mo ang sarili mong Awit 136. Magsimula ka sa araw na ipinanganak ka at maglakad pasulong. Ang panahong nagkasakit ka at gumaling. Ang trabahong natuloy. Ang gabing akala mo hindi ka na makapagpapatuloy pero nagising ka pa rin. Pagkatapos ng bawat linya, isulat mo ang koro. Matutuklasan mong may forever na tumatakbo sa buong buhay mo, at hindi mo lang napansin dahil sa tao ka nakatingin sa halip na sa Diyos."
          ),
        ],
      },
      {
        heading: t("A prophet told to love again", "Isang propetang inutusang magmahal muli"),
        body: [
          t(
            "If you want to see what hesed looks like with skin on, read the strangest love story in the Bible. God told the prophet Hosea to marry a woman named Gomer, knowing she would be unfaithful (Hosea 1:2). She was. She left him for other lovers. And then God said something no marriage counselor would say: “Go again, love a woman who is loved by another man and is an adulteress, even as the Lord loves the children of Israel, though they turn to other gods” (3:1).",
            "Kung gusto mong makita ang hitsura ng hesed na may laman at buto, basahin mo ang pinakakakaibang kuwento ng pag-ibig sa Bibliya. Inutusan ng Diyos si propeta Oseas na pakasalan ang isang babaeng nagngangalang Gomer, alam na magiging hindi tapat ito (Oseas 1:2). Naging ganoon nga. Iniwan siya nito para sa ibang mangingibig. At saka sinabi ng Diyos ang isang bagay na hindi sasabihin ng kahit sinong marriage counselor: “Humayo ka muli, ibigin mo ang isang babaeng iniibig ng ibang lalaki at mangangalunya, gaya ng pag-ibig ng Panginoon sa mga anak ng Israel, kahit bumabaling sila sa ibang mga diyos” (3:1)."
          ),
          t(
            "Hosea went. He found her, and it seems she had fallen so low she was being sold. He paid fifteen shekels of silver and some barley to buy back his own wife (3:2). Picture him counting out the coins in the marketplace while people whispered, then walking her home. That was not weakness. It was a sermon preached with his whole life: this is how God loves His unfaithful people.",
            "Pumunta si Oseas. Natagpuan niya ito, at mukhang bumagsak na ito nang husto at ipinagbibili na. Nagbayad siya ng labinlimang siklong pilak at kaunting sebada para tubusin ang sarili niyang asawa (3:2). Isipin mo siyang nagbibilang ng barya sa pamilihan habang nagbubulungan ang mga tao, saka inakay ito pauwi. Hindi iyon kahinaan. Isang sermon iyon na ipinangaral ng buo niyang buhay: ganito magmahal ang Diyos sa Kanyang bayang hindi tapat."
          ),
          t(
            "And it points to something greater. Every one of us is Gomer. We have run after other loves: money, approval, pleasure, our own way. And God did not stand at a distance and say, “Walang forever.” He came to the marketplace Himself. He paid not with silver but, as Peter wrote, “with the precious blood of Christ, like that of a lamb without blemish or spot” (1 Peter 1:18-19). John says of Jesus on the night before the cross, “Having loved His own who were in the world, He loved them to the end” (John 13:1). To the end. That is forever love.",
            "At may itinuturo itong mas dakila. Bawat isa sa atin ay si Gomer. Hinabol natin ang ibang mga pag-ibig: pera, pagsang-ayon ng tao, kalayawan, sarili nating gusto. At hindi tumayo sa malayo ang Diyos para sabihing, “Walang forever.” Siya mismo ang pumunta sa pamilihan. Nagbayad Siya hindi ng pilak kundi, gaya ng isinulat ni Pedro, “ng mahalagang dugo ni Cristo, gaya ng sa korderong walang kapintasan o dungis” (1 Pedro 1:18-19). Sinabi ni Juan tungkol kay Hesus noong gabi bago ang krus, “Dahil inibig Niya ang sariling Kanya na nasa sanlibutan, inibig Niya sila hanggang sa wakas” (Juan 13:1). Hanggang sa wakas. Iyan ang forever na pag-ibig."
          ),
        ],
      },
      {
        heading: t("Covenant in a contract world", "Tipan sa mundo ng kontrata"),
        body: [
          t(
            "Our world runs on contracts. OFWs know this better than anyone. A contract has terms, a duration and an exit clause. If the employer does not pay, you may leave. If you do not perform, you may be sent home. Contracts are good and necessary for business. The problem comes when we bring contract thinking into love. “I will stay as long as you make me happy. I will be faithful as long as you are.” That is not a vow. That is a two-year contract with an option to renew.",
            "Kontrata ang nagpapatakbo sa mundo natin. Alam ito ng mga OFW nang higit sa kaninuman. May mga tuntunin ang kontrata, may tagal, at may exit clause. Kung hindi magbayad ang amo, puwede kang umalis. Kung hindi ka magtrabaho nang maayos, puwede kang pauwiin. Mabuti at kailangan ang kontrata sa negosyo. Ang problema ay kapag dinala natin sa pag-ibig ang pag-iisip na kontrata. “Mananatili ako hangga't pinasasaya mo ako. Magiging tapat ako hangga't tapat ka.” Hindi iyan pangako sa kasal. Iyan ay dalawang-taong kontrata na may option to renew."
          ),
          t(
            "God sees marriage differently. Through Malachi He confronted men who were casually divorcing their wives: “The Lord was witness between you and the wife of your youth, to whom you have been faithless, though she is your companion and your wife by covenant... So guard yourselves in your spirit” (Malachi 2:14-15). And when the Pharisees asked Jesus for the grounds of divorce, He took them back to the garden: “The two shall become one flesh... What therefore God has joined together, let not man separate” (Matthew 19:5-6). A covenant is not “as long as you.” It is “I bind myself to you, before God.”",
            "Iba ang pagtingin ng Diyos sa pag-aasawa. Sa pamamagitan ni Malakias, hinarap Niya ang mga lalaking basta-basta na lang hinihiwalayan ang asawa nila: “Ang Panginoon ay naging saksi sa pagitan mo at ng asawa ng iyong kabataan, na pinagtaksilan mo, bagaman siya ang iyong kasama at asawa mo sa tipan... Kaya ingatan ninyo ang inyong sarili sa inyong espiritu” (Malakias 2:14-15). At nang tanungin ng mga Pariseo si Hesus tungkol sa mga dahilan ng paghihiwalay, ibinalik Niya sila sa hardin: “Ang dalawa ay magiging isang laman... Kaya ang pinagsama ng Diyos ay huwag paghiwalayin ng tao” (Mateo 19:5-6). Hindi “hangga't ikaw” ang tipan. Ito ay “Itinatali ko ang sarili ko sa iyo, sa harap ng Diyos.”"
          ),
          t(
            "Notice Malachi's phrase again: guard yourselves in your spirit. Marriages rarely end in one night. They end in a thousand small neglects. The couple in Jeddah and the province did not need a miracle; they needed a guard. A fixed time each day to pray together, even five minutes. Honest talk about loneliness before someone else fills the space. No secret chats, no hidden money. Friends in their churches who are allowed to ask, “Kumusta kayo talaga?” Distance will test any marriage. But a covenant guarded in the spirit can carry a couple across any ocean.",
            "Pansinin mo ulit ang parirala ni Malakias: ingatan ninyo ang inyong sarili sa inyong espiritu. Bihirang matapos ang pagsasama sa iisang gabi. Natatapos ito sa libu-libong maliliit na pagpapabaya. Hindi himala ang kailangan ng mag-asawang nasa Jeddah at sa probinsya; bantay ang kailangan nila. May takdang oras araw-araw para manalangin nang magkasama, kahit limang minuto. Tapat na usapan tungkol sa kalungkutan bago pa may ibang pumuno sa puwang. Walang lihim na chat, walang nakatagong pera. Mga kaibigan sa simbahan na pinahihintulutang magtanong, “Kumusta kayo talaga?” Susubukin ng distansya ang anumang pagsasama. Pero ang tipang iniingatan sa espiritu ay kayang magtawid sa mag-asawa sa anumang karagatan."
          ),
          t(
            "I must say this gently, because some of you have already been through the breaking. Faithful Christians differ on exactly when divorce and remarriage are permitted, but all agree that God heals and receives the divorced and the abandoned, and that no one is called to stay in a place of violence. If you are in danger, seek safety and the help of your pastor and the proper authorities. The God of hesed does not ask you to prove your faithfulness by being destroyed. He is your refuge too.",
            "Kailangan kong sabihin ito nang mahinahon, dahil may ilan sa inyong nakaranas na ng pagkasira. Nagkakaiba ang mga tapat na Kristiyano kung kailan eksaktong pinahihintulutan ang paghihiwalay at muling pag-aasawa, pero lahat ay sumasang-ayon na pinagagaling at tinatanggap ng Diyos ang mga hiwalay at iniwan, at walang tinatawag na manatili sa lugar ng karahasan. Kung nasa panganib ka, humanap ka ng kaligtasan at ng tulong ng iyong pastor at ng tamang awtoridad. Hindi hinihiling ng Diyos ng hesed na patunayan mo ang katapatan mo sa pamamagitan ng pagkawasak. Siya rin ang kanlungan mo."
          ),
        ],
      },
      {
        heading: t("The love that never ends", "Ang pag-ibig na hindi nagwawakas"),
        body: [
          t(
            "Paul's famous chapter on love is read at almost every Filipino wedding, but it was written to a quarreling church, not a romantic couple. “Love is patient and kind; love does not envy or boast... it is not irritable or resentful... Love bears all things, believes all things, hopes all things, endures all things. Love never ends” (1 Corinthians 13:4-8). Read it again and notice there is almost nothing about feelings in it. It is a description of choices: to wait, to be kind, to not keep a record of wrongs, to keep going.",
            "Binabasa ang tanyag na kabanata ni Pablo tungkol sa pag-ibig sa halos bawat kasalang Pilipino, pero isinulat ito para sa isang simbahang nag-aaway, hindi para sa romantikong magkasintahan. “Ang pag-ibig ay matiyaga at mabait; ang pag-ibig ay hindi naiinggit o nagmamayabang... hindi magagalitin at hindi mapagtanim ng sama ng loob... Ang pag-ibig ay nagtitiis ng lahat ng bagay, nananampalataya sa lahat ng bagay, umaasa sa lahat ng bagay, nagbabata ng lahat ng bagay. Ang pag-ibig ay hindi nagwawakas” (1 Corinto 13:4-8). Basahin mo ulit at mapapansin mong halos walang tungkol sa damdamin dito. Paglalarawan ito ng mga pagpili: maghintay, maging mabait, huwag magtala ng mga pagkakamali, magpatuloy."
          ),
          t(
            "Can anyone love like that? Not on their own. That is why Paul also wrote, “God's love has been poured into our hearts through the Holy Spirit who has been given to us” (Romans 5:5). The forever love we cannot produce, He pours in. And He promises that nothing will cut us off from its source: “Neither death nor life, nor angels nor rulers, nor things present nor things to come... nor anything else in all creation, will be able to separate us from the love of God in Christ Jesus our Lord” (Romans 8:38-39).",
            "May tao bang kayang magmahal nang ganyan? Wala, kung sa sarili lang niyang lakas. Kaya isinulat din ni Pablo, “Ibinuhos ang pag-ibig ng Diyos sa ating mga puso sa pamamagitan ng Espiritu Santo na ibinigay sa atin” (Roma 5:5). Ang forever na pag-ibig na hindi natin kayang likhain, Siya ang nagbubuhos. At ipinangangako Niyang walang makapuputol sa atin mula sa pinagmumulan nito: “Kahit ang kamatayan o ang buhay, ang mga anghel o ang mga pinuno, ang mga bagay sa kasalukuyan o ang mga darating... o ang anumang iba pa sa buong nilikha, ay hindi makapaghihiwalay sa atin sa pag-ibig ng Diyos na kay Cristo Hesus na ating Panginoon” (Roma 8:38-39)."
          ),
          t(
            "Think of Peter on the shore of Galilee after the resurrection. He had promised to die for Jesus and then denied Him three times beside a charcoal fire. Now, early in the morning, there is another charcoal fire, with fish on it and bread, and the risen Jesus is cooking breakfast for the man who failed Him (John 21:9). Three times He asks, “Do you love Me?” Three times Peter answers, and three times Jesus gives him back his calling. The smell of that fire must have reminded Peter of his worst night. Jesus let the same smell become the memory of his restoration.",
            "Isipin mo si Pedro sa baybayin ng Galilea pagkatapos ng muling pagkabuhay. Nangako siyang mamamatay para kay Hesus pero tatlong beses Siyang ikinaila sa tabi ng apoy ng uling. Ngayon, maaga sa umaga, may isa pang apoy ng uling, may isda at tinapay sa ibabaw, at ang muling nabuhay na si Hesus ay nagluluto ng almusal para sa lalaking bumigo sa Kanya (Juan 21:9). Tatlong beses Siyang nagtanong, “Iniibig mo ba Ako?” Tatlong beses sumagot si Pedro, at tatlong beses ibinalik sa kanya ni Hesus ang kanyang tawag. Tiyak na ipinaalala kay Pedro ng amoy ng apoy na iyon ang pinakamasamang gabi niya. Hinayaan ni Hesus na ang parehong amoy ang maging alaala ng kanyang pagpapanumbalik."
          ),
          t(
            "So here is my answer to the hugot. The world is right about itself. Everything under the sun passes away. Even the best marriage on earth ends at the grave, for Jesus said there is no marrying in the resurrection (Matthew 22:30). But that is exactly the point. Every faithful marriage, every kept promise, every friend who stayed, is a signpost pointing beyond itself to the love of Christ for His people, the one marriage that will never end (Ephesians 5:31-32). There is a forever. It has a name. And He has already said, “I will never leave you nor forsake you” (Hebrews 13:5).",
            "Kaya ito ang sagot ko sa hugot. Tama ang mundo tungkol sa sarili nito. Lumilipas ang lahat ng nasa ilalim ng araw. Kahit ang pinakamagandang pagsasama sa lupa ay natatapos sa libingan, dahil sinabi ni Hesus na walang pag-aasawa sa muling pagkabuhay (Mateo 22:30). Pero iyan mismo ang punto. Bawat tapat na pagsasama, bawat pangakong tinupad, bawat kaibigang nanatili, ay karatulang nagtuturo lampas sa sarili nito, sa pag-ibig ni Cristo sa Kanyang bayan, ang nag-iisang kasal na hindi kailanman matatapos (Efeso 5:31-32). May forever. May pangalan ito. At sinabi na Niya, “Hindi kita iiwan ni pababayaan man” (Hebreo 13:5)."
          ),
        ],
      },
    ],
    pullQuote: t(
      "The world is right that nothing under the sun lasts forever; it is wrong about the One who made the sun.",
      "Tama ang mundo na walang nasa ilalim ng araw na nagtatagal magpakailanman; mali ito tungkol sa Lumikha ng araw."
    ),
    pastoralWord: [
      t(
        "Beloved, if you have been hurt so deeply that you stopped believing in forever, I will not argue with your pain. I have sat with too many broken hearts to do that. But I will ask you to let God be the exception. Every promise people broke, He has kept. Every time someone walked out, He stayed. Tomorrow morning, before you touch your phone, say Lamentations 3:22-23 out loud and look for one new mercy that day. Then do it again the next morning. Let the refrain of Psalm 136 slowly become the refrain of your life.",
        "Minamahal, kung nasaktan ka nang sobrang lalim na tumigil ka nang maniwala sa forever, hindi ako makikipagtalo sa sakit mo. Masyado nang maraming wasak na pusong sinamahan ko para gawin iyon. Pero hihilingin kong hayaan mong maging eksepsyon ang Diyos. Bawat pangakong binali ng tao, tinupad Niya. Bawat pagkakataong may umalis, nanatili Siya. Bukas ng umaga, bago mo hawakan ang cellphone mo, sabihin mo nang malakas ang Panaghoy 3:22-23 at maghanap ka ng isang bagong habag sa araw na iyon. Gawin mo ulit sa susunod na umaga. Hayaan mong dahan-dahang maging koro ng buhay mo ang koro ng Awit 136."
      ),
      t(
        "And if you are married, especially across the miles, do not wait for a crisis. This week, set a time to pray together, even five minutes on a video call. Close the one door you know is open: the chat, the hidden expense, the friendship that has gone too close. Tell your spouse something you are grateful for. You are not only protecting a marriage. You are preaching, the way Hosea did, a sermon to your children and to a cynical generation: there is a love that keeps its promise. And it comes from the God whose steadfast love endures forever.",
        "At kung may asawa ka, lalo na kung magkalayo kayo, huwag mo nang hintayin ang krisis. Ngayong linggo, magtakda kayo ng oras para manalangin nang magkasama, kahit limang minuto sa video call. Isara mo ang nag-iisang pintong alam mong bukas: ang chat, ang nakatagong gastos, ang pakikipagkaibigang sobra nang lapit. Sabihin mo sa asawa mo ang isang bagay na ipinagpapasalamat mo. Hindi lang pag-aasawa ang iniingatan mo. Nangangaral ka, gaya ng ginawa ni Oseas, ng isang sermon sa mga anak mo at sa isang mapang-uyam na henerasyon: may pag-ibig na tumutupad sa pangako. At nagmumula ito sa Diyos na ang tapat na pag-ibig ay magpakailanman."
      ),
    ],
    benediction: t(
      "May the Lord whose steadfast love endures forever meet you with new mercies every morning. May He heal every place where broken promises have wounded you, and make you faithful in every promise you have made. And may you rest, today and forever, in the love from which nothing can separate you. Amen.",
      "Salubungin ka nawa ng Panginoon, na ang tapat na pag-ibig ay magpakailanman, ng mga bagong habag tuwing umaga. Pagalingin nawa Niya ang bawat bahaging sinugatan ng mga napakong pangako, at gawin kang tapat sa bawat pangakong binitiwan mo. At magpahinga ka nawa, ngayon at magpakailanman, sa pag-ibig na walang anumang makapaghihiwalay sa iyo. Amen."
    ),
  },
};
